/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250512-5","meetingId":"r07-cm05","date":"2025年5月12日","dateIso":"2025-05-12","committee":"総務委員会","time":"午後 １時００分～午後 ３時０９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"キッチンカー活用事業の実施","agenda":"キッチンカー活用事業の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"このキッチンカーが有効だというお話ですが、大災害が起きたら、食料品、調理用の油、様々な調味料をはじめ、そろわないと思うのですが、これ、災害時協力体制と言われますけど、本当にこのキッチンカー、物が入ってこないのに有効利用というのは可能なのですか。必ず食品がここから仕入れられる、油もここから持ってこられるという体制ができているということなのですか。それについて教えてください。","respondent":"佐藤経理課長","answer":"災害時の対応のところでのご質問かと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"水の入手、それから、ガソリンの入手も一時的にほとんど止まってしまう状況だと思います。確かに蓄電池などは車に積んでいるかと思いますが、やはり食料品などをどこから仕入れるのだ、水はどこからどうなのだということもきちんと一つ予定を組んで、区民が安心してキッチンカーに頼れるような仕組みづくりをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そこの考え方をお聞きしたいということ。７２.４％の方々、これ職員だと思うのですけれども、よかったということなのですが、まず、試行のときの業者の満足度はどうだったのか。要は売上げはどうだったのかなということ。なので、これをどう考えているのかなと。ただ単にテイクアウトという考え方なのか、それとも、何かしらベンチを置くなり何なり、食べるところをつくるのか、その辺はいかがでしょうか。","respondent":"佐藤経理課長","answer":"仲介事業者を使って出店する際の事業者との関係というところですけれども、一つは、行政としましても、試行実施のときはホームページに出して、職員が対応したのですが、やはり調整ですとか、あるいはその事業者がどういう事業者なのかというのが分からないところもあったので。","voiceIndex":8,"id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"試行ではある程度満足いったということなのでしょうけれども、仲介業者が入るということになると、売上げなどにも関係してくると思うのです。なので、それが実際の販売価のところに付加されてくると、少しまた試行と違う状況が出てくるのではないかと思うのです。でもいっぱいですよね。これは意見なので、参考にしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松本委員","kind":"提案","question":"先ほど、仲介業者を使うのか個別で契約するのかどちらがいいのかというところの中で、やはり管理の部分が結構大変というところがあったかと思うのですけれども、恐らく、こうした管理の部分というのは、災害時のことも検討されてこちらの業者を選ばれているのではないかと思いますが、現時点で具体的に品川区で何か災害が起こったときにどういうスキームを提案されているというか。","respondent":"佐藤経理課長","answer":"事業者選定のときにどのぐらいのキッチンカーを確保するというか協力体制が取れているかというところも、非常に多く抱えていると聞いておりますので、すぐには枯渇するようなことはないのかなというのは認識しております。","voiceIndex":11,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"なぜ、仲介業者を入れるようになったのかを伺いたいのと、この仲介業者が、出店業者の管理等を委託ということで、この出店業者に何かあった際、また、事故やトラブル等があった際というのは、全てこの仲介業者が対応する、場所を貸しているというところでは品川区にもご意見などが出されることになるかと思うのですけれども、管理というところでの責任は、もうこの仲介業者であって、区は。","respondent":"佐藤経理課長","answer":"損害があった場合は二重三重に保険に加入していて、それによって賠償するといった体制も説明を受けておりますので、そういった点でも優れていると考えております。","voiceIndex":13,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。事故とか、やはり食品を提供するところなので食中毒などというものが起きたときに、区がスペースの有効活用ということで貸して、その中でも事故やトラブルということになってくると、すごくいろいろ区が対応することも出てくるかなと思うのですけれども、そういった場合の区の対応というのは何かすることになるのか、伺いたいと思います。","respondent":"佐藤経理課長","answer":"そうした中で、キッチンカーについて事故が起きた場合に、仲介事業者として、その前提として一定のマニュアルを作ったりですとか、あるいは保健所を通して許可を受けているわけなのですけれども。","voiceIndex":15,"id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"それと１点だけ、見ているとすごい並ぶのですよね。本当に並んでいて、待ち時間も大変だろうなと。待っている間に昼休みが終わってしまうのではないのかなと思いながら、上からのぞかせていただいているのですけれど、例えば皆さん１２時に、当たり前ですけれど、たくさん来るではないですか。","respondent":"佐藤経理課長","answer":"保健所からの指導等もあって、作り置きというのは食中毒の危険があるので、そこはできないと聞いておりますので、一定程度限界はあるのかなとは思いますけれども、事業者と話す中でもそういった声があるというところは伝えておりますので、なかなか難しい点ではあると思いますが。","voiceIndex":17,"id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"１点だけ、これを１年間やった中で、効果測定というのはどのようにしていくのでしょうか。こういうものをやると、官民でいろいろやっていくと、利用者側の視点とか区民側の視点というのが少し落ちる可能性があるなというところでは、そういったところも含めて、意見を聞くとか、この効果がどうだったかというのは、どうやっていくのか教えていただければと思います。","respondent":"佐藤経理課長","answer":"事業者側からですので、売上げがどうだったかですとか、あるいは何か意見があるかどうかというところは集計していただいて、区に提供いただけると聞いておりますので、そういったものを活用しながら、事業の効果について判定していきたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。そういう意味では、どういったデータが出せるのか、いろいろ考えていただいて、利用される方が職員が多いようであれば、改めてそういったアンケートを取るとか、区民向けのアンケートを取るとか、そういったこともできるのかなと思いますので、いろいろ考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻副委員長","kind":"提案","question":"そうすると、テイクアウトがメインということですが、例えばそこの場でテーブルなどを出していただいて、区民の方がそこで食事をできるような、時期にもよると思います、梅雨時期とか、暑い時期とかを避けた中で、そこで食事をしていただくということも必要なのかなと思うのですが、先ほどの事業者とのやり取りの中では、事業者のほうもテイクアウトを主として考えているということだったのですが。","respondent":"佐藤経理課長","answer":"２点目に、試行実施のときの、職員の利用についてはアンケートを取りましたけれども一般の区民の方はどうだったかというところです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"食べるところや、区民への周知というところに関しては、そうするとここはもう委託をするということなので、事業者に一つはその考え方、やり方というのはお任せをするといいますか、そこは投げかけるというような仕組みが今回の取組ということでの認識でよろしいですかね。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"１点だけ。２階に食堂がありますよね。ほとんどこれは職員をターゲットにしているということだと思う、区民の方も多少いらっしゃると思うのですけれど、そうなってくると、２階の食堂の利用者が少なくなっていくのではないのかな。そうするとある程度、売上げが下がってくれば、では２階の食堂は閉鎖、見直しをする考えも出てくるのかなと思いますが、その辺何か考えがあるのでしょうか。","respondent":"宮尾人事課長","answer":"昨年、キッチンカーの試行実施ということで、その期間の実績、売上げにどう影響したかというところを見ていたのですが、その期間だけ食堂の売上げが下がったとか、そういった傾向は見られなかったですので、今回も。","voiceIndex":27,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、当面は並列でやっていただきたいなと思います。あまり影響がなければそれはそれで両方とも続行できるかと思うので、あまり極端になってしまうとやはり見直しを図らなければいけないというような状況になり得るかと思うのですけれど、いろいろ状況を見ながらということなので、それを注視しながら、でもサービス低下にならないようによろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"}]},{"id":"topic-02","title":"令和７年度定額減税しきれないと見込まれる方への給付金（不足額給付）の支給","agenda":"令和７年度定額減税しきれないと見込まれる方への給付金（不足額給付）の支給","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それでさらにこういう不足分が生じた場合の対応というのが出てくる、そういう政策だったのだなというところでは、私たちも当時から、消費税の減税等、やはりそういうところで暮らしを守るべきだというふうに訴えてきましたので、こうしたまた、不足分を対応しなくてはいけないというところでは、ご苦労さまですという思いですけれども、４番の不足額給付の対象者と支給額というところで。","respondent":"宮澤税務課長","answer":"６月２日を基準日として算出して金額等を出すところですが、予算上、給付金に関しましては８億７,０００万円余を予算としております。特にＡの方に該当する、不足が生じた方というのは扶養人数等で控除額等が変わりますので、算出してみてその金額が出てくるです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。ですので、今も本当に暮らしがまだまだ、これまで以上に物価高騰等で苦しい状況ですので、引き続きの減税策、私たちは消費税減税が一番だと思っていますけれども、区としてもぜひ求めていただきたいなと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"すみません、非常に分かりづらいです。減税というのは分かったのですけれど、減税し切れない額とか、なぜそういうことが起きるのかなということ。それから、合計所得金額１,８０５万円以下の方ということなのですけれど、この仕組みをもう少し教えてもらえないでしょうか。どういう方々が対象で、どういう方々に支払われるのか、なぜそういうことが起きるのかということを教えてください。","respondent":"宮澤税務課長","answer":"仕組みの部分を説明しますと、昨年度定額減税が実施されまして、所得税と住民税、合わせて４万円になります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"少し分かったような気がしますけれど。逆の方はどうなってしまうのですか、それはなしなのでしょうか。","respondent":"宮澤税務課長","answer":"令和６年中の収入が、所得等が仮に大きくなった場合に関しましては、国の方針としまして、返還等は検討しないというふうになってありますので、返還等は特段ないです。","voiceIndex":40,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"これ、定額減税というふうに、去年ですか報告があったときに、先ほども質問がありましたけれどもすごく煩雑で、結局、職員の手を考えたら本当に、事務量が多くなってきて大変だよねという話をしていたのです。それを教えてください。","respondent":"宮澤税務課長","answer":"事務を執行するに当たりましては、事業者等に委託等を活用しております。今回その金額につきましては、１億３００万円余の委託費を計上しております。それらの事務経費につきましては、１０分の１０補助金で賄える形になっております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"この仕組みは、やるときに相当そこが問題だったのです、手間がかかるよね、みたいな形で。だからこれは国に対してですが、もう少し分かりやすいような、やりやすいような、そういう内容のものにしていただければなという、これは意見なので、別にここで言っても皆さんどうすることもないと思いますが、私の意見として少し言わせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"松本委員","kind":"質問・要望","question":"品川区の場合に、こういった被害の報告が、所管上難しいかもしれないですけれど、どこが受けるのかというところと、今回やるに当たってまた、こういった便乗が出る可能性があると思うのですが、ここは周知といいますか、こういう可能性があるというところの周知を行っていただきたいと考えていますが、いかがでしょうか。","respondent":"宮澤税務課長","answer":"給付金事業を実施する際、今回につきましては７月に広報しながわ、または区のホームページ等でお知らせするとともに、今回対象となる方にもご案内状が行きますので、そこでも注意喚起をしていきます。","voiceIndex":45,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"先ほども質問がありましたが、この給付金事業ですけれど１億３００万円というお話ですが、これからもまだ続くわけではないですか。不足額に対してこれから支給しなければいけない。ということは、これ１億３００万円ははるかに超えていくというふうに考えていなければいけないということですか。そこ、２つだけ教えてください。","respondent":"宮澤税務課長","answer":"昨年度の定額減税含めて調整給付金につきましては、減税等におきまして、可処分所得を押し上げて物価高の中で区民の負担軽減を図るというところで実施しています。","voiceIndex":47,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"すみません、言い方が悪かったと思うのですけれど、これからも委託費はまだ続くということですから、増えていくと考えていいのでしょうか。それで、実際多くの方が定額減税されているはずですが、実際は効果が出ていないと。分からないのですよね。こんなようなやり方で定額減税して、国民、区民の方がありがたいなどとは思わないと、私は思うのですが、その辺について少しご見解だけお聞かせください。","respondent":"宮澤税務課長","answer":"区民の方の評判ですが、税務課のほうには特段お声はいただいていないところではありますけれども、こういった給付金事業というのはとにかく速やかに実施するというところを念頭に進めているところです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"須貝委員","kind":"意見","question":"これも国民のために国が動いた定額減税ということですけれど、こんな分かりづらい、実感がない、実際その成果が上がらないというような、私の見る限りですが、区で捉えられているほうは分かりませんけれど、こんなことを地方自治体に押しつける、やれというのは何か間違っているような気がしますので、それだけ少し指摘しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-024"}]},{"id":"topic-03","title":"「品川区職員・教職員向け性的指向・ジェンダーアイデンティティに関する行動指針」の改訂","agenda":"「品川区職員・教職員向け性的指向・ジェンダーアイデンティティに関する行動指針」の改訂","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、今後さらに、ジェンダー平等推進条例もある中で、どう進めていくのかというのを知りたいので、そうした研修の回数や、ほかにもう少し何か工夫があるのか伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"これが職員の方々にとっては、勤務時間内、就業時間内に実施している形になったことと、会社の方々などからもご相談を受けるようなことを想定してこの時間にしておりますので、そういったものも含めて総合的に取り組んでいきたいなと考えております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、開催していくに当たっての説明を先ほど様々いただいたのですけれど、目標みたいなものというのですか、今年はこれぐらいやっていく、それで、さらに意見を寄せていただいて、さらに改訂していくみたいな指針、そういった今後へどうつながるのかなというのもお聞きしたいなと思うのです。","respondent":"木村人権・ジェンダー平等推進課長","answer":"行動指針、先ほど言ったとおり今回の改訂については、令和５年の法律と令和６年の条例について、ということも含めて改訂のきっかけにはなったのですが、内容としても、近年新しく変わってきたものですとか。","voiceIndex":59,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"パートナーと配偶者どう違うのとか、お連れ合いって何、とか、結構あやふやなものになってしまうので、区の手続の中でそれが答えづらいという、逆に分かりづらいというようなことがあるのではないかなと思うのですがどうなのでしょうか。だから、教育現場の周知徹底も非常に難しいのですけれど、それをどういうふうに、教育委員会、各学校との調整を図ろうとしているのか、まずこれを教えてください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"なので、もちろん区民の方の意識も変えていかなければならないというところではあるのですけれども、それに関しましては、また、別のところでというか、いろいろな方法を試していきながら、いい形で皆さんにお伝えできればと思いますし、例えば区役所の。","voiceIndex":62,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"だけれど、保育士たちがこれはちょっとあまりにもプライバシー、これプライバシーの問題になるのか、もう少し考えたほうがいいのではないかというような状況もあるので、だから、当事者の考え方も当然なのだけれども、それは大人だったら希望を聞いてということなのですが、やはりこういうものができているわけだから、専門的なところの意見を聞くとか、こちらから発信をして。","respondent":"木村人権・ジェンダー平等推進課長","answer":"積極的に区民の方にもというお話ですけれども、こちらのほうでもいろいろな形で区民の方々に、様々な機会を捉えてお話をさせていただいたり、例えば会議に出させていただいて説明をさせていただいたりというような形で、昨年も実施しておりますが、今年も引き続き。","voiceIndex":64,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"すみません、まだ全部読み切れていないので恐縮なのですが、教育関係者の責務、それから禁止事項と書いてあるのです。ということは、後半のほうを読みますと、教育を行うよう努めるものとするとか、性別等の起因する人権侵害を行ってはならない、そう書いてあるけれど、それを実際きちんと守りなさいよというときに罰則規定がなくて、果たして守り切れるのでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ただ、もし、相談しづらくて、難しい場合には、例えば、東京都のほうに相談してからこちらに相談したとかというような方もいらっしゃるかもしれませんし、これは実際に区の職員ではなく、外部の方のお話なのですけれども。","voiceIndex":66,"id":"exchange-029"},{"speaker":"須貝委員","kind":"確認","question":"意見だけですけれど、交通ルールもそうなのですが、スピード違反をしてはいけない、一旦停止しなければいけない、ここは追越し禁止だから追越ししてはいけない、そういうルールブックがきちんとあるのです。皆さん、運転者はそれぞれ理解をしている。毎回免許更新のときも確認をする。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"都議会議員選挙のほうなのですが、これ、毎回事前ポスターの撤去をやはり徹底してほしいと思います。これの徹底の仕方について。それから、候補者の住所の公表はするのでしょうか。それから、公報なのですけれど、６月２１日までというのは少し遅過ぎやしませんかと思うのです。これはもう少し早くなりませんか。なので、もう少し早くできないものかなと思いますが、いかがでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"今回行いました立候補者説明会につきましても、この２連ポスターにつきましては、告示日にきちんと撤去するように、通知文書も含めて徹底しているところです。それから住所の公表になります。","voiceIndex":74,"id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"ただ、これは貼り残しがいっぱいありますので、やはり引き続き徹底をお願いしたいなと思います。候補者の住所、これ１点確認なのですけれど、明確な何番地までは要らないと思うのですが、どこどこ出身かというのは、品川区なのか他区なのかというのは、やはり明確なことを知りたいなと思うので、公報紙にそういうものはあまり書けないと思うので、多分書かないと思うのです。","respondent":"今井選挙管理委員会事務局長","answer":"ですので、今後事前審査終了者につきましては、東京都のほうの届出の告示などを確認していただくようになるかと思います。","voiceIndex":76,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"すみません、今の件なのですが、６月１３日が提出ではないですか。だから事前審査をその前にやっていますよね。その事前審査のことなのか、それともその６月１３日の情報なのか、都のほうが公開するということであれば東京都の都選管のほうにお願いすれば、例えばホームページなどでの公表になるのか、その辺少し教えてほしいのです。","respondent":"今井選挙管理委員会事務局長","answer":"初めに、５月２６日から事前審査を行いますので、そちらのほうは速やかに報道機関へ提供いたします。","voiceIndex":78,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"参議院のほうの選挙の、公営ポスター掲示板の設置ということで、７２面というのは結構大きな数だなと思うのですけれど、今の時点で、何面掛ける何面みたいなことが分かるでしょうか。横に伸びたら伸びたで、スペース的に大丈夫ではない場所も出てくるのかなと思ったりもするのですが、その面の感じが分かれば教えていただきたいと思います。","respondent":"今井選挙管理委員会事務局長","answer":"４段になりまして、ただ、一気に板面を設置できるところと、少し間を空けて板面を作るところはいろいろ工夫をしまして、今回３４８か所のうちの１割は少し移設をしたり場所を動かしたりするような工夫をしながら。","voiceIndex":81,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、有権者の高齢化も進む、そういう中で、期日前投票の場所も遠くて、当日の投票所も遠いという方が、地域があったりすると、投票権を、権利を行使することができないという状況も少し最近、私も聞くようになりまして、だからといって郵送投票ができるほどの、要は、条件ではないということで、今後、もう来月の都議選、その後の参議院選となると対応は難しいと思うのですけれども、今後。","respondent":"今井選挙管理委員会事務局長","answer":"障害のある方、いわゆる障害だけではなくて介助が必要な方は、障害のある方はご自宅から投票所への移動支援について、いわゆる介護ヘルパーのこともありますし、それから、社会福祉協議会が有償サービスのさわやかサービス、おでかけサービスも行っておりますので。","voiceIndex":83,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、様々な方が無理なく投票できるようにしていただきたいなと思うのですけれども、そういうガイドヘルパーだったり、介護の現場も人手不足で、人手がないためにヘルパーに行けないという状況も多々聞きますので、そういった様々な課題がある中ですので難しいと思うのですけれども、そこを何とか、やはり権利ですので行使できる環境整備を、引き続き私たちとしても求めていきたいなと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-036"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"意見","question":"遺贈ということだったと思うのですけれど、それの公正証書などを取っていろいろやるよという話で、議会のほうにもそれを報告していただけるということを言っていたと思うのです。細かい中身はいいです、守秘義務もあると思いますので、それはどうなっていますか。どういうふうに進んでいますか。","respondent":"藤村総務課長","answer":"遺贈の公正証書等というところですけれども、かねてより委員会などでもいろいろお伝えさせていただいているところかと思いますが、公式文書という形で、その所有者のご本人からは、土地ですとか建物というところは遺贈するということを。","voiceIndex":91,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"これ、議会の中で答弁いただいている案件です。何かしらの約束事をするということが議会の中でのご答弁なのです。なので、時期が来たらということは当然それは分かります。なので、それをしっかりと、議会への報告はしていただくように強くお願いしておきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"すみません、少しお聞きしたいのですが、新庁舎建設の予定地に建築資材が多数置かれているのですが、あれは品川区の新庁舎の建築資材なのですか。","respondent":"泉広町事業調整担当課長","answer":"今、新庁舎の整備予定地に置かれている建設の資材関係につきましては、隣接で行われているＪＲの工事、そこは今、収去の工事ということで、更地にするための工事を行っておりまして、そういった関係の資機材が置かれているという状況です。","voiceIndex":95,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"先ほどの報告事案で出てきたのですけれど、キッチンカーが地所賃貸料で１２日間で少ない面積で１４万６,０００円、賃料として取っていますよね。あの敷地をもし品川区が、ＪＲに今貸しているということならば、何億円か何十億円か分からないのですけれど、それは請求できるのですか。","respondent":"泉広町事業調整担当課長","answer":"今、新庁舎の敷地で行われている工事につきましては、従前の土地所有者でございましたＪＲが、いわゆるあそこを更地にするために、新庁舎を工事するために、もともとあったＪＲ街区の構造物などを撤去するために使われているというところもございまして。","voiceIndex":97,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"それで看板も立って、これから建設計画がありますと、品川区の土地だと私は思うのですが、それに対して、ああいうふうに資材を置かれるということは、やはりどんなに親しいとはいえ、やはりきちんとした社会通念上、地所代ですか、賃貸料はしっかり取るというのは普通の社会通念上のやり方だと私は思うのですが、そんなことはＪＲでも知っていると思うのですが、何かおかしくありませんか。","respondent":"泉広町事業調整担当課長","answer":"今、新庁舎の整備が予定されている敷地につきましては、従前はＪＲの敷地というところで、繰り返しになりますけれども、現在ＪＲのほうでそこを更地にするための工事が行われているところで、その敷地の管理につきましても、今ＪＲが管理をしているということになってあります。","voiceIndex":99,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"意味が分からないのですけれど、建築計画が出ているということは、建築課が確認申請しているわけですよね。そうしたらそれは区の土地でなければ、その確認申請は受理できないではないですか。そんなことないのではないですか。一般の社会の建設関係の社会通念上、そういう考え方はおかしいと思うので、ここで議論してもしようがないので、しかるべくきちんとした回答をいただきたいと思います。","respondent":"堀越副区長","answer":"当然、今のこの状態のまま区がその土地の管理を受けて、区が何かをするという場合には当然、それなりの金額の管理料が発生しますので、そういった部分も含めて、区画整理事業の枠組みの中でこういう対応を取っているですので、何か、例えばＪＲのほうに便宜を図るとか。","voiceIndex":101,"id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"いや、そういう関係性ではなくて、普通そういうふうに、借りるなら借りるという、そういう権利というのは、社会通念上、向こうも支払うべき話だし、こちらももらうべき話ではないですかということを申し上げています。","respondent":"堀越副区長","answer":"お考えはよく分かりますが、区画整理事業の枠組みの中で、今お話しした中身をいろいろ協定を取り決めてやっているですので、例えば、もともとの土地を区が持っていたとか、そういう関係とは若干違いますので、また、技術的なそういう部分も含めて、先ほど申し上げましたとおり。","voiceIndex":103,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"おやっと思ったというか、ここは都市計画審議会でも権利変換などして、もう決まっているのではないのですか。それで、都市計画審議会でもこれが審議されていて、それで、これ全部品川区の持ち物というものではないのですか。区画整理のためにというのはよく分からないのですけれど。","respondent":"泉広町事業調整担当課長","answer":"今ご質問のありました敷地につきましては、まず、新庁舎の整備をする予定地となっているところにつきましては、土地区画整理法上の仮換地の状態になってございまして、そこは品川区のほうに仮換地をされてあります。","voiceIndex":105,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"ということは、まずはその権利変換、一応都市計画審議会ではきちんと議論していましたけれども、そういうものが現場サイドの中ではまだですよということですか。ではそれがいつになるのですか。いつから品川区の工事が始まって、いつから品川区の持ち物になって、仮にＪＲが貸してくれというのなら貸せばいいと思います。それはいつがそういう状況になるのですか。","respondent":"泉広町事業調整担当課長","answer":"いつから品川区がですけれども、今、新庁舎の整備の契約は１０月頃を予定していますが、その前の段階で、品川区のほうで使用収益を開始したいということで考えておるです。","voiceIndex":107,"id":"exchange-045"},{"speaker":"新妻副委員長","kind":"提案","question":"この１年間、理事者の皆様、そして、委員の皆様にご協力をいただきまして、活発な議論も進んだかなと考えています。所管事務調査に沿った行政視察もさせていただきました。大変にありがとうございました。理事者の皆様におかれましては、委員から提案がありましたことを実現していただけますようお願いを申し上げまして、ご挨拶とします。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7045#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":39821,"voices":111}},{"id":"r07-20250513-14","meetingId":"r07-cm05","date":"2025年5月13日","dateIso":"2025-05-13","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区ＤＸ推進基本方針の改定","agenda":"品川区ＤＸ推進基本方針の改定","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"もう一度確認しますけれども、１月の段階で、今回の内容についてはご説明を受けたという認識でよろしいのでしょうか。","respondent":"西澤ＤＸ戦略担当課長","answer":"はい、ご認識のとおりです。説明済みの内容になっております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"新妻委員","kind":"確認","question":"特にホームページに関しては、やはり今回だけではないと思いますが、お声は上がっていたのだろうなと思うのですけれども、ホームページで情報を得る方は非常に多いと思いますし、まず第１弾、そこでしっかりと情報が確認できることが職員の方への業務の改善にもつながっていくかと思いますので、ぜひここは分かりやすいホームページの改定は早めに進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"私からも何点か質問します。その上でなのですけれども、重点施策以外には、１枚紙で示された内容、これまでの取組や評価指標、推進スケジュールが示されていないのですけれども、これは作成はしていらっしゃらないのでしょうかというところからお願いします。","respondent":"西澤ＤＸ戦略担当課長","answer":"アクションプランのスケジュールについてですが、こちらにお示ししている内容については、時期を明確に定めていて、重点施策については、このスケジュールのとおりやっていくという方針で考えております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"ここでなのですけれども、２３区、近隣区の状況を見渡しますと、最近、抜本的にウェブサイトを見直している区が増えておりまして、このような区のウェブサイトは昔から少しずつ直して、直して直してやってきているので、抜本的に見直すことがすごく難しいという仕組みなのは分かるのですけれども、こういった状況も踏まえて、そしてＤＸ推進基本計画の改定等々の時期も踏まえると。","respondent":"西澤ＤＸ戦略担当課長","answer":"こちらの取組は、東京都のＧｏｖＴｅｃｈとも連携して、今、ＧｏｖＴｅｃｈは伴走支援で、ほかの自治体の事例とかを我々と一緒にどういったホームページにしたいかといったところの支援をしてくれるような取組がなされておりまして、そちらに参加して、今年１年間。","voiceIndex":14,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"とてもよく分かりました。それから戦略広報課と共同してうまく進めていただきたいと思います。次に、地域ＤＸになります。こちらは重点施策３点でございまして、誰ひとり取り残さないデジタル活用の推進、これ、最重要課題ということで引き続き上げていただいておりまして、私も要望しているところであり、ぜひ進めていただきたいと考えています。この中身のところで質問なのですが、８ページです。","respondent":"横田デジタル推進課長","answer":"一方で、高齢者の方のスマホの利用が大分定着してきたというところで、個別のよろず相談は伸びているので、よろず相談を今後集中的にやっていきたいというふうに考えているところです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"だとすると、よろず相談を目標、評価指標のところに設定することがふさわしいのではないかなというところが１点と、あと、パソコン講座のところは、私も従前から要望していますけれども、まだまだ高齢者の皆様の全体の数からすると、もっともっと数を増やしたほうがいいのではないかと考えていますので、そういったところの工夫も引き続きお願いしたいと思います。これは要望です。続けます。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"令和５年度は１,３２７件の方がご使用いただいていまして、令和８年度になると、もう２,０００件近くなっているということで、昨今、大幅に伸びている傾向がありますので、委員ご指摘のとおり。住民参加型デジタルプラットフォームの件数についてなのですけれども、昨年は試行的に実施したところもありまして、防災に関する取組についてになりますけれども、こちらは１１７件というところで。","voiceIndex":18,"id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"これは所管組織が学務課等で、保育施設運営課ですか、前者のほうが学務課、教育委員会になっていまして、その教育委員会との連携をどのようになされるかというところで、タブレットを活用した授業の中身とか、そういったところに関わるのかと思いましたので、デジタル推進課と教育委員会との連携の方針や進め方がどのようにされるのかということが分かれば教えていただければと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"ただいま質問いただいたＧＩＧＡスクールの件ですが、授業のコンテンツだとか、そういったところは学務課の内容になっておりまして、我々としましては、例えば、入れるスマホのタブレットの性能だとか、ネットワークだとか。","voiceIndex":21,"id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"その中でも１２ページに記載されているＡＩや生成ＡＩ業務への利活用の推進というところになりますけれども、以前も少しお話しさせていただきましたけれども、学校の教職員の皆様へのこういった利用の推進というところで、ぜひ進めていただきたいと思っておりまして、先日の文教委員会でも教育委員会の皆様もこれを進めていく動きを考えているということで言われていましたので、その辺り、今。","respondent":"西澤ＤＸ戦略担当課長","answer":"教職員のＡＩの活用についてですが、こちらは、今、教育委員会とも連携しながらやっていこうというところでありまして、区の準備しているＡＩのツールがありますので、そちらを使って、学校の教職員の方々の校務の業務改善を進めようとして、今度。","voiceIndex":23,"id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"最後に、ＥＢＰＭの推進のところも非常に大事だと思いまして、この辺りの目標設定、データ利活用による好事例創出目標５件、データアナリストとの共同案件目標３件というのは、これは非常によいなと思いまして、これを実現するためには、多分、もう少し多くの材料をここからやっていくのかなと思いますので、これはそれぞれぜひ進めていただきたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＤＸ人材の育成については、全職員対象にアンケートをとる予定でありまして、年度ごとに評価をして、それで改善につなげていくというところを実施しようと思っています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"最後は、検討していきたいということでご答弁をいただいていて、また、今回のパブリックコメントの中にも、それに関する質問というか問いがあって、それに対しても、貴重なご提案として参考としますというふうな区の回答がありますが、そこについて、今、品川区の今後の予定とか、この間の検討状況について教えてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"ただいま質問いただいたデジタル推進委員についてですが、こちらは、おっしゃるとおり、デジタル庁が定めたものになりまして、こちらについては、区民誰もがＤＸの恩恵を受けられるようなＤＸ推進を進めていく上で、パソコン／タブレット／スマホ教室とか。","voiceIndex":28,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"数では、私も全部把握しているわけではないのですが、その方の知り合いも含めていらっしゃるというところで、連携のやり方はいろいろルールもあるのかも分かりませんが、今、いろいろな国だとか東京都とか、様々な行政サービスの展開がスマートフォンに集約したようなサービスも、今後、増えていくという流れもあるところですとか、東京都では、簡易なスマートフォンの提供だとか。","respondent":"西澤ＤＸ戦略担当課長","answer":"そうですね、デジタル化の取組で、デジタル庁とも連携して、調査して進めていきたいというふうに考えております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"のだて委員","kind":"意見","question":"アクションプランが出てきたのは今回が初めてだと思うのですけれども、最初の説明だと、あまりにも簡潔過ぎるので、このアクションプラン、先ほどから説明されている部分はありますが、さらに説明しておきたいところとか、少し説明をしていただければと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"２つ目の庁内組織横断で取り組むべき施策は、先ほどの答弁でもありましたとおり、単一の部署ではなかなか難しいところもありまして、ＤＸはデジタル部署だけではなく、所管部署の課題だとか、施策だとか、そういったところと連携していくことが重要だと考えておりまして。","voiceIndex":32,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"幾つか伺いたいのですけれども、６ページのところで、窓口支援システムの活用をしていくということで、これがどういった支援システムなのかというところを伺いたいのと、あと、同様に、その下に窓口体験調査もこれまで行ってきたということで、これによって、どのような改善がされてきたのかというところを伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"窓口についてですが、窓口改善調査を去年１２月に実施しまして、その中で職員が区民になり切って手続をしてみるといったような調査をして、時間を計ったりだとか、バックヤードの処理の内容だとか、そういったところを見た上で。どのようにセキュリティを強化していくかというところなのですが、これまで品川区役所はＬＧＷＡＮという閉じられた環境で業務を行っていたわけなのですが、そうした場合、境界型防御ということで、繰り返しになりますけれども。","voiceIndex":34,"id":"exchange-013"},{"speaker":"筒井委員","kind":"確認","question":"基本方針の実現のために具体的施策をアクションプランとしてやっていくということなのかということをまず確認したいのと、あと、基本方針は、更新の期間が５年間ですけれども、アクションプランは、大体３年になっているかと思うのですけれども、その理由です、アクションプランの動きに合わせて、やはり方針のほうも適宜。","respondent":"西澤ＤＸ戦略担当課長","answer":"それに伴って、アクションプランがなぜ３年なのかというところですが、こちらについては、より具体的な施策を年度単位で設定することが重要かなと思っておりまして、基本的には年度単位で考えていて、それを３か年で実施していくという。","voiceIndex":37,"id":"exchange-014"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。「シゴトＤＸ」アクションプラン、重点施策６、ＥＢＰＭの推進のところで、ＢＩツールの導入と書いてあるのですけれども、ちなみに、このＢＩツールは、具体的にどのようなものをお使いになっているのかお知らせください。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＢＩツールは、Ｔａｂｌｅａｕというツールを使っておりまして、そちらのツールを使うことで、ＣＳＶのデータだとか、エクセルのデータだとか、そういった数値データを可視化したりとか、あとは高度な使い方ですと、地図データとかを使うことによって、例えばですけれども。","voiceIndex":39,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"提案","question":"いわゆるエビデンスなのだと、我々は、どちらか、区議会議員というのは町場の人の声を聞いて、そのエピソードに基づいて、提案、立案をしているのですけれども、そこのところのエビデンスの、今度、データアナリストとの共同で案件を募集して、さっきチャレンジングというお話がありましたが、具体的には誰に対してエビデンスを示すのか。","respondent":"西澤ＤＸ戦略担当課長","answer":"委員おっしゃったとおり、まさにこれは難しいポイントだと私も思っております。１７ページに示したポートフォリオといいますか、こちらの図にも示していますけれども、アンケートデータが、先ほどおっしゃっていたとおり、扱いが結構難しいと思っているポイントであります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"我々とか区民は、データでこういうふうに言われていますよとか、こういう意見が多かったのでと、アンケートでと言われてしまうと、それがＥＢＰＭですと言われると、ああ、そうなのだと納得するのだけれども、納得というか、「はい」としか言いようがないというか、だから、それは母数がどれだけだと、さっきアンケートという話がありましたけれども、アンケートを使うのであれば、何分の、どの意見があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-017"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、要望と質問をさせていただきたいのですが、アクションプラン窓口ＤＸについて先ほどお話があったところで、デジタルとアナログについて考えていたのですが、アナログをある程度解決して、業務のフローを見直して課題を見つけるというお話があった中で、これからマイナンバーカードの手続ですとか、証明書の発行ですとか。","respondent":"横田デジタル推進課長","answer":"これにつきましては、システム標準化であったり、システム移行があったから起きたということではない事象になりますので、関係所管、デジタル推進課、ＳＥを含めて、この辺りを反省しながら、二度と起こさないように推進していきたいと考えております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"西村委員","kind":"質問","question":"ということは、これぐらいの不具合は例年起きているということでよろしいのでしょうか。","respondent":"横田デジタル推進課長","answer":"このような障害につきましては、例年も起きてきていないという状況です。今回たまたま起きてしまったというところになります。ただ、たまたまということを反省しながら次回に活かしていきたいというふうに考えております。","voiceIndex":46,"id":"exchange-019"}]},{"id":"topic-02","title":"「品川区ふるさと納税特設サイト」の開設および「しながわ団体応援寄附」の開始","agenda":"「品川区ふるさと納税特設サイト」の開設および「しながわ団体応援寄附」の開始","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"本当に全然分からないので教えていただきたいのですけれども、今回のこのふるさと納税特設サイトの開設は、今までふるさとチョイスという事業者を使っていて、そこはガバメントクラウドファンディング（ＧＣＦ）、そこのいわゆる独占権というか、名称の独占権を持っていて、ガバメントクラウドファンディングをやるのだったらそこだということで。","respondent":"宮澤税務課長","answer":"１点目の業者を代えるのかですけれども、ふるさとチョイス、ふるなび等々、今、ポータルサイトを９つ活用しています。そちらは引き続き寄附の募集という形で活用はしていきますが、改めて区として特設のサイトを開設するというところです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"今までの業者も同じようにガバメントクラウドファンディングもやっていくということなのでしょうけれども、こちらのほうでは、クラウドファンディングということが下のほうに、３番目にクラウドファンディングとあるのですけれども、そことの違いというか、どういう立て分けをされるのか、そこだけ教えてください。","respondent":"宮澤税務課長","answer":"クラウドファンディングの部分です。クラウドファンディングする場合、既存のポータルサイトを今年度も予定しておりますけれども、そちらのほうも活用します。ただ、このふるさと納税特設サイトのほうでも、同じ時期、同様に募集を開始するという形になります。","voiceIndex":54,"id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"ごめんなさい、私の理解不足で。そのことに関してなのですけれども、例えば、毎年やってきたしあわせ食卓事業のためのガバメントクラウドファンディングと同じものをこの特設サイトでやるということなのでしょうか。別の名称でやるということなのか。金額もそれぞれ立ててやるということなのか、その辺りをもう１回教えてください。","respondent":"宮澤税務課長","answer":"同じ内容で、同じ目標金額を立ててやります。集まった金額は、両方が最終的には合算するというような形になります。","voiceIndex":56,"id":"exchange-022"},{"speaker":"山本委員","kind":"質問","question":"ご説明ありがとうございました。ふるさと納税での流出額を、できるだけ差額を減らすためにこのような取組をするということはとても大事なことだと考えています。その中で幾つか質問しますけれども、今回、この特設サイトをつくる費用は、どれぐらいかかっているのか、区が直接、区の職員の皆様がやられているのか、委託でやっているのか、そして幾らぐらいかかっているのかを教えてください。","respondent":"宮澤税務課長","answer":"今年度から、ふるさと納税を進めていく上で、中間事業者に委託をかけております。その委託金額、予算上は７００万円を計上しておりまして、特設サイトに特別に別に予算を計上しているわけではなくて、その中で事業者のほうで区と連携しながらサイトを構築しています。","voiceIndex":58,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問","question":"状況を理解いたしました。これに当てはめますと、例えばサイトをつくったことで、どれぐらいの目標をこれに置いているかというところで、具体的には、例えば、閲覧数でどれぐらい見てもらうことを予定しているとか、さらには、これを見てもらったことで幾らぐらいの寄附額を想定しているというところで、そういったところの目標があれば、目標設定内容、それぞれの目標指標等を教えていただければと思います。","respondent":"宮澤税務課長","answer":"先ほど説明もさせていただきましたが、既存のポータルサイトでも寄附を集めますし、今回このふるさと納税の特設サイト上でしながわ団体応援寄附という新たな寄附の枠組みも行います。それらを含めて１.２億円を集めていきたいというところであります。","voiceIndex":60,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"最後にといいますか、結局は、より多くの方に知ってもらうことがとても大事だと思うのですけれども、このサイトをつくって、このサイトをどう広く認知してもらうかというところで何かお考えがあればお伺いしたいというところと、私、これまで議会の数々の場でいろいろと要望していますが、区で独自のデジタル通貨等を幅広く流通させて知ってもらったりして、そういうプラットフォームをつくり。","respondent":"宮澤税務課長","answer":"特設サイトの周知という部分ですけれども、今年度、ふるさと納税の取組に対して、広報しながわの特集号を発行する予定です。それを含めまして、各種ＳＮＳを通じて発信等もしてまいります。","voiceIndex":62,"id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"情報の伝達をしていただく先というところで、区内と区外と双方あるなというところを今ご説明いただいて改めて思ったところではありますが、いずれにしましても、より多くの方に知っていただいて、効果が出るように進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"今回、しながわ団体応援寄附というものを始めるということで、この事業を区が実施するに至った経緯を伺いたいと思います。そして、今回、これに関わると思いますが、なぜ学校法人なのかというところです。学校のほうに交付される補助金が上限７割というふうに書いてあるのですが、これは寄附された上限７割というわけではないですよね。上限７割というのはどういうことか伺います。","respondent":"宮澤税務課長","answer":"この団体応援をする枠組みが、２３区含めて他区、また全国的な自治体でも取組を進めているところです。そういった中で、文部科学省からも、自治体と学校法人が連携した取組の好事例ということでも令和４年度にモデルケースということでもお知らせしていると。","voiceIndex":65,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"経緯はご説明いただいて分かった部分はあるのですけれども、そうすると、今、区内の大学や高校、中学校の経営がなかなか大変な状況があるということで、国もそうしたモデルケースなどを示してやっているということなのか、そこを伺いたいと思います。","respondent":"宮澤税務課長","answer":"学校法人を対象とさせていただいていまして、区内の学校法人の経営が厳しいというようなことではなくて、今回、広く多くの方に応援してもらうというところで寄附を集めまして、事業に活用していただくというところで寄附を集めるというものです。","voiceIndex":67,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"流出額が約５０.９億円ということで、一方、聞き間違いがあるかもしれないですけれども、区に入ってくる寄附額は１,６６９万円程度でしたか、違っていたらまた教えてほしいのですけれど、それで今回、ふるさと納税特設サイト等で努力して、目標１.２億円まで何とかしていくということなのですけれども、それにしても、流出額と、こちらに入ってくる流入額の差がかなり大きいので、引き続き、区としては。","respondent":"宮澤税務課長","answer":"最後に、都市ブランディングの部分です。特設サイトを開設しまして、やはり品川区の魅力を発信していくというところにも力を入れていきます。その中で都市のブランディングというところを担当部署とも連携しながら進めていきたいと考えております。","voiceIndex":69,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"はい、分かりました。ぜひ都市ブランディングとの連携をよろしくお願いします。しながわ団体応援寄附についてですけれども、これは私立学校も今回含めたということで、私立学校へ行かれている方は、やはり品川区民以外の方も一定数いらっしゃると思いますが、その点を考えて、こうした仕組みにしたのか、その辺りのお考えはいかがでしょうか。","respondent":"宮澤税務課長","answer":"各学校法人にお話ししても、同窓会報等でお知らせして集めたいというような意気込みを持っている学校も多くございまして、まさに区外にお住まいの多くの方が、このふるさと納税の特設サイトに訪れていただいて、団体応援の寄附もしてもらいつつ。","voiceIndex":71,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私もよく分かっていないのですが、お聞きしたいのは、まず、税務課長がいいとか悪いとか、そういう話をするつもりも全くないので、ただ教えていただきたいのは、令和７年５月２７日に開設をされるということ、ここに書いてあるとおり。それがもう４００でも５００でも出てくるのですかということをまずお聞きしたいのと、団体応援寄附もいいのです、クラウドファンディングでもいいのです。","respondent":"宮澤税務課長","answer":"今年度は、現状、約５０品目程度なのですけれども、それを今年度中に２００品目以上にはしていきたいというふうに考えているところです。","voiceIndex":73,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけど、そういう品川のためにやりますよという人がいてくれたほうがいいと思うし、それで、さっき、メニューの数が５０から２００にしていきますと言うのだけれども、これ、いろいろ時間がかかるということは分かるけれども、渋谷区とかでも、もう４００幾つとか５００ぐらい出しているわけではないですか。なぜこういうところに手がつかないのですかということを聞きたかったのです。","respondent":"宮澤税務課長","answer":"プロの活用という部分ですけれども、中間事業者をこの４月に入れて進めております。私も４月から着任しておりますけれども、事業者としっかり連携しながら、まずは品目の拡大も含めてやっていきたいというふうに考えているところです。","voiceIndex":75,"id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"ほかでもやろうと思っているので、お願いだけしておきます。それは連携するのはいいのです、委託をしたところと一生懸命、１軒２軒やっていきます、それは頑張りますというのはいいのだけれども、どうしてそういう営業的な方、プロで営業を１軒１軒潰して歩くぐらいの人を見つけたほうがいいような気がする。だけど、それぐらいの勢いでやったほうがいいのではないですかということをお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-033"},{"speaker":"つる委員","kind":"確認","question":"個別具体の可能性みたいなところのお話しなのですが、ふるさと納税だけで５０億円以上ありまして、別でいろいろ確認もさせていただいて、次年度以降ですか、今回の１０３万円とかの関係で、住民税にも影響して、それでも二、三億円ぐらい区の税収が減るとなってくると、６０億円近く、前半というか、そういうふうな本来区に入ってくるべきものがなかなか入ってこなくなる。","respondent":"宮澤税務課長","answer":"東京湾の花火に関しては、見える位置等々の課題等はあるかと思いますけれども、天王洲で行っております花火大会に関しては、今年度、ふるさと納税の返礼品として行うように、今、実行委員会と調整しておりますので、返礼品として、そういうものを用意するということは可能です。","voiceIndex":78,"id":"exchange-034"},{"speaker":"つる委員","kind":"質問・要望","question":"こちら側から見るという画角も当然あるわけで、そういったところも含めて、将来そういうふうになった場合に、ぜひ積極的ないろいろな事業者も含めて、既存の屋形船の方も含めてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7047#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":30536,"voices":92}},{"id":"r07-20250514-19","meetingId":"r07-cm05","date":"2025年5月14日","dateIso":"2025-05-14","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 １時５６分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度しながわゼロカーボンアクション助成の受付開始","agenda":"令和７年度しながわゼロカーボンアクション助成の受付開始","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"すごくまとめていただいて、分かりやすくなったなと思うのですけれども、それでこのパンフレットも、私たち、どこがどのように減らしていけばいいのかというロードマップを出してくださいとずっと要望していたのですが、このパンフレット、一家庭当たりこれだけの削減が必要ですというように書いていただいて、若干……、若干といいますか、すごく一家庭がどう。","respondent":"中西環境課長","answer":"ただ、この助成制度以外での取組といったところでは、ほかの区でも特色ある取組をしていますので、そういったものに関してはアンテナを張りながら、品川区でそういったものが落とし込めないかというものは日々研究してまいりたいと考えているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"いや、本当に品川区、進んだなということは思うところですので、引き続き積極的に私たちも区と一緒にやっていきたいなと思っているのですが、あと、このパンフレットのほうで、国と東京都の補助金ということで、一番最後、１４ページにということで開いてみると、すごくきゅっとまとまってしまっていて、これももう少し、さらに開いた後自分が必要なものに行き着くのに少し時間がかかるといいますか。","respondent":"中西環境課長","answer":"国や東京都のほうが、まず品川区のように、このタイミングから全ての助成金が始まりますというわけではなくて、タイミング、タイミング、また、省庁別によっても違ってくるといったところも、タイミングが違ってくる部分もありますので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひお願いします。それと、先ほど６月に説明、パネルを展示して区民の皆さんに説明していくということで、いつどこでということがもう決まっているのですか。聞き漏らしたのかな。エコルとごしで。６月のいつかをちょっと、すみません。","respondent":"中西環境課長","answer":"それから説明会に関しましては、６月２８日の土曜日、１２時から１７時の間で説明会、うちの職員のほうが出向きまして、相談会を行おうと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"１点確認です。申請手続の流れというものが５ページにあります。それで、これ審査が記載漏れや必要書類が不足している場合、申請書類に不備が無い場合ということで、その先が２つに分かれていくということは、記載がきちんとされていれば、審査では基本交付決定というようになるという理解でよろしいでしょうか。何か別の審査があるなら教えてください。","respondent":"中西環境課長","answer":"例えばエコジョーズとか、エネファームとか、最近少し間のような機種も出てきております。エコフィールのようなものも出てきていますので、そういったものがきちんとその申請内容と合っているかといったところの審査といったものはあるところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"基本やはりきちんと記載されていたら、皆もらえたほうがいいなと思って質問をしたのですけれども、それはどこかで分かるということですか。今ご説明いただいたようなこと。そうしたら、きちんとそのような審査が通るようなものをお使いになるのではないかなと思うのですけれども、ごめんなさい、きちんと読み込めていないので、その辺が分かるようになっているのか教えてください。","respondent":"中西環境課長","answer":"昨年度の経過でいきますと、かなりお問合せを多くいただいておりまして、こちらのほうでも確認をいたしますし、また、最近ですと、特に大井町にあります百貨店、大型の家電量販店などですと、この制度もご存じなので。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう本当にこのような形でまとめていただいて、またパンフレットも作っていただいて、すごく分かりやすくなってよかったなと思っています。先ほどの６月のエコルとごしでの説明会なのですけれども、この説明会というものは、このような助成がありますよという中身の説明会なのか、ちょっとその辺のところを教えていただきたいと思います。","respondent":"中西環境課長","answer":"例えば、ご自宅をこれから新築される、リフォームされるときにどういった制度がありますかとなったときには、我々の制度に関しては環境課の職員が出ますので、環境部門の制度に関してはご説明できるのですが、例えば国や東京都のところになってしまうと。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。この品川区の太陽光というものは、東側に太陽光をつけるとか、そのようなものでも補助金がつくのか教えていただきたいということと、この１,６５７kgの削減というものは、何キロワットの想定でこれだけなるのかということも、ちょっと教えていただけたらと思います。","respondent":"中西環境課長","answer":"太陽光発電の設置の補助に関しては、どちらの面につけたといったところで補助の内容が変わるということは、区のほうではございません。あくまでも、ご自宅なり、事業所のほうに太陽光パネルをつけていただくといったことで補助を出すといったような制度になってあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは、この件数というものは、大体これで区民の、何というのですか、要望に応えられるだろうという件数で想定しているのでしょうかというようなことを伺いたいということと、できれば予算を超えてオーバーした場合も、補正予算を組むなどして要望に応えるというようにはできないのかなと思ったのですけれども、その点も伺いたいと思います。","respondent":"中西環境課長","answer":"件数に達してしまった場合の対応といったところですが、今この時点で何かという考えは持ってございませんけれども、そのときの状況の中で判断をさせていただきたいなと考えてです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひこれは積極的に、気候危機に対しての対策というようなところでも、これだけ区としても積極的な対応していただいているということで、要望がそれを超えた場合は要望に応えられるようにぜひともしていただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"確認","question":"そのような点では量販店のほうも分かっていらっしゃるということで、私は認識、分かりましたけれども、周知の方法で、住宅展示場等が入っていて、その住宅展示場は八潮に抜ける道の住宅展示場なのかどうかということの確認と、もう一つが、建設４団体の方々には、等の中にもしかしたら入っているのかも分かりませんけれども、入っていると思うのかもしれませんが。","respondent":"中西環境課長","answer":"それから建設４団体など、そういった各種団体への周知に関しては、これからアポのほう取りまして、メールでお流しするなど、そういったところで、データのほうをお送りしたいと。どういった形がいいかということはこれから相談しながら進めていきたいと考えています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。それで、量販店の方々も分かっていらっしゃるということでしたけれども、それは区のほうでこのような助成制度をやりますよということでお伝えをした上で、その認識をしているということでいいのですか。","respondent":"中西環境課長","answer":"量販店の方に関しては、昨年度、特段こちらからアプローチをしたわけではなくて、先方のほうで助成制度をお調べになってご説明をされていたといった経緯があります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"今の高橋伸明委員に関連する質問です。お客さんから相談を受けたときに、区でこのような助成をしていますよというように、お店側のほうからそのようなお知らせもしていただけるとというところもあるので、そうした考え方はどうなのかといったところです。ですから、今言ったまちの電気屋にもお知らせをし、もっと言えば、不動産屋もこのようなことを知っておいていただきたいというところです。","respondent":"中西環境課長","answer":"２点のご質問かなと思います。まとめてのご回答になるかと思いますが、区内金融機関というものが、昨年度連携協定を結びました、例えば城南信用金庫など、そういったような金融機関のほうにお力をお借りして周知をしようと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"これは課長のあれですか、たまものですか。本当にすばらしいなと思っています。せっかくこうやってすばらしい、いいものができたのであれば、これからさらに、所管をまたいだ関連するような助成金も、どこがやるのだという話になってしまうかもしれないですけれども、くっつけて、さらに何か分かりやすいような、何ですか、助成金の表をつくっていただけると非常に助かるかなと思いますが、いかがでしょうか。","respondent":"中西環境課長","answer":"ただ、おっしゃるとおりで、なかなか文字だけになってしまって具体的に何に使えるのかということは分かりづらい部分はあろうかと思います。引き続き、他課と連携をしながら、どういった見せ方ができるかといったものは環境課のほうで考えてまいりたいと思っています。","voiceIndex":33,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"かなり倒産件数が増えていることを考えると、何かせっかくゼロカーボンを進めて、自然エネルギーを取り入れて国民の方に供給しようというものが、何か逆にストップをかけられているような気がするのですが、その辺についてもどのようなご見解を持っているのか、簡単でいいので、もしお考えがあったらお聞かせください。","respondent":"中西環境課長","answer":"区としては、そこのシステム業者自体を支援するということはなかなか難しいところもありますし、区としてやるべきかといったところもありますので、そういった面では、区民の皆様、事業所の皆様に太陽光発電のシステムや。","voiceIndex":36,"id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"一生懸命こうやって、各自治体でゼロカーボンに向けて取り組んでいるのに、片や、もっとたくさん使う電力のほう、事業に対しては逆に縮小していく、もう非常に矛盾しているような今状況なので、ぜひ、これは区にお願いをするというよりは国にお願いするしかないので、ぜひいい方向に進んでいくように期待をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"そのようなときに、何というのですか、庁内でいろいろな課が連携して、庁内横断型のプロジェクトチームのような形で対策を取っていくということも必要かなと思うのですけれども、そういうところでは、区としては、そのような庁内横断型のプロジェクトチームのような形ではなっていないのか。","respondent":"中西環境課長","answer":"ただ昨年度、技術職でつくる技術会議の中で、若手職員に集まってもらって環境ＰＴというものを立ち上げていただいて、区としてどういった環境施策が、環境の事業ができるかといったものを環境課のほうにご提案をいただくといった取組は昨年度実施をして。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"意見","question":"本当に気候危機対策というものは待ったなしの課題で、様々本当に環境課としても取り組んでいただいているということは評価するところですけれども、さらにいろいろな、先ほどもありましたが、では自分が家を新築するだったり、改修するだったりというときにどれが使えるかとか、あとは自分たちとしてこの問題でどのようなことができるのかと考えたときに、一体化しているような。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-017"},{"speaker":"ゆきた副委員長","kind":"質問","question":"それで、１４ページの東京都や国の併用は可能ですかということで、よくある質問の中でありますが、この併用は可能であるということで回答があって、国と都の支援事業についても、ＱＲコードもついていて見られるようになっていますけれども、品川区と東京都、品川区と国では併用できても、東京都と国では併用できないものがあったりして、少し複雑だと感じています。","respondent":"中西環境課長","answer":"条件もかなり複雑になってありますので、一般的な制度説明など、そういったボード、それからこのページを見てくださいというような説明はできるかなと思いますので、その辺りはできる限りのことは努力いたしたいと考えていますので、取り組んでまいりたいと思います。","voiceIndex":44,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、１点だけ。だから、私は小さい小型の蓄電池を、やはり各家庭にできるだけ普及啓発していただいて、それぞれの場所で、できれば給電できるような、スマホを使えるようにするとか、簡単な電気のシステムは使える、あとは扇風機や何かは使えるような、そのような、何というのですか、体制だけは何とか私は早急に取っていただきたい。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-019"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これ以前も申し上げましたけれども、トイレトラック１台ではどうしようもなくて、いや近隣の自治体からも救援に来るのだというのですが、品川区がもし大災害に遭ったら、近隣自治体も、皆さんどこも大災害に遭っているわけで、とてもではないですけれども、１台では、デモンストレーションにはなっても、実際実働ではあまり効果が生まれないと思うので、その辺について将来、未来像というのですか。","respondent":"星災害対策担当課長、羽鳥防災課長","answer":"今回の訓練につきましては、トイレトラック１台について１台バキュームカーが来ます。そちらで十分吸い取りが可能な量ですので、今後もそのような形で考えているところです。私のほうからはトイレトラックについてご回答します。トイレトラックは、品川区では１台導入をさせていただいて、将来的に台数を増やす、今のところ計画はございません。","voiceIndex":53,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際公園も、空き地がこの品川区というものは本当に少ないので、公園に置けば、公園で避難している人が今度どこに避難していいかという、そのような諸問題たくさん出てくると思うので、この大都会の中の防災ということを私はしっかり考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"その中で１個だけ、これは小隊なので消防団が主だと思っているのです。だから、今は消防団だけではいいと思うのですけれども、これから先このような水防訓練なども、やはり地域の人たちに、やる気のある方やこのようなことに興味がある方を少しずつ入れていく方向性というものは、これから水防訓練にも求められていくのではないかなと思っていますけれども、その辺教えてください。","respondent":"星災害対策担当課長","answer":"水防訓練に対する区民等の参加についてのご質問かと思われます。地域によって様々な地域特性がありますので、今回行う水防訓練が、優先度が高い地域とそうでない地域とあると認識しております。","voiceIndex":58,"id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"地区防災協議会でしっかりご意見を聞いていただいて、地区防災協議会だけではなくて、やはりこのようなところにも、訓練の重要性がありますよということは、引き続き周知していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7049#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19135,"voices":66}},{"id":"r07-20250515-10","meetingId":"r07-cm05","date":"2025年5月15日","dateIso":"2025-05-15","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"常任・議運・特別委員会の構成","agenda":"常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今回、定数も９人ということで、無所属の方が入ってないということになってしまったのですけれども、これは少し前回も言いましたが非常に残念だと、意見として述べさせていただきたい。今回はこういう案で出されているのですけれども、やはり速やかに全会派の議員を入れるという構成に変えたほうがいいと思うのですが、ご意見があれば、委員長含めてお伺いできればと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-001"},{"speaker":"まつざわ委員長","kind":"質問","question":"例えば維新などの方から、議会運営委員会に入れてほしいというお話であったりとか、前も申しましたけれども、無所属の方が、ではこうしてほしいというお話が、実際、私の耳に入ってきていないのが現状でありますので、委員長としては、現状維持のままやっていきたいと考えています。ほかにご意見はありますか。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"先ほど述べたことが私たちの意見なのですが、正副委員長が今回、常任委員会が５つあって、特別委員会が３つとなりますと、合わせて１６個なのですけれども、そちらについての意見というのは、ここで言ってもいいでしょうか。それとも後がいいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年は、このポストが１４個あったのですけれども、選挙を経まして、結果的に自民党、公明党、未来の３会派が全て占めたということになりました。委員長ですとか、ほかの会派の皆さんのお考えをお伺いしたいと思っていますが、ぜひご意見があれば聞かせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、選挙という形ですが、私たちがあるべきだというのが比例配分方式で、各会派に数を割り振ることが最も民主的ではないかと思うのですが、そう切り替えたほうがいいのではないかと、今、選挙ですけれども、さっき言ったように、選挙となりますと、結果的に割り出した数にはならないですし、なおかつ大会派の方がやはり選挙をやればそれは数が多いわけですから当然勝つわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-005"}]},{"id":"topic-02","title":"土地開発公社議会選出評議員の推薦","agenda":"土地開発公社議会選出評議員の推薦","exchanges":[{"speaker":"せお委員","kind":"質問","question":"ごめんなさい。１つ前の附属機関なのですけれども、この１列目の数というところはトータルの数ですか。青少年問題協議会と、廃棄物減量等推進審議会あと都市計画審議会が１人ずつ足りないのでは。これというのは足した数ですか。それぞれ、青少年問題審議会だと６人いるのですけれども５と書いてあって、７番の廃棄物減量等推進審議会も自民から無所属まで足すと６名になるのですが、５と書いてある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7051#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":13138,"voices":73}},{"id":"r07-20250521-10","meetingId":"r07-cm05","date":"2025年5月21日","dateIso":"2025-05-21","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7053#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":3428,"voices":26}},{"id":"r07-20250526-10","meetingId":"r07-cm05","date":"2025年5月26日","dateIso":"2025-05-26","committee":"議会運営委員会","time":"午前１０時００分～午前１０時４５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議事日程(1)、追加議事日程および追加議事日程(2)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"当会派の木村議員が現在、歩行が難しく車椅子を利用している状況です。つきましては、車椅子で本会議に出席すること、採決時の起立が難しいため賛成は挙手によるものとしていただきたいということ、それから、副議長選挙において、投票箱への投票に当たって、事務局職員の方からの補助を受けること、以上３点をご了承いただけないでしょうか。ご検討よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"毎回そのたびに申し出があるのですが、恒久的に、その都度申し出がなくてもできるように改善できないのかという考えを持っていますので、もしよければそういった制度を検討していく必要があるのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7055#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":6376,"voices":47}},{"id":"r07-20250527-6","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"区民委員会","time":"午前１０時０７分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"共産党としても、今月、区長へ物価高対策として緊急要望していたものですので、今回このプレミアム付商品券の拡充が盛り込まれたことは大いに歓迎したいと思います。幾つか質問したいのですが、プレミアム付商品券で例年、実際に買われている商品や使われている店舗というのは、どこら辺が多いのか。そういう地域経済活性化の中身の分析というのはしているのかというのを、改めてお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"対面のほかに、説明会に出たけれどもよく分からないから後で電話で改めて聞きたいとか、説明会には行かないけれども電話で問合せをして聞きたい、今回の品川区のこの事業のためにＰａｙＰａｙのアプリをそもそもどうやって使ったらいいのかとか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"券種を２種類にしているではないですか。その理由を改めてお伺いしたいと思います。一方で商店主からは、ＱＲコード決済で商品を買っていただくと、２％程度はプラットフォームに手数料を取られてしまうと。実質２％の消費税を取られるようなことになってしまっているのですというような話も聞きます。ちょっとそこら辺がどんな仕組みになっているのかというのを教えてください。","respondent":"小林地域産業振興課長","answer":"ただ、一方で商店街支援という観点もありますし、中小店舗の支援というときに大型店舗ばかりで使われるという場合の逆の悪い影響というのもあると思いますので、他区の事例あるいは東京都以外の自治体でも既に導入されておりますが、こういった２券種をつくって。","voiceIndex":9,"id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問","question":"何点かお聞きしたいと思います。購入を希望したにもかかわらず購入できなかったという人が出ないようなための調整なのかというのはお聞きしたい。利用可能店舗が８,５００店舗とありますが、もちろん利用開始となる１０月には示されることになると思われますが、この点については、店舗はいつまでに示されるのかというのをお聞きできればと思います。そこについてお聞きしたいと思います。","respondent":"小林地域産業振興課長","answer":"システム利用料１,８１５万円とありますけれど、当初予算で載せていた４億円で１０％という部分の掛ける係数分とこの１,８１５万円を合わせたものを使って、今回秋のデジタル商品券の区民の方、店舗側の方が買う側、売る側の両方のシステムをこの部分で対応するという予算です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。ということは、ＰａｙＰａｙへの手数料負担については補填されないということになるのでしょうか。","respondent":"小林地域産業振興課長","answer":"安藤委員のご指摘にあったような店舗側の決済手数料との関係で多分ご質問されていると思いますが、決済手数料については、特段、品川区で直接補助するということは考えてございません。","voiceIndex":15,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ＰａｙＰａｙは店舗が導入するに当たっての初期費用もかからないですし、区が行う今回の物価高騰対策について、恩恵を受けたいという店舗も少なからずあると思います。これについて、キャッシュレスを促進する区の相談窓口の対応を進めていただきたいと思いますが、この対応については、今どのようなお考えなのかというのがまず１点です。ここについてお聞きできればと思います。","respondent":"小林地域産業振興課長","answer":"もう１つのご質問が、利用者側も同じでして、デジタル商品券の事業は今回一回限りとは我々は考えてはいませんけれども、今後コールセンターというのは申込みの時点だけで終わるのではなくて、使用期間あるいはそれ以外の問合せにも対応できるようにしていきたいと考えております。","voiceIndex":17,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"コールセンターで聞きながらアプリの活用について操作するのは難しいですし、説明会も日にちを逃したら諦めざるを得ないというふうには思いますので、ぜひこの期間の地域センターに行けば担当の方がいるなどの対応で、丁寧に進めていただければと思います。もし何かありましたら、お願いします。","respondent":"小林地域産業振興課長","answer":"今ご指摘の点、利用者に今回幅広く使っていただくというところが大事なポイントだと考えていますので、我々も最初の周知、こういう事業を始めますよとか、あるいはその使い方も含めて、説明会というのは、我々のイメージでいくと一対一の対面で、当然ながら画面を見せながら。","voiceIndex":19,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"今までのほかの委員の質問で何となくだんだん分かってきました。私からは、今回２５％にアップということでかなり購入が見込まれると思いますが、今まで紙だった店舗が、商連加盟店でプレミアムの紙のものだと１,６００店舗、これがデジタルになると８,５００店舗と随分増えるなと思います。この８,５００店舗の内訳をお願いします。出てくる中小店舗というのは同じものなのでしょうか。","respondent":"小林地域産業振興課長","answer":"デジタル商品券のほうは商連の直接の事業ではないにしても、商連とは話し合ってこういう仕組みを相談していますので、店舗側への説明ということでは、商連に加盟している方向けの説明会などもやりつつ、できるだけこの中で商連加盟店も増えていくようにというところで。","voiceIndex":22,"id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"紙のほうだと、今まで５００円が２５枚つづり。今回だと２５％なので２５枚つづりということで、紙面で５００円という券を持っていると、少し高額というか、それに小さなお金を足して買おうかなみたいな感じの買い方なのかなと思って、それでこの際に自転車もということも過去にあったのかと思います。それともやはり５００円といった単位みたいな、目安みたいな数字というのはあるのですか。","respondent":"小林地域産業振興課長","answer":"紙の商品券は５００円つづりで２５枚ということで、先ほど安藤委員へのご回答の中でお伝えしましたが、アンケートを取ると、実際の買物では、やはり紙の商品券の額だけ使うのではなくて、この機会にちょっと自分のお金も足して。","voiceIndex":24,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"確認","question":"ちょっと細かいところをまず確認させてください。１人というわけでありますけれど、これは年齢制限というのはあったのでしたか。改めてお伺いします。これは、対象は区民のみでしたか。それとも区外の方も買えるのでしょうか。仮にＰａｙＰａｙだとしたら、その契約方法というのはどのようになっているのか。その契約方法について、改めて教えてください。そこを教えてください。","respondent":"小林地域産業振興課長","answer":"実際その割合は１割いるかいないかぐらいなのですが、今回からこちらについては、区民か区内在勤の方というのを紙商品券の購入対象としております。デジタルのほうは区民ということで、これは本人確認をやりつつということで買っていただく形になると思います。","voiceIndex":28,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"私はいろいろなところで以前から言っていますが、そもそもなぜ当初予算で１０％だったのかと。これがなぜ当初予算では１０％にしているのか、もう不思議で仕方がなかったのですが、なぜこの時期に改めて２５％にしたのか。そもそもなぜ１０％だったのか。紙とデジタルの今回の補正予算額を見ると、デジタルのほうが圧倒的に事務手数料みたいな部分がかかっているわけではないですか。そこを教えてください。","respondent":"小林地域産業振興課長","answer":"お店側の対応です。","voiceIndex":30,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問","question":"委員の皆様の質疑で大体分かってきましたが、１点だけ。以前からキャッシュレス決済ポイント還元事業をやっていたと思いますが、それとの差というか、効果の違いみたいなところというのは、どのように考えられているのかと疑問に思ったので、お願いします。","respondent":"小林地域産業振興課長","answer":"キャッシュレス還元ポイント事業の中でもＰａｙＰａｙが使えるという意味では、確かに似たような部分があるというのは１つありますけれども、我々は今回、商品券のつくり込みをするに当たって、例えば区民か区民ではないかということを。","voiceIndex":36,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、今回プレミアム率が２５％ということですが、なぜこの時期にこういうふうに上げたのですか。関税だとかいろいろあるけれど、なぜこの時期に急に上げたのですか。では、このまま２５％でずっと行くのですか。上げることに関して私は賛成なのですが、それをしっかりつかんでおかないと、何だかという思いがやはり出てしまうから質問させていただきたいのですが、その辺はいかがでしょうか。","respondent":"小林地域産業振興課長","answer":"今回も１０％以上に上げるときに、どの辺が利用者側あるいは店舗側にとっていいのかと考えた場合に、３０％はさすがにそういう過去の反応もありましたので、ただし去年、令和６年の春に２０％でやっていますけれど、そのときよりもさらに悪い統計も出ていることから。","voiceIndex":42,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"このプレミアム率をつけた、こういう施策というときに私が質問しましたら、これは商店も含めて産業に対してのカンフル剤なんだという言い方を答弁でされていました。ただ、区商連も大事ですが、今回、品川区の消費者目線で言うと、やはりプレミアム率が高いほうがうれしいので、ありがたいので、その辺も考えていかないといけないと私は思いますが、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"区民にとって、区内店舗にとってよりよい方法があれば、それは引き続き情報も集めながら対応を改善していきたいと考えております。","voiceIndex":44,"id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"あれも今後どうやって使っていくのかというのはありますが、私は例えばこの額をデジタル商品券の利用料に出すのであれば、東京都と連携して商店街の活性化。これはおそらく秋ぐらいというか、１０月上旬というから間に合わないのかもしれないので今回はあれですけれど、ぜひそういうのも含めて検討していただきたい。その辺、もしお考えがあれば教えてください。","respondent":"小林地域産業振興課長","answer":"ただし、ポイントシステムがどういうふうに、そこ自体は東京都がつくるシステムを先にＰａｙＰａｙやｄ払い、楽天ペイといった民間のポイントシステムとつながるという仕組みはその中で充実していくということもありますので、その動向というのですか。","voiceIndex":46,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民生活の一定の下支え、区内経済循環につながることから賛成ですけれど、同時に、二定も控えておりますが、米高騰対策支援の支援金やお米券の配布や、あるいはインボイスと合わせた物価高騰、米トランプ関税の区内事業所・個人事業主の実態調査。それと省エネルギー対策、業務改善設備更新助成金の復活を、さらなる物価高対策を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7063#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19188,"voices":60}},{"id":"r07-20250527-7","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"厚生委員会","time":"午前１０時０８分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"１つ、４番の配送品のところで、１回あたり４,０００円相当のスポーツドリンクなどの飲料水ということなのですが、新聞報道だと２４本を……、下にも書いてあるのですが、２回に分けて１回あたり４,０００円というと、１回あたり４,０００円で４,０００円が２回ということではないのかなと思ったのですが、この４,０００を２回に分けてということで、１２本ずつ２４本ということでいいのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"熱中症予防を契機とした見守り支援が目的ですので、飲料配布はそのきっかけづくりということで捉えさせていただいて、今回は世帯数で飲料水の数をお配りするということで、世帯の人数によって数を変えるということは考えてはおりません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。水分摂取の状況とか、そういうのが入るのか、このアンケートの中身もお聞かせいただきたいと思います。そうすると、４万６,０００人もの人を分析して、支援が必要かどうかというところに選び出していく作業というのは、結構大変な作業になっていくのではないかなと思うのですが、そこのところは、高齢者福祉課がその体制というのは取られているのか、そこら辺のところも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"配送したときに１０問も２０問もいろいろと細かいことを聞くと、かえって多分、高齢者の方も警戒してしまうのではないかなというところなので、今回は熱中症予防にポイントを絞った四、五問程度の簡単なアンケートという形のイメージでしていますので、一人一人の。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当は温度計・湿度計を区でも配布してもらえないかなという思いがしているのですが、そういうところはぜひ必要ではないかなと思うのですが、そのところはいかがでしょうかというところです。それも同時に配布したほうがいいのではないかなという思いがしているのですが、その点もいかがでしょうかというところも少し伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらは、エアコンを上手に使いましょうとか、あとは、予防法ができているかのチェック項目などがありまして、この中の１つに部屋の温度を測っておりますかとか、そういったところを項目として、分かりやすくリーフレットになっておりますので。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、もう一つ、熱中症に対しての予防の啓発というところで、これを、もう本当に正しい知識を普及していくというところを組織的にやっていくというか、区としてもそういう取組というのをやっていただきたいなとずっと思っていまして、地域包括支援センターがあるところとかは、世田谷区に行ったときも、やはり熱中症については地域包括で、かなり地域に講座という形で、いろいろなところに対しての。","respondent":"菅野高齢者福祉課長","answer":"例えば今後、高齢者クラブ等へもっと啓発をというお話なのですが、今回、３万６,６００世帯の方たちに直接的にアウトリーチをさせていただいて、熱中症の予防啓発をするということがまず大きいので、そこの動きをまずは第一義的に考えているということと。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に熱中症に対しての、何というのですか、暑さも感じにくい。それと、最後に、区長が配布をするというところで、いろいろ新聞でも大きく取り上げられましたが、そのところに、都が体内の温度を確認できる腕時計型端末を高齢者に無料配布というところも書かれていたのですが、この中身が分かったら教えてください。","respondent":"菅野高齢者福祉課長","answer":"今後、熱中症の予防啓発については組織的に対応していくという部分につきましては、今回のこのアウトリーチで皆様のところに直接的に働きかけるということをきっかけに、そういった組織的な対応も今後は検討してまいりたいとは思っております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"ひがし委員","kind":"確認","question":"病院で勤務していても、毎年、夏には運ばれてきてということがあったので、事業として一つできるのはいいなと思う反面、記事を読まれた方からよくお問合せをいただくのが、認知症の方とかご高齢の方々が家にいて、詐欺とかと区別がつきにくかったりというところを、どういうふうに区として対策をしているのかというところと、あとは、もしご家族とかが。","respondent":"菅野高齢者福祉課長","answer":"お問合せの形の件につきましては、今回、コールセンター等も設置させていただきたいと考えていますので、配送のところでお問合せ先のダイヤルも表示しますので、何かご心配なことがございましたらコールセンターにお問い合わせいただいて、多分。","voiceIndex":18,"id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点は要望とさせてください。もし熱中症の対策と考えると、先ほどの鈴木ひろ子委員のお話があったように事前の予防というところが大切なので、６月から本当は動き出しておくのが一番効果的なのではないかなと思うのですが、その点についてのお考えをお聞かせいただければと思います。","respondent":"菅野高齢者福祉課長","answer":"本日、うまく補正予算が成立した暁には、次に事業者の選定という運びになるのですが、どうしても役所のシステムの中で、契約の公平性とか、そういったことを考えると、どんなに早く事業者を選定させていただいても、プロポーザルという形を取る以上。","voiceIndex":20,"id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"確認ですが、今回、一般財源で２億８,０００万円ほどになっておりますけれども、この一般財源を見て、財政調整基金の繰入金５億４,０００万円のうちの２億８,０００万円ということでよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"財政当局のほうから、そのような形でとは聞いております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"筒井委員","kind":"意見","question":"ということで、結構、今回の繰入れのうちの半分以上の額となっているのですが、今回、大きな額で、また、猛暑というのは比較的予想されていたことかなとも考えておりますし、先ほどひがし委員からも、熱中症対策だと、もう少し早めに想定しておいたほうがよかったかなと思うのですけれども、改めて、当初予算で組み込んでおけばよかったのかなと思っているのですが、今回。","respondent":"菅野高齢者福祉課長","answer":"今までも熱中症予防対策という事業は、民生委員や、あとは在宅介護支援センターのケアマネジャー等のご協力も得ながら、進めさせてはいただいておりました。","voiceIndex":25,"id":"exchange-009"},{"speaker":"筒井委員","kind":"確認","question":"配布されるものが１回あたり２,０００円相当ということで、だから、１回あたり１２本お配りするということで、１本あたり約１６６円程度ということでよろしいのかということと、あと、スポーツドリンクなどと書いてありますが、スポーツドリンクですと、糖尿病を患っている方とかは、あまり運動せずに飲むと、かえって危ないのではないかとかいうお声があると思うのですが、飲料水の内訳とか。","respondent":"菅野高齢者福祉課長","answer":"基本的には熱中症予防を啓発しつつも、全ての高齢者の体に優しい飲物が基本であると考えておりますので、例えばスポーツドリンクは糖分が少なめのカロリーオフにしたり、お茶はカフェインレスのある麦茶にするなど、そうした組合せなどを検討してまいりたいなとは思っております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"ぜひそうした体に優しいものをお配りしていただけるとよろしいかなと思います。最後に、事業者ですが、事業者は、単純に配送業者の方に委託されると考えているのか、それとも飲料系専門の卸売業者のところに頼むのか、どういったことを想定されていますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"そこに際しては、配送だけではなく、飲料水の調達から配送、そして、見守りの支援を行っていただくというところとコールセンターの設置などについて、全て一括で委託という形でお願いしたいと考えていますので、そこについては。","voiceIndex":29,"id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。配送のスキームですが、プロポーザルということなのですが、想定として、当然、事業者が決めるところもあるかもしれないですが、どれぐらいの人員で配送をしてもらうような、１日何人ぐらいの方が稼働するみたいなイメージというのはあるのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"そのあたり、事業者のスキームはいろいろと事業者によって違うのかなというところはあるのですが、区としてお願いするところとしましては、８月に１回目、２回目は９月というところで。","voiceIndex":32,"id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"確認","question":"それぞれの事業者に見積もっていただくというか、１日何軒回るかというのは、もうこれ、想定は出ているのですよ。だって、１回目が８月上旬で２回目が９月上旬、１か月なわけではないですか。そうなったときに、本当に１日１,２００軒回れるのかというところが結構、相当しっかりやらないと難しいかなと思うのですが、その辺は何か想定されていたりしますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"そのあたりの事業の展開、事業内容についてご説明させていただいたところ、見込みとしてはできるのではないかというお声も聞いておりますので、この事業スキームで進めさせていただければなと考えています。","voiceIndex":34,"id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"同じローテーションでずっと、１回目も２回目も回るなんて言っていたけれども、もしかしていろいろな状況で、「あれ、もう来たの」みたいなことになり得ると思うし、結構難しい、結構詰め込んだなという印象は正直受けるので、事業者選定も、本当に最短でこのスケジュールだということは分かるのですが、もう少し、猛暑というのはある程度、もう今年の数か月前から予定されていたことであると思うので。","respondent":"菅野高齢者福祉課長、寺嶋福祉部長","answer":"初の試みではありますので、いろいろと事業の組立て方が急だったり、いろいろな部分はありますが、少しでも本当に安全に高齢者の方たちに事業が実施できるように、最大限努力はしてまいりたいと考えています。ただ、やはりお配りするものの数や単価、それと、それにかかる配送料、いわゆる事務経費といったもののバランスを考えたときに、なかなか、これを最優先として打ち出すことがベストかどうかという、こういった議論も含めて。","voiceIndex":36,"id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"確認","question":"高齢者見守りということで、一応確認なのですが、同じような見守り事業で、昨年、こちらの厚生委員会で陳情も出されていましたが、長寿お祝い事業、基本的には高齢者見守りということでやっているという事業が入っていたと。となると、これ、９月上旬にも一応行かれるということで、かぶってしまうというのが多少あるかもしれない。その辺は特に関係なく、別々でやるということでよろしいですか。","respondent":"東野福祉計画課長","answer":"福祉計画課所管の事業です。同じ長寿見守りですけれども、１０月ではなく９月に行っております。当然、かぶる方はいらっしゃるかもしれませんが、目的が全く違うものですので、通常どおり実施します。","voiceIndex":39,"id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。ごめんなさい、スポーツドリンクなどの飲料水に関してですが、麦茶だったりスポーツドリンクだったりということで、その中にぜひＯＳ－１を、全部とは言わないですが、何本か入れておくと、もし熱中症、脱水しているなと思ったときはこれを飲んでくださいみたいな感じで渡せるといいかなと思うのですが、その辺はご検討はしていただけるでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今回お配りするのが、全ての高齢者の体に優しい飲物が基本であるというところから察しますと、もちろん熱中症になりかけたりという場合にはＯＳ－１がいいのですが、ただ、通常時に飲まれるという部分については、やはりカリウムとか。","voiceIndex":41,"id":"exchange-016"},{"speaker":"若林委員","kind":"確認","question":"補正予算ということで、契約はこのとおりでこれからですが、予算のいわゆる内訳、いわゆる商品関係、それから配達・配送関係、それからコールセンターもというお話もあります。大体その３つが大きな事業の柱になるのかなと思うのです。それで、この紙面には出ていないので、そこら辺、金額的なところを確認します。","respondent":"菅野高齢者福祉課長","answer":"今回の２億８,３６９万５,０００円の予算の内訳等についてですが、まず、配送費が８,５８６万２,０００円、そして、コールセンター運営費が３,０２７万２,０００円、そして、飲料費が１億４,４２９万２,０００円。","voiceIndex":45,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"少し数字があいまいですけど、少なくとも近年どんどんうなぎ上りというのですかね、右肩上がりで、熱中症にかかる方も多い。その上で、今の内訳もお聞きしましたが、これは２回の配送なのですが、いわゆる契約期間、特に配達のほうですかね、配送のお尻というのはどのぐらいで設定されているのかというのをお聞きするのが一つ。","respondent":"菅野高齢者福祉課長","answer":"不在の場合の再送というところで、今回、不在者連絡票にコールセンターの番号を書いて、コールセンターにお電話していただいて、再送を望まれた方にはもう一度行くという形なのですが、そこが、１回行って不在だったらもう不在者連絡票を入れて。","voiceIndex":47,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"それはやはり、今年度は補正予算という形でこの真夏の事業になったわけですが、では、来年度はどうしようかと。その辺の意識調査も含めて、一人でも多くの方に飲料水として、見守りとしてお会いする、お話を聞く、アンケートを取るというご努力は、１０月末ということでしたけれども、継続してこの事業の中で行っていただきたいなと思いますけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"２回目のアンケートの中で、「本事業については熱中症の予防に役立ちましたか」とか、あとは、「熱中症予防に対して希望するこのほかの取組などはありますか」というところで、幾つか項目をつくらせていただいて、聞き取りとかも、配布の中でアンケート実施ということで。","voiceIndex":49,"id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"非常に私はこれは、時間がない中ですが、成功裏に実施してほしいなと思っています。これはもうプロポーザルをされるわけですから、ぜひそういう視点を捉えていただきたいなと思っています。それから、お伺いしたいのは、これ、歩留りはどれぐらいで考えているのですか。これというのは、区が買い取るのですか。そうではなくて、配布した実績の本数で精算してもらうというやり方をするのですか。","respondent":"菅野高齢者福祉課長","answer":"一部の事業者にいろいろと実態をお聞きしたときには、実績で支払ってもらうことのほうがいいのではないかということで、事業者としては見込みで仕入れをするような形がいいのではないかなということを言っている事業者もおりました。","voiceIndex":52,"id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"本当にこれ、配達する期間も、先ほど来いろいろ出ているのだけれども、来年は来年で考えられるけれども、今年はもうこれでいくしかないのであれば、やはり事業者の方が、これでいくと１か月、３週間、２週間なのかとあるけれども、やはり特に９月は少しでも早いほうがありがたいわけだから、そこら辺はぜひお考えいただいて、ぜひいい事業者の方。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点ですごくプラスになる部分というのがあるのではないかなと思うのですが、せっかくこういう形で集計されて、区も分析をされるということなので、このアンケートの分析の結果については、ぜひともまた厚生委員会の中で報告をしていただいて、それをまた来年度にどうつなげていくかということにもつながっていくと思いますので。","respondent":"菅野高齢者福祉課長","answer":"もちろん事業についての、急に始まった事業ということもありますので、そういったことも含めて、報告できる機会がありましたら、研究していきたいとは思っております。","voiceIndex":56,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7061#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":21489,"voices":69}},{"id":"r07-20250527-9","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"文教委員会","time":"午前１０時０７分～午前１０時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第６７号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"すみません、すごく素朴な質問と、あとは、今回金額がそれほど、私の感覚では、何というのでしょう、あまり大きくないというか、１５７万４,０００円と２７９万８,０００円ということで、比較的元の金額がなかなかそれなりに大きいにもかかわらず、結構、何というのですか、少なめにというか、軽微で済んでいるような感じなのですが、これは先方からの申入れがあって、交渉の中でこうなったのか。","respondent":"芝野保育入園調整課長","answer":"続きまして、今回の金額が軽微なのではないかというご質問ですが、毎年インフレスライドによる対応は発生しておりまして、実は令和６年度もインフレスライドによる請求を適用させていただいて、ここで補正を組ませていただいているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。内容については分かりました。先ほどありましたように労務単価ということですから、いわゆる職人の報酬というか、そのようなものが上がってきているのかなという認識ですが、資材ということではないのかなというところで、ありがとうあります。ではちょっとまとめて、最後私立幼稚園のほう、いわゆる物価高騰の私立保育所等運営事業者の支援について伺います。","respondent":"佐藤保育事業担当課長","answer":"民間の保育施設は非常に人数が少ないところもございまして、１施設１万３,０００円の６か月ですので、１０万円いかないぐらいの金額ということになりまして、その程度の差は発生するものかというように認識しております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"議決をするに当たって、５％以内であれば議決なく専決処分でできるのだと思うのですけれども、これはすみません、計算すればできるのでしょうが、５％を超えているから今回議案として出てきているのかという、ちょっとその辺を、まず最初の保育園のほうの内容についてお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"今回の契約変更におきまして議決額の５％を超えましたので、第２回定例会において契約変更の議決をいただく形になるかと思います。あくまでもこれ予定ですが、というような、今流れになっております。","voiceIndex":14,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"内容は分かりました。施設整備課のほうで詳細は担当されているということなので、そこは後で確認をさせていただきたいと思います。金額で単純に比較して、都の補助金よりも実際に支給される金額、補正額のほうが高いのですけれども、都が補助金の対象ではないけれども、区が単独で補助を出すところがあるのかどうか、あると思うのですが、それは具体的にどこなのかをお伺いしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"本補助事業の東京都の対象外の施設ですが、対象外の施設は、私立幼稚園および公設民営保育所等となります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"１点確認をしたいのですけれども、都が対象にしなかった私立幼稚園に対して、ちょっとまず、すみません。なぜ都が私立幼稚園を対象にしなかったのかということが、もし分かればお伺いをしたいということと、都が対象としなかった私立幼稚園に対して、逆になぜ区は補助をしようとしたのか、そこの区のお考えをお伺いしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"同様の考えをもちまして、物価高騰に対する補助は令和４年より実施しているのですが、そのときから私立幼稚園も対象としておりまして、補助の継続性という観点からも、対象とすることが適切であるというように認識しております。","voiceIndex":18,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"区がそのような物価高騰に対して、施設運営、あるいは保護者負担の補助をすることによって、保育の質の低下を防ぐというお考えということは分かりました。逆に今回の補助をするに当たって、私立幼稚園側から、物価高騰によって保育の質の低下につながりかねないから補助してくださいという要望があったのでしょうか。そこを確認したいと思います。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園側からの本事業に対する要望についてですけれども、正式に私立幼稚園協会等々を通じた要望というものはいただいてございませんが、幼稚園協会などの園長会などを参加するときには。","voiceIndex":20,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"幼稚園協会側から要求、要望がないにもかかわらず、このように税金を投入するということですか。区の思いとしては、物価高騰に伴って保育の質につながりかねないという思いからだというお話がありましたが、一方で私立幼稚園側から要望がないということは、今回の物価高騰程度では保育の質の低下にはつながらないという判断をしたから要望がなかったというようにも思えるのです。","respondent":"佐藤保育事業担当課長","answer":"一方で、委員のお話のように、その後の効果検証につきましては、区としてもしっかりと対応していきたいと考えております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"山本副委員長","kind":"質問・要望","question":"この物価高騰に対応した私立保育所等運営支援事業者についてなのですけれども、各支援金額の算出根拠のところ、私立保育園等や公設民営保育園所等は、在園児数１人当たり８６４円、１か月当たりで試算していて、６か月相当ということで、物価高騰で１人当たりこれぐらいの影響があるということを考えていらっしゃると思うのですが、何かその根拠、これが都から示されているのであればそれでいいですし。","respondent":"佐藤保育事業担当課長","answer":"区といたしましても、昨年１年間事業者が支払っている費用等々と消費者物価指数の動向を勘案して、妥当な数値であるというように認識しています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"山本副委員長","kind":"質問・要望","question":"こちらも分かりました。それからこの支援のやり方、申請や補助金の交付については、円滑で手間がかからない手法等に努めていただきたいと思いますので、これを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれ物価高騰に対する対応はやむを得ない事情として了解はするのですけれども、特に私立幼稚園については、今の質疑を通じて、先方から要望がないが、区の思いとして補助金を出すということでした。この意味合いは、半分理解し、半分理解できないところであります。それで、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7057#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":10172,"voices":43}},{"id":"r07-20250527-5","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"総務委員会","time":"午前１０時０７分～午後 ０時０９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６８号議案、専決処分の承認を求めること","agenda":"第６８号議案、専決処分の承認を求めること","exchanges":[{"speaker":"西本委員","kind":"質問","question":"４番の専決処分とした理由で、改正地方税法の公布、令和７年３月３１日ということなのですけれども、当然専決処分せざるを得ないという状況だと思うのですが、これはこのようなものなのですか。今回特別このような、専決処分しなければいけない状況になってしまったのか、いつもこのような状況が出てくるのですか。それはいかがでしょうか。","respondent":"宮澤税務課長","answer":"３月３１日に法案が成立してというところで、４月１日から施行ということ、そして軽自動車税が４月１日が基準日となっているところから、時間にゆとりがないということで専決処分させていただきましたということです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"その流れは分かるのですけれども、３月３１日に決めて４月１日からということはあり得ないではないですか。ですから、このようなことをやられてしまうと、全部専決処分にすれば終わりなのという形になってしまうので、なぜこのようなものか、分かります。品川区がどうこうできるものではないということは分かっています。","respondent":"宮澤税務課長","answer":"地方税法の改正の内容というものが、いわゆる住民税に係るものなどがあります。そのうち、特に軽自動車税に係る部分というものが４月１日が基準日というところで、専決処分ということになる可能性が高いです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"この間国の動きというものが、突発的なものが多くて、それは地方にしてみれば、なかなか話し合う場を設けられないというようになって、通年議会というようにするということもあれば、いつでも議会が開かれると。国はやはり地方のことも考えてやってほしいなという要望も必要かなと、これは意見として言わせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も今の西本委員と同じような思いなのですけれども、でも国がこのようにしてきているし、ここがこのような期日なので、致し方ないのかなという思いはありますが、今回は車両区分の見直しということで、この総排気量１２５cc以下で、最高出力を４.０kw以下に制御したバイクというものがどのようなバイクなのか、ちょっとイメージがつかないのですけれども、１番の概要の一番下に。","respondent":"宮澤税務課長","answer":"５０cc以下の原付自転車があって、オートバイ等が、いわゆる排気量というところで５０cc以下、１２５cc以下というものがあって、その排気量、いわゆるエンジンから排出されるところの二酸化炭素の排出量ではなくて、一酸化炭素や炭化水素などの化学物質の排出。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、今５０cc以下の原付に乗っている方は、今後もずっと、もし大事に乗っていくという状況であった場合、どうなっていくのですか。","respondent":"宮澤税務課長","answer":"現在乗っていらっしゃる５０cc以下については引き続き乗っていけますし、もしそのオートバイをどなたかに譲渡する場合、引き続き５０cc以下原付としての登録もできるです。ただ、１１月以降は、新車での販売流通というものはなくなるということです。","voiceIndex":13,"id":"exchange-005"}]},{"id":"topic-02","title":"第６７号議案、令和７年度品川区一般会計補正予算","agenda":"第６７号議案、令和７年度品川区一般会計補正予算","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、こうした今回の飲料水の配布で、アンケート等も取られる中で、こういったエアコンについても聞く項目というものはあるのかどうかということを伺いたいということと、やはりこのようなところへのエアコンの設置とか、エアコンを使うための電気代の補助とか、そうした対応を区としても求められているのではないかなと思うのですけれども、そこはご検討などはされているのか伺いたいと思います。","respondent":"加島財政課長","answer":"その観点から、今電気代の補助は考えておりませんが、国のほうで今後７月、８月、９月、電気代支援が入ってまいりますことと、５月以降も燃料価格の下落によりまして、６月支払い分の電気代のほうから値下がりをしていくというような報道も見ておりますので。","voiceIndex":30,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。電気代を直接補助することは難しいということですけれども、この間も物価高騰やエネルギー価格の高騰ということで、何というのですか、電気代は直接ではないですが、やはりエアコンの設置の補助や、それをさらに増額するなど、そうしたことはできると思いますので、引き続き熱中症予防という観点から、対策を進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"確認なのですが、歳入のところに基金繰入金もあるのですけれども、民生費の中で、これ１０分の１０になっているのです。それで、財政調整基金繰入金、５億４,０００万円余で、歳出のところが、高齢者福祉費に２億８,３００万円余です。その残り２億何がしかのものというものは、プレミアム商品券ということで計算された形になっていますという理解でいいでしょうか。確認したいのですけれども。","respondent":"加島財政課長","answer":"この中の保育所のうち、公設民営の保育所、それからぷりすくーる西五反田、私立幼稚園につきましては、これは都補助ではなくて、区の一般財源での対応となりますので、その分での基金繰入金となります。","voiceIndex":34,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"だから、細かい話はそれであったのですが、まず非常に不思議な点が何点かあって、なぜ当初予算で見なかったのですか。当初予算に入れるべきではないのか。なぜかというと、もう今回の補正予算が決まって、それで業者選定になって、実際の配布は７月中旬、それで９月ですね。なぜ当初予算に入れられなかったのですか。そのような検討もなく、唐突に今の時期にポンと出てきたということはなぜなのですか。","respondent":"加島財政課長","answer":"電気代そのものにつきましては、経済対策として国が支援を発表いたしましたけれども、基礎自治体として、気象庁からこのような発表と、また物価がこのような上昇をしているという中で、区としても何かできることはないかというところで。","voiceIndex":36,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"なぜ入れ込むことができなかったのですか。私はそれは、タイミングといっても、ここ数年間の気象状況を見れば、当然ながらそのファクターというものはあるわけであって、いきなりここに取ってつけたように来て、それで準備もままならない状況、業者もどのような状況でやってくれるかも分からない、そのようなことで見切り発車するということは、私はどうかなと思うのですが、いかがですか。","respondent":"加島財政課長","answer":"そういった状況を受けた中で、次年度、つまり令和７年度に向けて、こういった熱中症対策の検討がなされなかったのかというご質問かと思いますけれども、検討はしてまいりました。","voiceIndex":38,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"スキームもまだ全然決まっていないではないですか。中身も分からない、研修するのかどうかも分からない。現実難しいです。いつから現実的に配れるのかといったら、かなりずれてくるのではないですか。私も今見守りで地域の方を伺っていますけれども、出てきません。ではこれ何％が目標なのですか。暑いし。１世帯につき幾らということが出てくるではないですか。そこの細かい計算はしているのですか。","respondent":"加島財政課長","answer":"その上で３万６,６００世帯に必要な配送料、それから保管庫、コールセンター等の対応等を含めまして、今回予算額として提案させていただいたものになります。","voiceIndex":40,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"そうなった場合に、契約金というものはこのままなのですかということが１点、途中で変えるということもあり得るのか。これ１００％、当然です。やるのだったら１００％。１００％やりたいという意気込みは分かるけれども、いろいろな高齢者のことを、状況を考えたりしたら、結果によっては非常に無駄が多くなるのではないですか。それを想定した形で、これは予算をかけているのでしょうか。いかがですか。","respondent":"加島財政課長","answer":"１点目の契約の件ですけれども、高齢者と話してアンケートを取る、それからアンケートの結果、この方の状況について懸念がある場合には区のほうに連絡をするといったことは、業務の中の仕様として入ってまいりますので、これについて業務が生じたからといって。","voiceIndex":42,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"長くなってしまって、申し訳ない。長いですよね、ごめんなさい。出てこない。それは恐らく１割、２割のところではないと思います。もしも被害があったらどうするのですかということ、それも想定していなければいけないですよね。ですから、そこの犯罪に対しての対応をどう考えるのか、区の責任はきちんと取ってくれるのですよねということです。最後にですが、１つ要求がある。ペットボトルを送るでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、これ大切なのでいいですか。ペットボトルの蓋は高齢者になると開けられないのです。それをすごく言われました。蓋開けの、何かあるではないですか。それも入れなければいけないよねとか、ではその使い方は分かるのかと。使い方が分からないよねなどということもあるのです。それで、高齢者の方から非常に言われたことが、これ最後意見でまとめますけれども、要らないと言われています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"飲料水はいいのですけれども、去年の秋から今年の５月まで、ずっとお米の問題が、もういろいろなテレビ局でやっていたら、飲料水もいいですが、やはり生きていくためには、お米、食べるものというのが大事なので、私はそのようなことも考えてほしかったなと。そして、先ほど防犯の話もありました。質問というよりは意見だけ言わせていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"先ほどの質問の答弁をいただきたかったので、安全面の保証の件と、区の責任はどこまでありますか。それから蓋の件、法で決められるということではないと思うのですけれども、その２つ、ご答弁お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-016"},{"speaker":"新妻副委員長","kind":"質問","question":"１点だけ。長くなりましてすみません。そして厚生委員会の資料では、１回当たり４,０００万円相当というように書かれておりますけれども、そうすると、お一人当たり２回ということなので、お一人当たり８,０００円分、金額に換算すると８,０００円相当の支援というように受け取めてよろしいのでしょうか。","respondent":"加島財政課長","answer":"見守り支援としての委託ということを考えているところです。それから４,０００円相当のというところですけれども、こちら１回の飲料の配送で、１２本を配送します。その１２本を２回分、２４本で、配送料も含めて４,０００円相当という形になります。","voiceIndex":52,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成ですけれども、やはり、先ほども言いましたが、エアコンの設置の補助、そして電気代も直接は難しいという話でしたけれども、生活保護受給者の方々などには、夏季加算という形で、直接電気代という形ではないですが、そのような形で支援はできると思いますので、そういったことも考えて、安心してエアコンをつけられて、そして品川区からも飲料が届くとなったら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-018"},{"speaker":"松本委員","kind":"意見","question":"賛成です。そしてどうするかと考えたときに、人と人というものは、先ほどの強盗の件や詐欺の件などがあって、結構限界も来ているのではないかと私は思っていて、そうすると見守りというものは、今は電子端末でもある程度できる部分が出てきているので、この事業を踏まえて品川区の見守り事業、高齢者の見守り事業というものはもう１回整理してもいいのではないかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"だけれども、それを含めて、やはり短絡的に考えるのではなくて、十分な議論、十分な状況把握、そうしないと税金ですから。税金使うわけです。１円たりとも。１００％できるという保証はありません。なぜならば、準備が不十分だから。それも１００％が目標だ。ではどこに目標を持つのですか。どのぐらいのロスはあるのですか。そのロスはよしとするのですか。いろいろな必要なものがあるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7065#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":18366,"voices":65}},{"id":"r07-20250527-10","meetingId":"r07-cm05","date":"2025年5月27日","dateIso":"2025-05-27","committee":"議会運営委員会","time":"午後 ２時１４分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7059#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1306,"voices":11}},{"id":"r07-20250609-6","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"区民委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"藤原副委員長","kind":"意見","question":"副委員長です。藤原です。長年席があっちだったので、斜めから理事者を見ることしかしなかったのですけれども、正面から見るとこうなるのですね。それが一番今は感激しております。今後ともよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"区民保養所のあり方検討の開始","agenda":"区民保養所のあり方検討の開始","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"私から１点だけお伺いします。外部有識者を交えた検討体制による検討を行うということですが、どういった方を予定されているのでしょうか。","respondent":"平原地域活動課長","answer":"現在どういった方がいいのかといったところを内部で探している状況ですけれども、これは例えばですが、保養所事業についてお詳しい方や、建物ですので、土地、建物などの資産に詳しい方、そういった方々を中心にお願いできればと考えているところです。","voiceIndex":38,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"意見","question":"スケジュールが令和７年６月から９月までということですので、これから３か月間かなと思います。その中で検討期間中に２回程度会合を実施ということですが、広く意見を取っていただいて、他区における保養所事業の状況なども調査しながらと書いてあります。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"今回このような検討会を開始するということですけれども、これまでこの保養所に関しては、様々な課題というか、一番は利用率ということは、かなり前から課題となっていました。ここへ来て、今検討が始まったということは、どのような背景で、もっと前からこの検討会はあってよろしかったのかなと、私はそのような感じがしているのです。今この時点でこれが始まったという、その経緯と背景を教えてください。","respondent":"平原地域活動課長","answer":"今回それに加えまして、やはり建物の老朽化や、さらに今後を見据えたところで、大規模改修から既に３０年ぐらいたっているというような利用施設もありますので、今後どのくらいのコストがかかっていくのか、あるいはそれに伴って、現状の利用率が今後どのように推移するのか。","voiceIndex":42,"id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"いわゆる、これまでの課題で、様々な利用率だったり、アピールだったりされてきたと思うのですけれども、改めて、区民の方の、いわゆる健康増進という、こうした観点もこの保養所にはあるといったところからすると、これまでどのような区民の方へのアピールなり、利用促進に取り組んでこられたのか、改めてその辺を確認させてください。","respondent":"平原地域活動課長","answer":"一定数の固定客の確保はできているということは運営事業者から聞いているところですけれども、今言った、これまでの広報しながわを中心とした広報媒体でやってきたというものが正直なところでございまして。","voiceIndex":44,"id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"その辺のところをしっかり、これまでの取組と、そして事業者に委託をするときの、区の保養所に対する、何でしょう、思いというか、このような形で運営してもらいたい、あるいは保養所の在り方というものがどのようにされてきたのかというところの面も振り返りながら、検討を進める必要があるのではないかと考えるのですが、その点についてはいかがでしょうか。","respondent":"平原地域活動課長","answer":"今ご指摘のとおり、委託に変えた時点といったところにつきましては、区の、例えばかつてでいくと直営だった時代、それから業務委託だった時代、それから今回無償貸付けと、様々な形態をたどってまいりましたけれども、その時点、その時点で、やはり課題を踏まえまして。","voiceIndex":46,"id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"提案","question":"事業者もいろいろ季節の食べ物、お食事にしても、結構いろいろと提案されていて、お泊まりになる方もそれを楽しみにしている方もいるわけです。ただ、光林荘だと、ここにも教育委員会と協力すると書いておりますけれども、会議体として、有識者の方を入れて教育委員会もメンバーに入るという、協力と書いてあるから、どのような関係性で協力体制を取るのかということをお尋ねさせていただきたいと思います。","respondent":"平原地域活動課長","answer":"こちらの資料の中で教育委員会が協力するというように書かせていただいたのは、区民保養所としての光林荘は、あくまで地域活動課が所管している関係で、私どもがやはり責任所管としてしっかり責任を持っていくといったところですが、今委員ご指摘のとおり。","voiceIndex":49,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。教育委員会と協力体制を取って、あくまで教育委員会、あと現場は現場の学校管理者がいるわけではないですか。校長先生など学校側の現場の方も、その会議体の中に入れて発言をしてもらうという認識でよろしいですか。","respondent":"平原地域活動課長","answer":"実際の検討につきましては、外部有識者も交えた形でおおむね２回ほどという形なので、全部集まって何か発言をその場でしていくというようなことを考えているよりは、調査をどんどんかけていって、その情報をどんどん共有してその場に意見を出す。","voiceIndex":51,"id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。それで、３か月の期間があって２回程度と会合がなっているではないですか。それで集約して、まとめて今度議会のほうに、区民委員会に報告と書いてありますけれども、おおむねこの２回で大体その検討というものはまとまるのかなと、私はそのように思っているのですが、それが３回になる可能性もあるということでいいのですよね。","respondent":"平原地域活動課長","answer":"ご指摘のとおり２回という形ではなくて、２回程度と書かせていただいているのは、今現状では一番最初と最後といったところで、それ以外につきましては私どもが個別で説明するとか。","voiceIndex":53,"id":"exchange-009"}]},{"id":"topic-03","title":"しながわシティラン開催報告および次回開催に向けた進捗","agenda":"しながわシティラン開催報告および次回開催に向けた進捗","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"この点について、どのようなお声があって今回車椅子の方を、また、この項目を入れたのかという点と、視覚障害など、ほかの障害がある方も参加をしたいというようなお声は聴いているけれども、なかなか一般の方と一緒に走ることは難しいかもしれないから配慮をしてほしいというようなご要望もいただいているのですが、その点についてどのような体制を取っていくのかという。","respondent":"守屋スポーツ推進課長","answer":"障害者団体の方にもご意見をいただきながら、先日も説明させていただいて、危険な点や、気をつける点があるというところを意見交換して、今回の開催にそこを反映させていきたいと考えているところです。","voiceIndex":59,"id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ、車椅子に乗っている方だけではなくて、ほかの障害を持っている方々に対するご配慮というところも今後検討いただきたいなというような趣旨での質問だったので、車椅子以外の方に対する対策や、一緒に参加できるような機会というものをこのしながわシティランでも反映させていただきたいなと思うのですけれども、その点についていかがお考えかというところを教えていただきたいと思います。","respondent":"守屋スポーツ推進課長","answer":"２点目の、より参加しやすい大会に向けて、いろいろな意見をいただいておりますので、そちらのほう、２０２６大会、または次回以降の大会に向けて、いろいろな意見がありますので、できるだけ参加者の方々に満足していただけるような形で進めていきたいと考えております。","voiceIndex":61,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"質問・要望","question":"安全が第一だと思うので、救護体制について、医師会とまた相談をしながら、よりよい形を取っていただければなと思います。今回と次回と、同じ道のコースというようにお話しになっているのですけれども、そこの混雑状況などについては把握をしていると思うのですが、その改善案があれば教えていただきたいと思います。","respondent":"守屋スポーツ推進課長","answer":"もう１点につきましては、ランナーを１,５００人のグループと１,０００人のグループの２回に分けて、５分間隔を空けてスタートさせるという、ウェーブスタートということを取り入れることで、一斉に２,５００人がスタートしますとやはり混雑しますので。","voiceIndex":63,"id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問","question":"実行委員会がまた今年度も既に立ち上がって、次回に向けて既に話合いが持たれているということですが、前回参加された方からも、アンケートなどというものは取られているのでしょうか。","respondent":"守屋スポーツ推進課長","answer":"約８５％の方が「次回も参加したい」という回答と、「場合によっては参加したい」という回答を含めますと、約九十八、九十九％というところで、おおむね好評という、少し母数は少ないのですけれども、評価をいただいているです。","voiceIndex":67,"id":"exchange-013"},{"speaker":"おぎの委員","kind":"質問・要望","question":"やはり後半は、だんだんばらけてくるので道が狭くてもいいのですけれども、スタート時はやはり広い道のほうがいいなという意見はありましたので、先ほどの２車線や、急にボトルネックをつくらないなどという話も含めて、幅の部分で見直せる部分があったら見ていただきたいなということと、やはりデフリンピックも今年度ありますので、その流れで一緒にスポーツを打ち出していくという観点からすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"ボランティアについてお聞きしたいと思います。ボランティアの方々にも振り返っていただくというか、アンケートなどを取られたのか、いわゆるボランティア活動の中で気づいた点など、お声をいただいているかどうかといった点、その辺の当日のボランティアについての活動の総括について教えていただきたいと思います。","respondent":"守屋スポーツ推進課長","answer":"本年度につきましては、１５０人程度に参加していただきたいということで見込んでおるのですが、前回大会のところでも、参加されたボランティアの方から、主に警備などをやっていただいたり。","voiceIndex":74,"id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7081#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":39548,"voices":86}},{"id":"r07-20250609-7","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"厚生委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"委員長に確認で１点、今回、特別委員会の中で、まちづくり・公共交通推進特別委員会のところで大井町のまちづくりということが入っているのですけれども、大井と八潮。議会運営委員会でも何度か確認をしたのですけれども、その中に地域の医療連携というものも項目に入れてあるはずなのですが、それについては当委員会で議論してもいいということでよろしかったのかどうかが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど時期、ごめんなさい、７月とおっしゃっていましたか。時期と、あと、ボリューム、どれぐらいの数の方、先ほどおっしゃっていたと思うのですが、ごめんなさい、聞き取れなかったので、書き取れなかったので、もう一度、対象の方がどれぐらいいるのかということと、送付の時期について教えてください。","respondent":"山下国保医療年金課長","answer":"答弁漏れで失礼いたしました。時期につきましては、国民健康保険につきまして、令和７年７月中旬以降を目途に送付を予定しています。","voiceIndex":52,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう中で、どれくらいマイナ保険証の利用率になっているのかというのが分かったら教えていただきたいのと、ぜひ品川区としても、渋谷区や世田谷区のように、全ての国民健康保険加入者に資格確認書を交付していただきたいと思うのですけれども、そこら辺のところは検討はされたのか。ぜひそうしていただきたいと思うのですけれども、いかがでしょうかということでお願いします。","respondent":"山下国保医療年金課長","answer":"実際に今のルール、新たな仕組みの中では、マイナ保険証の利用をこちらとしてもお勧めしていくところはありますので、当然、資格情報のお知らせと資格確認書と適切に対応していきたいと考えていますし、先ほど冒頭にご質問いただいた趣旨の中にも。","voiceIndex":58,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ほかのところで質問させていただきたいのですけれども、まず、福祉部の一番初めの組織のところなのですが、今回のところで、人数的にも福祉部のところで体制強化がされていると思うのですけれども、それから、新たに設置された担当というのもあると思うのですが、例えば、障害者就労支援担当というところも新たに設置されたのではないかと思うのですけれども、それと介護人材確保定着支援担当。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"そのため、障害者支援課としても、働きたい障害者の方がご希望に沿って就労が実現できるように支援するために、障害者就労支援担当を新たに設置したものです。他区の、全国平均とかも見ますと、同じような日数ということで、３０日を過ぎる場合にはお知らせをするということが決まりとなっておりますので、しっかりとお知らせをすることと、あとは、緊急的にサービスが必要な場合には。","voiceIndex":60,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"ほかは体制強化をここのところはしましたというのはないものなのかどうなのかということと、それから、２ページのところで、会計年度任用職員というのは、これは常勤換算の人数ということで考えていいのかという点についても伺いたいと思います。引き続いて伺いたいと思うのですけれども、福祉計画課の３ページのところなのです。","respondent":"東野福祉計画課長","answer":"私からは、まず、組織のところの体制強化のところ、福祉計画課のところも説明したと思っていたのですけれども、再度説明させていただければと思います。施設担当です。","voiceIndex":63,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"開かれるようになったということは非常に評価をしておりますけれども、せっかく医療的ケア児支援というところに踏み込んだのであれば、もう少し具体的な議論に深められるような回数の開催とか、もちろん参加されている方たちがお忙しいメンバーだというのはすごく重々承知なのですけれども、せっかく開かれるのに、１回やって、次はもう１年のまとめみたいなのだと。","respondent":"松山障害者支援課長","answer":"地域自立支援協議会につきましては、非常にテーマが幅広くて、それぞれ下位の部会が、専門部会がございまして、今年度は、相談支援部会、子ども支援部会、就労支援部会に加えまして、精神の部会を発足するということで、こちらには全体会の回数は書かれているのですけれども。","voiceIndex":68,"id":"exchange-006"},{"speaker":"やなぎさわ委員","kind":"質問","question":"事務事業概要なので、大枠でお伺いしたいのですけれども、福祉部の事務事業概要、紙で高齢者福祉課の３１ページ、電子だと６５ページのところなのですけれども、介護人材の不足が叫ばれているということで、区としても非常にその切迫感を捉えていただいていると思うのですが、今、人手不足というところの対策として、やはり区としても外国人人材を受け入れていく。","respondent":"菅野高齢者福祉課長","answer":"外国人に限らず、あと、ＩＣＴの導入によっての業務の効率化とか、あとは、元気な高齢者の方にも支えていただくとか、いろいろな手法はありますが、その中の一つとして、やはり外国人人材というのは大変貴重な要員だと考えていますので、区としては。","voiceIndex":72,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、週２０時間というのが、移動時間を入れるともっと、２５時間とか２６時間とか、そういう時間になってしまうので、実際は２０時間というのが、移動時間も入るともっとたくさんの時間になるので、移動時間も入れて２０時間にするとか、もっと短い時間でも対象にするとかという形で拡大を検討していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ありがとうございました。営業所は対象にならないと言われたということで伺ったのですけれども、そこのところは確認させてください。東京都の制度が使えるところは、ぜひ区の制度も使えるようにしていただきたいということと、２０時間というのは、せめて移動時間も含めたようなことでもぜひ検討いただきたいということで、これは要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"ここで聞かないと聞くときがないので。これ、大きなところなので、ぜひそこのところがどのような形で検討が進められていくのかということを教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-010"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことからすると、幾つかそういう病院はありますので、そういうところでも受け入れてもらえる可能性はあるのではないかと思っていまして、ぜひそういうところで進めていただきたいと思っているのですが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"私どもも、この森山リハビリテーションクリニックの休止については、非常に驚きとともに、今後、本当に何とか区内で医療ショートステイ事業を実現させるためにも、区内の様々な医療機関にさらに積極的に働きかけを行ってまいります。","voiceIndex":86,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7079#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":45171,"voices":92}},{"id":"r07-20250609-8","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"建設委員会","time":"午後 １時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"石田しんごです。建設委員会ですから、建設的な議論をしていきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"何かこのところ２年ごとに入れ替わっていらっしゃると思うのですけれども、東京都と品川区でどのような取決めで派遣してもらっているのかなども伺いたいと思います。現在着任されている部長の、東京都で経験されてきた主な略歴というのですか、どういった業務を経験されて品川区に来ているのかというのを伺いたいと思います。","respondent":"高梨都市計画課長、鴇田都市整備推進担当部長","answer":"それぞれ派遣している場所によって開始の年代は異なりますが、そういった理由で派遣をしています。経験ということでご質問がありましたので、私からお答えします。","voiceIndex":57,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"４月２４日に令和７年度羽田空港の機能強化に関する都および関係区市連絡会分科会が行われたのです。ここというのは何かあまり委員会に報告がないと思うのです。私はやはり区民に関わる大事なところなので、今後委員会に報告というのはあるのか、それとも今までもしていたのか、そこら辺、私は委員会に今後報告すべき事項だと思うのですけれども、区の認識はいかがでしょうか。","respondent":"高梨都市計画課長","answer":"区といたしましては、分科会の開催のたびというよりは、しっかりと国の動きを察知させていただいて、しっかりと委員会に報告すべき内容が出てきましたら、分科会の開催有無にかかわらず、当委員会のほうには報告をさせていただきたい、そういう回答です。","voiceIndex":60,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は開催のたびに、ぜひ建設委員会、所管の委員会には報告してもらいたいですし、それは委員長、今後ぜひ運営の中でそういったことをしていただけるとありがたいという、これは要望します。何か取決めなどはあるのでしょうか。現在就任されている担当部長の自衛隊での経験されてきた主な任務というのはどのようなものだったのか、こちらも伺いたいと思います。","respondent":"羽鳥防災課長、七嶋災害対策担当部長","answer":"そういったところで、区の部隊を動かすという部分と実際の災害対応、そういったところが区の防災対策に非常に有効だということで、その知見を区の行政のほうにも還元していただいているということになります。風水害以外の災害派遣等におきましては、京都府における鳥インフルエンザ、また東日本大震災におきましては、福島第１原発対応等に参加をいたしました。","voiceIndex":62,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"２年ではなくて５年でした。すみません、失礼いたしました。改めて今回は両部長のところについて伺わせていただきました。私からは以上になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-005"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"所管事務調査は、今物価高騰などで大変あちこちで破綻が来ている再開発を取り上げたいです。再開発問題というのは、このまま今までのようなやり方で進めていいのかということがあるので、ぜひ所管事務調査に入れていただきたいという意見です。前段の道路大会の件についても一言いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"意見","question":"災害対応とか、あと防災対策について、案として一つ挙げたいと思います。避難所整備についても今後課題だと思いますので、あと、それに防災に含めて全体的に見てマンション防災とか、あと木密の整備についても含めて、災害の対応について案として挙げられればと思いますので、お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"事実なのでしょう。出席していたらごめんなさい、私はネットニュースでしか分からなかったので、やはり一言説明いただきたいです。せっかく良いことだと思っているのだけれども、議会のほうに説明や、議長はさすがに出席されているのですか。全然分からないので、何があったのだというのが正直なところなので、少し説明だけいただいてよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-008"},{"speaker":"松永委員","kind":"質問・要望","question":"私もやはり南海トラフ地震とか大きな地震が迫っている中で、こうした緊急対策としては災害、先ほどのゆきた委員と同じように、災害防災のほうに入れていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"所管事務調査の議論が中心でしたね。脱線してしまってすみませんでした。再開発を進める区の説明を伺うと、いわゆる災害だったり防災。これらの危険を取り除くことであったり。木密対策というか再開発というか、それぞれ両方持ち合わせているところだと思いますので、ぜひ再開発についても、まちづくりという点で防災対策に加えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"防災というところは確かに重要なテーマであり続けますので、所管事務調査に入れていくというのは私も賛成です。その防災の中の一環でもあると思うのですが、やはり埼玉県の八潮市で事故があった、老朽化した下水道管、水道管といったところ。所管事務調査と併せてそういったことができると良いのではないかと提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"１年がたった２月の時点で、トイレトラックが各自治体から６台派遣されて、まだ使用されていたというのもありますし、それから１０月の段階でかなり日にちがたってしまうので、トイレトラック自体は派遣されていないかもしれないのですけれども、その時のどういった取組姿勢をやっていたかいうのは非常に参考になると思いますので、その辺のことについても一つ案として挙げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-012"},{"speaker":"中塚委員","kind":"提案","question":"２人の意見はとても良い意見、提案だと思うのですけれども、少し場所的に私の意見は同じ地域では無理かと思うのですけれども、やはり羽田新ルートの問題について、区民の関心が引き続き高いと。騒音の被害も続いているというところで、伊丹空港がある豊中市に羽田新ルート等の問題に関わって、地元の騒音対策や、あと防災計画にどう落とされているのか。さらには用地買収ということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7077#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":32615,"voices":81}},{"id":"r07-20250609-9","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"文教委員会","time":"午後 １時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井副委員長","kind":"意見","question":"副委員長の筒井ようすけです。１年間どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、事務事業概要、１５ページの学校施設のところで、いろいろ改修などもありますけれども、プールの問題です。子どもたちなどへの影響があれば伺いたいと思います。２８ページの学校給食のところで、この間、有機野菜等の導入をやっていくということで進められていると思うのですけれども、この進捗状況、現場との調整など、現在の状況を伺いたいと思います。","respondent":"荒木学校施設担当課長、石井学務課長","answer":"これにつきましては、今年度中に、昨年度の各学校のプールの実施状況なども踏まえまして、今後、学校改築に当たって、それから既存校改修に当たって、どのようなハード的な対策ができるか。ただ、学校現場につきましては、使用しているシステムが異なることになりますから、令和８年度以降、こういったシステムの選定のプロセスを含めて、現場には丁寧に説明していきたいと考えているところです。","voiceIndex":41,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今、学校の教員の不足の問題が深刻になっていると思うのですけれども、４月からスタートした状況では、教員の不足の状況、担任がいないとかそういうことはないのかどうか、そこを伺いたいのと、不登校数がやはり品川区でも増えているということで、令和５年度は７９９人だったと思うのですけれども、令和６年度の人数が分かれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"教員不足のところは、取りあえず、４月、空きがなかったということで、よかったと思うのですけれども、現在、２か月たって空いているところはないのかどうか心配になってきますので、この間、昨年、産休代替とか、そういったところで結構空きがありましたので、子どもたちの学習環境にも大きく影響してくることだと思いますので、ぜひそこの確保をしていっていただきたいと思うのですが、状況を伺います。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"年度が始まってから、病気休暇ですとか休職もちらほらと始まっている現実はありますので、東京都とも連携して、人材の確保、補填に努めていきたいと考えています。引き続き、学校が魅力あるものとして、子どもたちが通いたくなるような安心・安全が守られた学校づくりを目指してまいりたいと考えております。","voiceIndex":49,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"教員のほうも、今既にお休みされていることが始まっているということですので、そこをしっかり手当てしていただきたいのと、やはり教員の働き方をしっかり変えていくと、続けられるようにしていくということも必要だと思いますので、負担を軽減しながら、多忙化を解消していくことも一緒に進めていただきたいと思いますし、そのためにも、今、小学校が３５人学級になりましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"先生方の働き方改革とか、あと、部活動の外部委託とかで、学校の中で教員以外の方が働くという、いろいろな職の方がたくさん出てきて、そうすると、校長先生や副校長先生のマネジメント努力というのでしょうか、もちろん学校の先生方に対する、引っ張っていく、そういう指導力が必要ということは分かるのですが、それ以外のいろいろなスクール・サポート・スタッフだとか。","respondent":"酒川指導課長","answer":"課題等も踏まえまして、そういったマネジメント、校長、副校長を対象にした研修等で情報発信しますし、個別に見られた課題についての情報を発信して、各学校において、よりよく機能していくように働きかけを行っていきたいと考えております。","voiceIndex":53,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"もちろんいろいろな職に来られている方は意識が高くて、学校教育の中で貢献していただけるという基本的なラインは本当にしっかりされていると思うのですが、ただ、学校の教育という中での仕事というと、一般的な民間企業などとは違うので、その辺の認識をどう考えていただくかが、価値基準が学校の中でのいろいろな話になって、それは外だとこうですという認識を持たれるとか。","respondent":"酒川指導課長","answer":"一例ですが、非常にＩＣＴに長けているスクール・サポート・スタッフなどは、そういった力を存分に発揮しているというようなところもありますし、今まで教育関係の仕事に携わったことのあるスクール・サポート・スタッフなどは。","voiceIndex":55,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"いろいろな職にいらっしゃっている方は、物すごく意識が高くて、学校のために、あるいは児童・生徒のためにというふうにしてお仕事をされている方が全員だと思っていますので、そういう方をぜひフォローして、学校全体の教育活動がよくなるようにお願いします。これは要望です。","respondent":"佐藤子ども未来部長、三輪子ども育成課長、柴田子ども施策連携担当課長、吉野子ども家庭支援センター長、柏木子育て応援課長、芝野保育入園調整課長、染谷保育施設運営課長、佐藤保育事業担当課長","answer":"子ども未来部の令和７年度事務事業概要について、ご説明申し上げます。ＳｉｄｅＢｏｏｋｓの資料２－２、子ども未来部の事務事業概要をご覧ください。児童の安全・安心の確保を目的に、居場所確保事業を実施するとともに、児童の健全な成長を支援するため、朝食の支援を行います。１つ目は、子ども・若者応援事業として、フリースペースを設置し、不登校やひきこもりなど、社会的自立に困難を有する子ども・若者と。","voiceIndex":57,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"すまいるの環境整備について、今、区のお考え、どうよくしていこうとしているのか、そこを伺いたいと思います。１０３ページの区内保育園等のあり方についてなのですけれども、今回、いろいろ老朽化等も含めて、総合的に判断しながら、定員の見直し、統合を含めた再整備を図っていくということで、これは、つまり、区立保育園を減らしていくということなのか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"すまいるスクールのところは、個々に調整をしていくということなのですけれども、具体的に、やはりもともと決まった部屋がないというところで、あと、子どもが増えている中で学級が増えてきて部屋が足りなくなってきているということもあると思うのですけれども、そこのところで、なかなか学校は大変だと思うのですが、何か具体的な環境をよくしていく手だては、今、お考えがあれば伺いたいと思います。","respondent":"三輪子ども育成課長","answer":"一方で、学校の施設の中でも、個人情報の問題ですとか、制約は多々あると思いますので、そういった中でも活用できるような部屋は、学校の管理職も含めて、教育委員会とも連携しながら模索していく必要があるとは考えているところです。","voiceIndex":72,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"生徒がたくさんいると、いろいろ妨害とまではいかないかもしれませんけれども、グレーゾーンの子たちとか、そうした子どもたちがやはり安心して遊べないような状況にもなりますので、ぜひ子どもたちに適した環境を整備していっていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後さらに人材育成を強めていっていただきたいと思いますけれども、今の相談件数、支援担当の方が２５人いらっしゃって、今の受理件数でいくと、虐待相談とかは約６００件ですか、ほかもいろいろありますけれども、全部含めると約９００件ということで見ると、１人当たり、ケースが何件なのかも伺いたいと思います。それで今の人材配置が十分なのかどうかというところを伺いたいと思います。","respondent":"長谷川児童相談課長","answer":"紙の１０ページ、データ版、１３ページの子どもの権利擁護に関しまして、子ども会議の実施状況についてのご質問ですけれども、委員ご意見のとおり、こちらは一時保護所内での子ども会議になりまして、毎週月曜日、曜日を決めて保護している子どもたちを集めまして。","voiceIndex":80,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、人材のところでは、いろいろ人によって、新人には配慮をしてやっていらっしゃるということなので、いろいろ大変な業務でもあると思いますので、そうしたメンタル面の支援等も含めて、ぜひ働き続けられるように、やりがいを感じられるようにやっていっていただきたいと、子どもたちがしっかりと成長できるようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"一時保護のところで、定員超過の状況が続くと書いてあって、常態化しているということなのですけれども、これに対して、ご努力されて、職員の体制や居室の調整とあるのですけれども、これはずっとこのままの状態で、この超過の状態ということに対する、常態化することで、どういう課題というか問題が起きるのかということと、あと、この常態化は。","respondent":"長谷川児童相談課長","answer":"ゆくゆくは、職員の育成をどんどん進めていくと同時に、児童福祉司が担うケースワークともうまく連携していきながら、保護の期間を適正な保護期間にしていくように力をつけていけるようになればいいとも思っております。","voiceIndex":86,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"大変なご努力をされて対応されているということが分かったので、区の力だけではなかなかという部分もあると思うので、最後のほうにおっしゃっていましたけれども、２３区全体、あるいは東京都との協力というか、そちらも踏まえて進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-015"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"お答えできる範囲でよろしいのですけれども、以前、前の期の文教委員会で、学校の中で具合が悪くなったというか、原因不明で嘔吐とか、そういう児童・生徒が出たということで、調査中ですみたいなお話をしていただいたので、その後それがどうなったのでしょうかという、何か大きなノロだとか、そういうものも何かあったのでしょうかということが１つ。","respondent":"石井学務課長","answer":"その後、発生した後、消毒作業を実施しまして、２日間の臨時休業を経て、今現在は通常に機能しているところでございまして、体調不良者もその後増えることはなく、生徒の皆さんは元気に学校に通っている状況です。","voiceIndex":92,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"意見","question":"すみません、新聞の報道であったので、品川を含め、ほかの二、三区で、あと私立の学校でも殺害予告が来たということがあったのでお尋ねしたので、また詳細が分かったら、報告していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"意見","question":"その報道によると、「警察の発表によると」という表現でした。警察が把握している、警察に新聞社が取材をしたか、警察の発表を聞いたということです。新聞の報道では、東京都教育委員会がということではないです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-018"},{"speaker":"のだて委員","kind":"意見","question":"いじめ対策で、この間、いろいろ重大事態の報告がありますし、最近、報告書を公開してほしいという希望の方もいて、公開されるものが出ましたので、そうしたところも見ながら、区としてどういったことが必要なのかというところをできたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7075#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":35404,"voices":107}},{"id":"r07-20250609-5","meetingId":"r07-cm06","date":"2025年6月9日","dateIso":"2025-06-09","committee":"総務委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それのスケジュールなどが少し分かればお聞きしたいということと、あと、人権・ジェンダーのところで、苦情相談申出対応があったと思うのですけれど、それがどれぐらいあったのかというのが、数字が分かれば教えていただきたい。ではそこも少し踏まえて、どこでどういう介入のされ方をしてくるのかというのを伺いたいと思います。","respondent":"佐藤経理課長、木村人権・ジェンダー平等推進課長、宮尾人事課長、小林新庁舎建設担当課長","answer":"最終的には、労働報酬下限額につきましては、他の自治体などを見ましても。私からは、苦情相談の申出の件数についてなのですけれども、昨年度、７月１日から開始したところではありますが。ただ、来年の４月１日につきましては、任用されている方につきましては、もう一回。それと、２点目の介入ですが、基本設計、実施設計と進めてきているところですけれど、これは全ての期間におきまして関与されている状況です。","voiceIndex":81,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"公契約条例、今年から施行されて、労働報酬下限額がやはり一番気になるところですので、ここがどう決まっていくのかなというのは大変注目もされておりますので、ほかの自治体等を見ても翌３月ぐらいというのが適切なのかなというところでいうと、翌３月ぐらいに告示されるということですので、ここは十分に、全ての職種の方々に適切な額がしっかりと渡るようにやっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"財政的なシミュレーションといいますか、償還などもあるのですけれども、現在どうなっているのかなどというのは、常に意識しなければいけないなと思っているのですが、なかなか、決算や予算などのところには若干出てくるのですが、もう少し、これは要望になりますけれども、批判というか、少し回数を減らしながら、増やしながら議論をするというのが必要なのでは。","respondent":"崎村企画課長、加島財政課長、西澤ＤＸ戦略担当課長","answer":"ベーシックサービスにつきましても、この施政方針の中で述べさせていただいていますが、人間が自分らしく暮らしていく上で不可欠な。私どもといたしましては、その３０年先の財政シミュレーションに取り組んでいくに当たって、各歳入ですとか歳出の考え方をどのようにまず。私のほうから、ＥＢＰＭの推進について説明します。","voiceIndex":87,"id":"exchange-003"},{"speaker":"西本委員","kind":"提案","question":"客観的に見なければいけないし、統計的な分析手法や、ＡＩ的な、そういう手法もそうだと思うし、ということで、それを今後、かなり事業展開する中では、根拠になるデータというのを求められてくると思うので、ここは実践していただいて、ご報告できるのであればご報告、ぜひお願いしたいと思います。これは私の意見です。そして質問は、区のどの部門にも属さない事象というのはどんなものがあるのですか。","respondent":"崎村企画課長、藤村総務課長","answer":"これを何に位置づけるかについては、国の動向も踏まえつつ、今回、予算特別委員会でもいろいろとご議論いただきましたけれども、議会での意見ですとか区民のご意見等も踏まえながらしながら。どの部門にも属さない事象というところで、例というところですけれども、例えば、現在、総務係で担当しておりますＣＳＲ推進協議会など、そういった新しい概念が出てきたときに、どの部門にも属さないからというところがあったり。","voiceIndex":91,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"もっとこれから複雑になってくるのかなと思っているのです。そうすると、何か起きたときに、これ自分のところかなというのがよく分からなくなってしまうと思うのです。何でもいいから言ってきて、という状況になってくるのか、この辺の仕切りはどういうふうになっているのですか。","respondent":"藤村総務課長","answer":"連携等のご指摘というところですけれど、現在でも横軸の連携というのはしっかり取れているかなというふうには考えているところですが、どういった課が主導権を持つかというところがやはり不明確である事象が出てきた場合の対応といたしましては、不明確であれば総務課なりで。","voiceIndex":94,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"最後。最後に、人事課のほうなのですけれど、目安箱がなくなったらしいですね。職員の人たちのカスハラももちろん、条例できて、カスハラの問題もありますが、一人で悩んでいる方とかに対するフォローとか、そういうものはどうなっているのですか。そういう目安箱もなくなってしまったり、ということになるとなかなか言いづらいとは思うのですけれど、それは大丈夫でしょうかという、最後のお尋ねです。","respondent":"宮尾人事課長","answer":"もう一つ、外部といたしまして、弁護士が直接相談を受けるというような窓口も設けておりますので、そういったところ、目安箱がなくなったからというふうにならないような、様々対策を講じながら、しっかりと職員の声を聞いてまいりたいと考えています。","voiceIndex":96,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"ということは、外部の窓口がいろいろあるので目安箱をなくしたという認識でよろしいのですか。なくなった理由を教えてください。","respondent":"宮尾人事課長","answer":"要は、風通しのよい組織というところを目指して、自分の組織、例えば職員の悩み事に対してその組織全体で解決をする、こういった力というのも大切にしていきたいというような思いもあります。","voiceIndex":98,"id":"exchange-007"},{"speaker":"須貝委員","kind":"確認","question":"企画経営部にお伺いしたいのですが、渋谷区と世田谷区がマイナ保険証の有無に関わらず国民健康保険の加入者全員に健康保険証と同様に使える資格確認書を独自に発行することを決めました、とあります。渋谷区だけでも４万６,０００人、世田谷区がおよそ１６万人、資格確認書を順次発行するというふうにあります。","respondent":"横田デジタル推進課長","answer":"急遽１週間で方向転換したので、今後どうしていこうかというのは今、企画経営部、あとは健康推進部で調整して、近いうちにどうしていくかというのを出していくというふうに考えております。","voiceIndex":100,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"保険料は頂いているので、それで実際診療に行ったら診療してもらえないというのは、これはもう区民に対して大変失礼なことだと思うので、これは早急に企画経営部としては積極的に考えていただきたいと私は思います。２点目は、何かいじめの重大事件がまた、何件か発生したというような話が聞こえているのですが、これは事実ですか。それを教えてください。","respondent":"川村コンプライアンス推進担当課長","answer":"いじめ重大事態の件数についてです。累計で申し上げますと、令和４年度からの累計で２４件、うち令和６年度は５件というふうに把握しております。","voiceIndex":102,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"それで、令和７年度に入ったばかりですから、令和６年度はいろいろ対応策を考えて、事業部もそれぞれ編成したわけですよね。そのいじめ重大事件に対する体制を。それに対して、様々な手法、対応をしているにもかかわらず、やはりどんどん増えているといったような状況なのですか。教えてください。","respondent":"川村コンプライアンス推進担当課長","answer":"増加傾向にあるかというところで申し上げますと、いじめ重大事態は、令和５年度に比べて令和６年度のほうが減っております。","voiceIndex":104,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"様々な事業部で取り組んでいるというふうに報告を受けているので、これに対してはやはり、人をさらに増員して食い止めていただきたいと思います。意見だけ言わせていただきます。少し監査委員事務局にお聞きしたいと思います。その対象になっている人がいるにもかかわらず、また、監査もするというのは何か少しおかしな気がするのですが、区としては、これはこのまま続けるつもりですか。教えてください。","respondent":"黒田監査委員事務局長","answer":"監査委員制度につきましては、先ほど事務事業概要でも申し上げたとおり、地方自治法の規定がございまして、識見を有する監査委員といわゆる議選監査委員から設置されるという構成で、いずれの委員も区長が人事案件提出しまして。","voiceIndex":106,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"これ、子どもが見ても、監査される人がその中にいるにもかかわらず、監査を行う人をその中から選ぶというのは、小さなお子さんの教育上も間違っていると私は思うのですが、そういうことに関して、今まではそういうことがあってよかったのかもしれないですが、そういう間違いがだんだん顕著になって、世の中の風潮もだんだんそういうふうに目が厳しくなっているというのに関わらず、品川区はこのまま。","respondent":"黒田監査委員事務局長","answer":"繰り返しになりますが、監査委員制度につきましては、法令に基づいて運用されている制度ですので、これに基づいて運用していくものというふうに事務局としては考えているものです。","voiceIndex":108,"id":"exchange-012"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認です。ここは特別委員会ができたので、先ほども委員長のほうからご案内ありました。これは特別委員会ですよというところがあるので、もう一度確認したいのが、ＳＤＧｓと、それから庁舎の建て替え、跡地活用も、それも全部特別委員会だから、総務委員会では扱えないということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"やはり今後、新庁舎整備費等で負担が増大していくというところの中での、３０年先を見据えた、この財政のシミュレーション、これは非常に重要な事項の一つだと思っていますので、これは調査していただきたいというところで、これは新庁舎整備基金との絡みもありますけれども、それは新庁舎整備だけのことではなく、公有地だけのことではないということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-014"},{"speaker":"山本委員","kind":"意見","question":"私としては、今おっしゃられたように、どのようなやり方が可能かというところも含めて、この所管事務調査で話していくことができたらいいなという思いですけれども、そのやり方等については、ぜひ、もし調査対象になるようでしたら協議をさせていただければいいのかなと。入りのところもどこまでやるかというのは、そこは検討かなというところで……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"全体どういう動きになっているのかというのが。細かいところに入るともちろん所管に入ってきてしまうと思うのですが、全体の財政として品川区の財政どうなっているのですか、どういう方向になっている、今は大丈夫だけれども、このままいってしまうと、物価高も含めて考えていくと、プラスアルファで考えておかないといけないねとか。負担になってくるのか大丈夫なのかというのを、見通しを立てられたなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"職員の人材育成というところ。ただ、職員の方々が元気になってほしいのです。なので、私たちがそれを議論すべきものかという部分はあるのですけれど、現状として何か、やりやすい環境にするには何かないのかなあと。ただ、少し気になっていることなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"そういうところで意見交換なり、それぞれの大都市問題の悩みを抱える、そういう自治体と、いろいろなところを視察しながらお話を伺うというほうが、よりベターな視察になり、なおかつ勉強になると思いますので、そういう方向で進めていただけるとありがたいなと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-018"},{"speaker":"西本委員","kind":"提案","question":"それはすごく貴重な体験だったなあと思っているので、ぜひそういう観点で提案、総務委員会も小さいところ、大きいところ、自治体の状況によってという違いはもちろんあるのですが、でも、小さかろうが大きかろうが、結構共通した悩みとか問題点とかがいろいろあるので、広げて考えていただくのが一番いいのかなと思っています。ぜひ、所管事務調査に関わるような視察先の検討をお願いしたいと思います。","respondent":"石田（秀）委員長","answer":"別に、都内であろうと、今言った、川崎・横浜は別だと思っているけれどそういうぐらいのところでも、日帰りだって、委員会のときだって１時間ぐらいで行けるわけですから、委員会中に行ったっていいわけで、そういうことも含めて。","voiceIndex":153,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7083#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":38826,"voices":155}},{"id":"r07-20250610-21","meetingId":"r07-cm06","date":"2025年6月10日","dateIso":"2025-06-10","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"ゆきた副委員長","kind":"意見","question":"副委員長を務めします公明党のゆきた政春です。１年間、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"子ども・若者のほうで伺いたいのですけれども、３ページのところで表の見方を教えていただきたいのですが、区立幼稚園の運営の（２）の特別支援教育・巡回相談というところなのですけれども、この表が、令和６年度が９園で２７回、対象者が８１人ということなのですが、そうすると、１園で年間３回ということで、１園平均９人くらいということで見ていいのか、そのことを教えていただきたいと思います。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"１点目の、幼稚園の特別支援教育・巡回相談ですが、こちらの実績に記載のとおりで、回数等はここにお示ししたとおりであるのですけれども、園につきまして、複数その対象となるお子さんがいらっしゃいますので。保育所等訪問のご質問についてお答えします。保育所等訪問は、療育に通われているお子さんの療育の施設の職員の方が、ふだんの様子というのを見に来ていただく事業でございまして、子ども未来部で対応している事業ではないところです。","voiceIndex":32,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、臨床発達心理士というのは、私たちもいろいろな団体と懇談させていただいたときに伺ったのが、パルレとかの心理士の方も学校に相談に行かれているという話も聞いたのですけれども、そういうところの心理士がこういう形で巡回相談をしているというのが、この制度ということで捉えていいのでしょうか。","respondent":"染谷保育施設運営課長","answer":"実際に巡回相談の中身の違いにつきましては、事務事業概要にも記載をさせていただいているところではあるのですが、臨床発達心理士に関しましては、知的障害、発達障害といったところの児童の特性についての様々な支援方法について助言をいただくというもので。","voiceIndex":35,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"重層的支援体制について伺いたいのですけれども、重層的支援体制は既に区としては始まっているということでいいのか、それはいつから重層的支援体制ということで、準備の段階が結構長かったと思うのですけれども、それが本格的に始まったというのは、いつから始まったのかということを伺いたいと思います。","respondent":"東野福祉計画課長","answer":"重層的支援体制整備事業ですが、先ほどもご説明させていただきましたとおり、令和３年度から取組を開始いたしまして、令和７年度、今年度から本格実施となっています。ただ、どこが境目かという部分がかなり曖昧な部分はあります。","voiceIndex":37,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。それから、いろいろとケース会議とかは既にされているということでご報告いただいていますけれども、厚生労働省の重層的支援体制とはというところを見ていたら、重層的支援会議および支援会議についてというところがあったのですけれども、そこのところでは、品川区としては重層的支援会議というのはどういう状況になっているのか、メンバーとかも併せて教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"国で定めております基準でいきますと、重層的支援会議、それから支援会議という２つの会議体がございまして、当事者の方について、この会議にかけてもいいですよという本人同意があるものが重層的支援会議、本人同意がないのですけれども。","voiceIndex":39,"id":"exchange-005"},{"speaker":"つる委員","kind":"意見","question":"その上でですけれども、重層で孤独・孤立のほうなのですが、全体と、例えばもう一つの若者に関することということで、２つの中で、若者の孤独・孤立という考えと、重層で捕捉する孤独・孤立と２つあって、品川区でアンケートをやっていただいて、若い世代のほうが孤独感が強いという報告もいただいて、その辺りは、例えば委員会も含めて報告とか、今後どういう形でその辺りを捉えて。","respondent":"東野福祉計画課長","answer":"この特別委員会で、重層的支援体制、それから若者に関することの中に、孤独・孤立対策についてという項目がありますので、こちらに関することにつきましては、こちらの特別委員会へご報告をさせていただきたいと考えています。","voiceIndex":42,"id":"exchange-006"},{"speaker":"つる委員","kind":"意見","question":"それに限らず、当然、孤独・孤立に至る背景というのはいろいろな要素があると思うのですけれども、そこはどうなっているのかということと、あとは、東京都とかでは販売店とか、そういったところに対するアドバイスとか指導というのは、東京都でやっていただいていると思うのですが、学校、教育委員会では。","respondent":"せお委員長、東野福祉計画課長","answer":"今後取り上げていく内容につきましては、この後のその他で皆様からのご意見をいただきますので、そこで取り上げたいと考えていますが、現状の体制など、お答えできるところをお願いします。直接的な所管というよりは、そのものを扱っている部署がありますので、そちらとの連携という部分が必要だと思っているところです。情報共有をしながら、どんな対策ができるかにつきましては連携していきたいと考えています。","voiceIndex":44,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"ここは重層だと、もっと幅広いという形になると思うのですけれども、そういうアウトリーチで捕捉できるというところ、既存でやっていることと、今回の場合は全世代が対象のところに行くわけですが、ただ、やっていただく担い手は運送事業者とか、タブレットでとかというのがあるのですが、そういうところとの既存の重層としての連携といいますか、共有というのはどのように考えているのかというのが。","respondent":"寺嶋福祉部長","answer":"前提としてのところでご説明させていただきたいのですけれども、まず、重層的支援体制整備事業というのは、考え方としては、仕組みといいますか、こういう仕組みで漏れなくというか、可能な限りご相談を受けていこう、悩みを解消していこうという考えに立ったもので。","voiceIndex":47,"id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"つる委員","kind":"質問","question":"それぞれの今回の特別委員会で扱う施策で、事業等を実施していただいている現場を拝見させていただいて、その現場で従事されている方の声とか、できれば利用者の方の声も伺いながら、この委員会で次のステップについて、議論していきたい。これは庁内外といいますか、区内外を含めて、視察を含めてできたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"私も実際にいろいろと見てみたり、話を聞いたりというのが、理解がすごく深まるのではないかと思うのです。そこのところも、実際にされている受けたところからお話を伺えたら、すごく理解も深まっていいのかなと思いますので、そういうところを委員会としてもご検討いただけたらありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"そういうところが、具体的に私はどのような形でやっているのかというのが、自分で深めているところはないのですけれども、そういうところで既に何年間もされていて、深まっているところがあれば、そういうところを視察してお話を伺うというのも参考になったりするかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"私もぜひ視察はお願いをさせていただきたいと思うのですけれども、私の希望というか、これをやってみたいという思いがあるのが、今日お話を伺っていても、相談事業がかなり複数ありまして、例えば、あなたのいばしょとの連携のチャット相談とか、しなわかチャットとか、ヤングケアラーの方向けのサポートＬＩＮＥだとか、チャイルドＬＩＮＥもありますし、この辺りの何で知って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7085#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":19406,"voices":58}},{"id":"r07-20250610-20","meetingId":"r07-cm06","date":"2025年6月10日","dateIso":"2025-06-10","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員のご紹介","agenda":"幹部職員のご紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"しながわ未来の筒井ようすけです。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"公有地なのですけれども、それぞれの土地の公有地のところを、区としての現在の活用検討する上でのスケジュール感といいますか、それをそれぞれ教えていただきたいというのが１つ。行政評価なのですが、９月に当特別委員会へ報告とあるのですけれども、これはなぜこのタイミングで報告なのかというのと、何を目的として報告するのかというのを教えてください。","respondent":"吉岡政策推進担当課長","answer":"公有地についてです。１つ、旧荏原第四中学校につきまして、検討状況ですけれども、令和５年度から本格活用に向けて検討を進めてきたところでございまして、ＰＦＩ事業で進めているです。","voiceIndex":32,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"当特別委員会に報告していただくということだと思うので、それについて教えてください。まとめて言ってしまいますが、ふるさと納税なのですが、共産党としては制度の見直しが必要だと思っているのですけれども、区としてのスタンスを改めて確認させていただきたいのですが、具体的にはどのような形で、どのような意見を国に区として述べているのかお聞かせください。","respondent":"吉岡政策推進担当課長、西澤ＤＸ戦略担当課長、横田デジタル推進課長、宮澤税務課長","answer":"そういった中で、改めてシートの記載内容、こういった項目にはこういった考え方で記載をさせていただいている。初めに、適用期間といいますのは、ＤＸ推進基本計画というものを昨年から今年度にかけて定めておりまして、これを５年間実施していくというものです。私は区の完全なプロパーになりまして、職員時代に４年間、システム開発とかをやっていまして、今、係長時代からその後課長になったのですが。","voiceIndex":34,"id":"exchange-003"},{"speaker":"筒井委員","kind":"意見","question":"続いて２点目として、しながわＤＸの取組のところで、図表のところ、地域ＤＸのところで、誰ひとり取り残さないデジタル活用の推進のところで、翻訳タブレット利用回数が、令和６年度の実績が２,２３７回で、令和７年度の目標が１,５００回と回数が少なくなっているのですけれども、普通、目標を立てるとしたら、逆に多めの数値を持ってくると思ったのですが、その辺り。","respondent":"横田デジタル推進課長","answer":"今年度の目標の数値は見直していきたいと考えております。","voiceIndex":42,"id":"exchange-004"},{"speaker":"筒井委員","kind":"確認","question":"なかなか読みにくいと。過去の実績から見ると、１,０００件半ばぐらい、大体予想できるという理解で、そうしたことも今回せっかく書いているのに記載したのかという理解でよろしいのか、確認させてください。","respondent":"横田デジタル推進課長","answer":"事業者からの実績というものが年度末に一括して来まして、そうしましたら、思いのほか５００件ぐらい伸びていたというところもありまして、このＤＸ推進基本方針の目標を立てるときには、ここまでの数字の予測はしていなかったので。","voiceIndex":44,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"なかなか読みにくいという事情は理解しました。ぜひ見直しを行っていただきたいと思います。よろしくお願いします。最後に、ふるさと納税なのですけれども、流出額が約５０.９億円ということで、以前も、逆に品川区に流入してくる額をご説明いただいたかと思うのですけれども、改めて、品川区としては流入額が幾らぐらいを目標としているのでしょうか。","respondent":"宮澤税務課長","answer":"今年度、品川区に寄附いただく目標額としては、１.２億円を目標としております。","voiceIndex":46,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私はこれがＳＤＧｓ推進事業の一環だという認識がなかったので、子どもを中心とした、これから子どもの意見を政策立案に入れていくのだという認識でいたものですから、これがどういう位置づけで表れているのかを教えていただけますでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"別紙で記載をさせていただきましたように、今回、ＳＤＧｓ未来都市計画において３側面をつなぐ統合的取組のうち、多様なステークホルダーとの連携というところで、子ども・若者も登場人物として。","voiceIndex":49,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"別紙で今のご説明で、表題がパートナーシッププロジェクトで、子ども・産・学・官による共創というタイトルになっているのですけれども、今までこういう図というのは私も拝見してきましたが、子どもと産学官という、結構幅が広いというか、今おっしゃられた説明のとおりだと思うのですけれども、子どもというのが入るのは令和７年度からということで、それとも私の勘違いで。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、モデル事業で立ち上げたそのほかのしながわＳＤＧｓ共創推進プラットフォームですとか、あとはしながわシティラボでは、地域の民間企業や団体との連携を強化してきたところでもありますので、少し同じ枠組みとは違った。","voiceIndex":51,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"決して私は反対とか、それに異を唱えているわけではないのですけれども、品川区としては、計画のモデル、品川区が内閣府の認定を受けるに当たって提出した中にはそういったものが入っていて、この全体スキームという図の中に、以前は令和６年こども会議というのが入っていたと思うのですけれども、それが中高生リバースメンター事業という形で。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"そこの目的を踏まえたときに、子どもたちの意見をただ聞くだけではなくて、そこから一歩踏み込んで、子どもたちにもう少し継続的に区の事業を知っていただいたりとか、子どもたちが考える社会課題について少し深掘りをしたりするといったところをより強化していくために。","voiceIndex":53,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"最後に１点だけ。ということは、中高生リバースメンター事業というのは、ＳＤＧｓの推進の御課での取組ということになるのでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今、委員ご指摘のとおり、中高生リバースメンターは、ＳＤＧｓの達成に向けた取組の大きな要となる事業だと捉えてあります。","voiceIndex":55,"id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"趣旨としては、それ以外にご説明いただいたＳＤＧｓ共創推進プラットフォームなり、しながわシティラボ等の個別の事業は、それはそれでぜひご説明いただきたいのですけれども、区として全体として、各課で様々ＳＤＧｓの事業を進めていることも併せて知りたいので、今回この特別委員会でテーマにして、特別委員会の名前にもなっているということでもあるので、そういったご説明いただけると思って。","respondent":"井添ＳＤＧｓ推進担当課長、吉岡政策推進担当課長","answer":"この後、ＳＤＧｓ未来都市計画令和８年度、令和６年度から３か年の計画になりまして、毎年内閣府に進捗の報告をしてまいるのですけれども、スケジュールとしては、本年１０月頃に内閣府から。今年度におきましては、これはＰＦＩ事業で進めていくというところになりますので、事業者を公募するための実施方針、要求水準書を、１年間かけてつくっていくことになります。","voiceIndex":58,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"これも昨年度の行財政改革特別委員会のときにご要望させていただいたのですが、１年前倒しでＤＸ計画が策定されていて、この重点項目について、目標指標を設定されている取組は、すごくいいと思っているのですけれども、重点項目以外についても、そのとき様々ご発表いただいていたと思いまして、それについても評価指標の策定を進めていらっしゃるかどうかを確認させていただきたい。もうまとめます。","respondent":"吉岡政策推進担当課長、西澤ＤＸ戦略担当課長、宮澤税務課長","answer":"一方で、指標の設定の見やすさだとか、あるいは、議員の皆様、区民の皆様に見ていただく際のまとめ方というのは課題と考えておりまして。ただいまご質問いただいた評価シートについてですが、重点施策に関してはこちらで示しているとおりでして、その他以外に関しては、なかなか全ての項目を。令和６年度は１社で行っていたところなのですが、令和７年度からはさらに２社追加して、３社という状況になっております。","voiceIndex":61,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"要望させていただいているとおり、見やすさのところも非常に課題だと。分かりやすさ、取りまとめ方という課題だと思いますので、ぜひ進めていただきたいと考えています。それから、ほかの委員からのご質問にもありましたけれども、目標設定のところです。これはすぐに大幅に拡大していくということはないと思うのですけれども、ぜひ地道に加盟店等、声かけしながら、裾野を広げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-013"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど公有地等について、検討スケジュール感等をお伺いさせていただいたのですが、それぞれの公有地の活用検討のスケジュールの時期を見定めて、それの時期を逸しないように、ぜひ区民の意見を入れた活用になれるような時期で、当委員会で扱っていっていただくようなスケジュールをお願いしたいと考えています。あわせて、必要であれば、現地の視察というのもしっかり入れていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"意見","question":"安藤委員の意見と珍しく同意でございまして、ＳＤＧｓに資する都市でありますとか、あとはいろいろな跡地の活用についての視察、現地を見るということは非常に大事だと思いますので、常任委員会以上に、特別委員会の視察を精力的に組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7087#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":20608,"voices":72}},{"id":"r07-20250611-22","meetingId":"r07-cm06","date":"2025年6月11日","dateIso":"2025-06-11","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ２時２７分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"住民参加も情報公開もなく、区とＪＲと日建設計の３者で決められて進められてきた計画は見直すべきだと求めてきました。この周辺町会３町会を教えていただきたいのです。それで、この件に関わってなのでしょうか、今年の５月２４日に大井町まち歩き調査というのもやられていると思うのですけれども、これはこの社会実験に関わった調査なのかというのを伺いたいと思います。","respondent":"泉広町事業調整担当課長、中道都市開発課長、高梨都市計画課長","answer":"人数につきましても、今検討中のところがありますけれども、３名程度を想定しています。地域の方々から広町の開発がある中で、私たちの既存市街地にどうやったら来ていただけるかなど、そういったお話があり、様々お話をしていく中で。昨年度、今年の３月２８日になりますけれども、品川区と慶應義塾大学ＳＦＣ研究所、それとＮＰＯまちづくり大井の３者で。","voiceIndex":37,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"提案","question":"分かりました。こういう質問をしましたというのは分かるのですけれども、その質問への回答が、分からない。庁舎の跡地活用ですので、そこはある程度分かる形に今回はしていただきたいと、まず要望しておきたいと思います。それと、社会実験ですけれども、地域からお声があって、地域住民の方の願いに応えられるものはないかということで、区から提案されたということでいいのでしょうか。","respondent":"中道都市開発課長","answer":"まち歩き調査ですけれども、慶應義塾大学の方が大井町を歩いて、どのような形で楽しく歩けるまちづくりの検討を進めているか。それは学生の独自の調査というところだと思います。直接区と連携してそういった調査を行っているということではございません。","voiceIndex":41,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"社会実験とまち歩き調査は直接的には関わっていないということですね。次に、公共交通のほうで、コミュニティバスは今、試行運行ということで、本格実施するかどうかが、この試行運行で検討されるのが令和７年ということです。本格実施するのか、廃止も含めて検討するということでしたけれども、その要件が収益率５０％とか、廃止になる要件というのを改めて伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"要件と申しますか、一応、当初に計画を立てたときに令和７年度まで４年間運行して、令和６年度の実績をもって令和７年度に判断するということとしておりまして、その際の判断指標としては、収支率５０％という形になっております。","voiceIndex":43,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで、今現在、令和６年度は約２７万人の利用がありましたということですけれども、この収支率の計算の中にはシルバーパスは含まれていないのか、そこを確認したいです。その辺をどう見るのかというのはこれからの検討なのだと思うのですけれども、シルバーパスは入っていないということでいいのでしょうか、確認をお願いします。","respondent":"櫻木地域交通政策課長","answer":"シルバーパスにつきましては、特に計画時に、シルバーパスを加味するかどうかということは明示されておりませんので、数値の扱いについては、それも含めて考えていくということになろうかと思います。","voiceIndex":45,"id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"先ほどの大井町の社会実験について石田ちひろ委員から出ていた質問で、少し私も分からなかったのでお聞きします。調査を行いましたという話が出ていて、多分これはやられていると思うのですけれども、その調査内容をあまり品川区側で明確に把握はできていないという話でした。これは品川区もある程度把握しておかないといけないのではないかと思うのですけれども、そこはいかがでしょうか。","respondent":"高梨都市計画課長","answer":"慶應義塾大学とＮＰＯまちづくり大井と区の３者で取組をさせていただいている事業の一つです。その一環として、先ほどご説明させていただいたように３者で協定を組んで、大井町のまちづくりについて、これからいろいろと考えていきましょうということで進めております。","voiceIndex":49,"id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"これも石田ちひろ委員の話と重複する部分があるかもしれないですが、今の採択事業と今回の社会実験というのは、包摂されているのか、一応別の枠組みと考えたらいいのか、ここはどうなのでしょうか。","respondent":"高梨都市計画課長","answer":"慶應義塾大学が行っているまち歩き調査と、今回の社会実験の関係ということでよろしいですか。","voiceIndex":51,"id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"すみません、質問の仕方が悪かったです。今回の慶應義塾大学との協定というのは、必ずしもまち歩きの調査だけではなくて、採択事業自体はもう少し広いもので東京都から採択を受けていると思うのですけれども、東京都から採択を受けている事業の中にこの社会実験が含まれているのか、それとは別に、この社会実験というのは地域の要望もあって出てきたという関係なのか、ここの関係性をお願いいたします。","respondent":"高梨都市計画課長","answer":"今、広町でまちづくりが盛んに行われていますが、どうしてもそちらであったりとか、今年度実施予定の社会実験であったりというところもありますけれども、もう少し広い範囲で慶應義塾大学も今まで研究もされていますし、これからもされていくということです。","voiceIndex":53,"id":"exchange-007"},{"speaker":"松本委員","kind":"提案","question":"今回の社会実験、私はすばらしい取組みだと思っています。地域から、このままだとこのエリアになかなか人が来なくなるという話を聞いて、品川区側がいろいろ調べて、今回の社会実験というところをアイデアとして考えたのか、あるいは、例えばＮＰＯまちづくり大井から提案があって、品川区としても検討会をやっていきましょうという流れになったのか、この流れはどちらなのでしょうか。","respondent":"中道都市開発課長","answer":"どんたく通りの車道を一部歩道化してという具体的な社会実験の提案は、区のほうから行ったものです。そのきっかけというのは、先ほど申し上げたとおり、地域からどのように今後、この市街地によりにぎわいを創出するかといったお話の中で、区が具体的に提案をしたという流れです。","voiceIndex":55,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"だから、その前提として、今年の委員会の質疑は、令和７年のどの時期かわかりませんが、結論を出した上で、もう一度改めてコミュニティバスについて議論するのか、もうほぼ結論が見えていると思っているので、それを前提にして、今年１年の議論をすべきなのか、そこの前提がはっきりしないので、もう少し細かく言えば他にもいっぱいあるのですけれども、まずそこの確認をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、１点すみません、新たな質問で、どんたく通りの関係で私も確認をしたいのですが、近隣の方々との連携も踏まえてということですが、そもそものスタートは、私の理解だと舛添知事時代に、環状２号線をつくる際に新虎通り、虎ノ門のところのバイパスをつくる際に、上部が空くので、要はバイパスに多くの車が流れるので、上は道路の交通量が激減すると。そこが一つ、事例になると捉えていいのでしょうか。","respondent":"中道都市開発課長","answer":"どんたく通りにつきましては、ああいったカフェを常設するのはなかなか難しいかなと。そこまでの歩道の広さを確保できるかどうかというところはあるのですけれども、ああいった形で歩道を活用するというのは、一つ参考として捉えていきたいと考えています。","voiceIndex":62,"id":"exchange-010"}]},{"id":"topic-02","title":"路線バスのバス停新設","agenda":"路線バスのバス停新設","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"一つよかったなということなのですが、今のご説明の中でもありましたように、片車線のみの設置で、反対車線側にいろいろ課題があるというところで、そこについてはこれまでもいろいろ伺ってきているところではあるのですけれども、みずほ銀行側の反対車線は、素人目には結構歩道も広いし、スペース的にはそんなに課題として取り上げられるべきものがあるのだろうかというところがあるので。","respondent":"櫻木地域交通政策課長","answer":"みずほ銀行の辺りにつきましては、詳しく申し上げるといろいろとあるのですが、お住まいの方の関係ということと、あとは、みずほ銀行の前につきましては、都との関係で少し調整が難航しているです。","voiceIndex":68,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"特にみずほ銀行のところ、大井町方面に行く側は、都との関係というところが一番のネックになっているということなのでしょうか。もし都との関係ということになると、補助２９号線の絡みなのかどうかというところが出てくるのですけれども、もしそうだとすると、なぜなのかとなかなか腑に落ちないところがあるのですが、今説明できる範囲でご説明できれば、もう少しお願いしたいと思うのですけれども。","respondent":"櫻木地域交通政策課長","answer":"あの辺りについては、バス停の候補となる場所が何か所かあるのですが、そのうちみずほ銀行のところにつきましては、ご指摘のとおり、都の都市計画道路の関係と伺っております。","voiceIndex":70,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、都との協議の中で、あそこにバス停を設置する余地があるのか。都の道路として拡張されてしまうので、みずほ銀行前辺りというのは、候補としては考えられないのかということ、都との話合いがこの後持たれて何とかなる余地があるのかないのかというところで、最後にお伺いしたいです。","respondent":"櫻木地域交通政策課長","answer":"詳細につきましては、基本的には東急バスと都が直接交渉して様々なやり取りをしているところで、又聞きという形になりますが、いろいろと課題があるということで、解消できるのかどうかというのは、今検討中と聞いています。","voiceIndex":72,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"バス停の増設というのは私も要望を受けていたので、本当によかったと思っています。もう一つ要望を受けていたのは、バスの本数です。本数についての要望等をこれからもしていっていただきたいと、多分していると思うのですけれども、その辺の状況、あと、していっていただきたいという思いもありますので、その辺について答弁いただけますか。","respondent":"櫻木地域交通政策課長","answer":"バス停ができることによって、乗降者が増えて、需要が高まると。それが便数増という形に結実していくのかなと考えていますので、そのような面もご指摘の面も含めて、これからも東急のほうには話をしていきたいと考えています。","voiceIndex":75,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちも住民の皆さんから、このバス停の増設は要望がありましたので、本当によかったと思っています。東京都にもう少し強力に、こちらとして、いつできるか分からないし、反対の声も多数あるという中で、区としては区民の利便性という形で、そちらを最優先していただきたい、そこに積極的にもっと言っていただきたいという思いがあるのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"これまでもしてきましたし、これからもやっていきたいと考えています。","voiceIndex":78,"id":"exchange-015"},{"speaker":"えのした委員","kind":"質問・要望","question":"本数も、藤原委員がおっしゃっていましたように、要望を受けています。ただこれは民間なのでね。利用者数がどのぐらいかというのは、区が東急のほうから確認をしているのか。逆に、今後またバス停が増えれば利用者が増えて、また本数が増えるという、そういったことは企業として東急バスが把握しているのか、その辺も品川区としてはどのように理解をしているのかお聞かせください。","respondent":"櫻木地域交通政策課長","answer":"その中で便数を増やすというのは今の状況だと厳しいけれども、先ほど申し上げたように、バス停が増えていくことによって利用者が増えてという形で東急のほうに話したら、それはあり得るということを答えとしてはもらっていますので、できる限りご利用いただいて。","voiceIndex":81,"id":"exchange-016"},{"speaker":"えのした委員","kind":"質問・要望","question":"ぜひ今後もバス停の増設を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"オレンジの井の５０系統が大井町方面なのです。この写真ですと、平塚たけのこ公園で、住所が東中延一丁目になっているのですけれども、これは平塚ではないのですかという単純な疑問です。","respondent":"櫻木地域交通政策課長","answer":"すみません、確認して、後ほど回答します。","voiceIndex":85,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"それと同じ指摘で、戸越の四丁目９番とあるのは、戸越五丁目ではないかと思いますので、また後でご答弁いただきたい。","respondent":"櫻木地域交通政策課長","answer":"大変申し訳ございません。南と北が逆になっておりまして、戸越五丁目と平塚一丁目が正式な住所となります。大変申し訳ございませんでした。","voiceIndex":87,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"これは意見だけにします。コミュニティバスの利用者利便性向上に当たっては、地域から、さくら会前を含む、いすゞ病院前も含むバス停の数を増やしてほしいというのをずっと言われていて、私は、バス停の数が増えれば利用者が増える、そのことに伴って収益率も上がるというのは、先ほどの課長のご答弁のとおりだと思いますので、そこは私から意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-020"}]},{"id":"topic-03","title":"ＡＩオンデマンド交通実証運行の実施","agenda":"ＡＩオンデマンド交通実証運行の実施","exchanges":[{"speaker":"えのした委員","kind":"意見","question":"実証運行が７月９日になっているのですけれども、荏原区民センター、荏原五丁目、これはミーティングポイントが近いのに、説明会開催のスケジュールが運行されてからになっているのが少し残念というか、この運行が始まる前に、周知も含めて、もちろん利用者の方には事前に説明がされているのが丁寧かなと感じたところが１点と、愛称「しなるん」はどのように決まったのかというのと、あともう一つだけ。","respondent":"櫻木地域交通政策課長","answer":"利用者向けの説明会につきましては、アプリの開発の関係で直近になってしまったということと、やはり自動車が、物が動いている状況のほうが、具体感を持って聞いていただけるのかなというところもありまして、このタイミングで設定させていただいているところです。","voiceIndex":96,"id":"exchange-021"},{"speaker":"えのした委員","kind":"質問","question":"名前は一つ重要だと思うのです。るんるんということで楽しげな名前が、地域の方に広まっていって、こういった運行実証が始まっていく。それが設置されると、まちでもあれは何だろうということで、こういうのが始まるのだよと私も話がしやすいかなと思っているのですけれども、そちらもスケジュール感を教えてください。","respondent":"櫻木地域交通政策課長","answer":"こちらについては、６月の中旬から下旬にかけて工事することになっております。ただ、自立式看板を置ける場所はそれほどないということで、シートタイプが多くなるのかなと思っています。","voiceIndex":98,"id":"exchange-022"},{"speaker":"えのした委員","kind":"意見","question":"シートタイプは多分、路上喫煙禁止みたいな、ああいったものになるのかなとイメージしていますけれども、初めてのものなので、目立つとは思うのですが、自立の看板のほうもぜひ増やすように努めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"乗降場所の選定に当たって、自立看板が置ける、置けないも含めて、いろいろとご検討された結果だと思うのですが、今後、統廃合といいますか、利用実績に応じて減らすとか、あるいは、新たにここにぜひ設置してほしいということで設置場所を増やすという、その辺の対応は可能なのか確認をしたいと思います。","respondent":"櫻木地域交通政策課長","answer":"それで、今後増やしていくというか、実際に運行が始まりまして、地域の方々から、ここも使ってほしいというお声をいただけるのは大歓迎ですので、そういう形で機運が盛り上がってきて、少しずつ増やしていけたらいいかなと考えています。","voiceIndex":102,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"乗降場所を見ますと、病院、学校あるいは幼稚園など、極めて公共性の高いところ。具体的には旗の台の六丁目とか、小山七丁目とか、この辺は結構高台なのですが、一方で乗降場所が少ない。高台の方にもそういう需要はあると思いますので、そういう視点からも、ぜひ今後も新たな乗降場所の増設に向けてはご検討いただきたいですし、総論として、ぜひ高台にも設置をしていただきたいという要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-025"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"今ご説明があったオンデマンド交通の実証運行について、７月からやられるということで、これはＡＩでやられるから、勝手な想像なのですけれども、いろいろなデータが取れるのだろうと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7089#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":26107,"voices":108}},{"id":"r07-20250612-10","meetingId":"r07-cm06","date":"2025年6月12日","dateIso":"2025-06-12","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7091#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":2071,"voices":15}},{"id":"r07-20250625-10","meetingId":"r07-cm06","date":"2025年6月25日","dateIso":"2025-06-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点、羽田新ルートの説明会について。本当に議長に努力いただきまして、羽田問題議員連盟しながわからも要望させていただきまして、議長に動いていただいて、こうした品川区議会に対しての説明会が行われるということになったこと、本当にありがとうあります。ぜひそういった運営をしていただきたいというのが要望なのですが、いかがでしょうか。","respondent":"渡辺議長","answer":"その辺、十分私のほうでも関係各所と検討しましたが、結論として、傍聴は認めないということにします。理由については様々ありますが、主な点で言えばやはり議員としての範疇で責務を果たす。","voiceIndex":40,"id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"事前に国交省と随分と調整はしている上での先ほどの提案だとは思うのですけれども、やはりそこはもう一度議会としては傍聴を認める方向でお願いしたいということで国に言っていただきたいです。議長には、そういう立場で動いてもらいたいという意思をまず議運で示していくというのが大事かと思うのですけれども、ほかの会派の皆さんにも、傍聴に関してのご意見などもあれば伺いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"公明党としては、先ほど議長からご説明があったとおり今回は議員に対する説明会ですから、そこに対して当然議員と国交省の間で質疑を行うということで、傍聴があるというのは、例えば建設委員会とかほかの場があって、それを区民に見ていただくという場もありますから、先ほど安藤委員がおっしゃったような趣旨であればそういったところで見ていただくということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、議長がおっしゃったように、我々議会でしっかり聞いて、我々が区民に伝えるべき話であって、そこに傍聴があるとそれこそテレビ中継をするとか何とかというのであれば、相手側だって通り一遍のことしか言わなくなると分かっていることをあえてやって、我々が質問しても通り一遍の答弁しかないというようなことをするためにやるのが今回の話ではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-004"},{"speaker":"松永委員","kind":"質問・要望","question":"説明会なので、そうしたところで私たちが聞いて区民に伝えることもできるですので、今回はそうした形で議長がおっしゃったようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それ以外のことでもいいですか。これは、分かりません。せっかく今議長が会長になられたので、私の思いは売上げも２,０３８億円、１回当たり６億円。配分金がないときもあったし、１,０００万円とか２,０００万円くらいのときもあったし、今は６億円まで来ているわけだから、それはやはり本場がある品川区の３億円を倍増くらいはしてほしいくらいの、これは議会の、品川の要望ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"競馬の運営は２３区で、東京都競馬株式会社が株を持っているから施設の所有は東京都です。運営側の視線からは、結構２３区の一員である品川区議会も関心を持って参加いただいているのですけれども、施設に対してもある一定の地元の要求というか、現状を競馬組合議会全体に把握をしていただいて、改善すべき部分は議長会として競馬株式会社なり東京都に対して要求する場面もあってもいいのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"今の厩務員宿舎の話等については非常にセンシティブな話なので、我々もいろいろ伺っていますけれども、例えば今議長がおっしゃったように、議会で議論がないものを議長会で取り上げることは難しいというのは、そのとおりだと思います。今、ご意見がお二人の委員から出ましたけれども、先ほどこれを取り上げてくれという話がありましたが、それは議運で発言をするということでよろしいでしょうか。","respondent":"渡辺議長","answer":"今の今なので、整理をしてどこがふさわしいのかをまずは議運の正副委員長なり副議長と相談させてください。その後、先ほども具体的な所管がどことか、本会議をはじめとする各種委員会、そういったどこがふさわしいかを相談させていただければと思っています。そういう考えです。","voiceIndex":57,"id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7093#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":11300,"voices":63}},{"id":"r07-20250630-6","meetingId":"r07-cm06","date":"2025年6月30日","dateIso":"2025-06-30","committee":"区民委員会","time":"午前１０時００分～午前１１時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第９５号議案、専決処分の承認を求めること","agenda":"第９５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"書面に自動二輪車とありますが、こちらはどのようなタイプだったのかというのと、車を運転していた職員側は１人で運転していたのか、またはもう１人助手席に乗っている状態であったのかというのと、非常に仕事に追われていたとか、そういうことの背景等、もしありましたらお願いします。","respondent":"平原地域活動課長","answer":"急いでいたとかという問題ですけれども、特段そのようなことはなかったものと認識しております。通常の運行時に安全確認を怠ったといったところが、本件事故の原因と認識しています。","voiceIndex":12,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"確認","question":"通常の自動二輪車ということで、それぐらい大きいものを見落としてしまったというのは、やはり安全確認を怠っていたのかなというのと、複数人乗られていたのであれば、やはり大人数の目で、一緒に後方等を確認していただくようにするといいのかなと思います。引き続き気をつけてお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認なのですが、ここは品川区北品川二丁目なので、第一京浜の品川健康センター周辺、あるいは山手通り沿いだと思うのですけれども、あそこの交差点のところは、車線変更する際、多分、禁止区間にもなっていると思うのですが、これは確認なのですが、車線変更禁止区間でやった接触事故ではないですよね。それだけ確認させてください。","respondent":"平原地域活動課長","answer":"本件交通事故事案につきましては、いわゆる車線変更禁止区間であるとか、そういったところの違反行為ではなくて、安全確認の怠りといったところの範囲となっています。","voiceIndex":16,"id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"今回のこの事案についての賠償について伺いたいのですけれども、これまでの事案で和解金額がここまで行ったケースというのは、あまりなかったのではないかなと記憶しております。それで、ここに書かれている相手方および賠償額の（１）が運転手、（２）が保険者となっております。ここのご説明をもう少ししていただけますでしょうか。もう少しこの賠償金についてのご説明をお願いします。","respondent":"平原地域活動課長","answer":"支払いの内容ですけれども、こちらの金額につきましては、交通事故の事案によりまして、この事案よりも多額の賠償に至った例というものもあります。事案によりけりですので、そういったところについては増減するものと認識しています。","voiceIndex":19,"id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"分かりました。ご説明いただいたことの理解が合っているかどうかをもう１回確認なのですが、そうすると、運転手本人と、運転手が加入している保険者への支払いという、こういう理解でよろしいでしょうか。","respondent":"平原地域活動課長","answer":"そのとおりです。","voiceIndex":21,"id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"参考までに、私は車を運転しないので詳しくはないのですが、交通事故の事案については、過失割合というのがあるかと思うのですけれども、それについては今回はどんな状況だったのか、参考までに教えてください。","respondent":"平原地域活動課長","answer":"こちらの負担割合につきましては、以前にご報告させていただきました物損につきましても、今回の人身につきましても、８対２、区側の責任割合が８、本人が２というところで、最終的に算定させていただいたものです。","voiceIndex":23,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"いずれにしましても、事故がないのが一番ですので、運転するに当たっても、再三もう事故防止策などをされているかと思いますけれども、何か特段、そういう庁有車を運転する際の、当然注意をするということは当たり前のことなのですけれども、それに加えて今回の事案で、さらにここを徹底しよう、ここをやはり強化していこうというところがありましたらば、教えていただきたいと思います。","respondent":"平原地域活動課長","answer":"改めて地域活動課自体といたしましても、こういった事案、今回ご承認いただけましたら、ご本人との関係で一定の区切りがつくということもありますので、改めて各所長を通じまして、庁有車の運行に当たりましての注意喚起を行ってまいりたいと考えています。","voiceIndex":25,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ再発防止に努めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"}]},{"id":"topic-02","title":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。昨年、第３回定例会のときの補正ですと、１億円余で、これは確認なのですが、前回だと１５０件というお示しがあったのですけれども、これは１５０件以上になったのかということを１点、お聞かせいただきたいと思います。","respondent":"小林地域産業振興課長","answer":"トータルとして、最終的には３７０件程度の申請という形で、今回、この実績も踏まえまして、あるいは令和５年度の実績なども踏まえまして、１か月１００件ぐらいのペースで来るのではないかということで、今回の見積りを行っているところです。","voiceIndex":41,"id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。それで、対象設備例として、これは全業種なのですけれども、前回のときはパーセンテージが大体どのぐらい、製造業がパーセンテージでこのぐらい多かったよとか、教えていただきたいのが１点と、あともう１点が、今、課長がおっしゃられたように、申請期間が前回は１１月下旬からになっているのですが、今回は９月１日からという、少し早めた理由というのも教えていただきたいと思います。","respondent":"小林地域産業振興課長","answer":"そのほかに、生活関連サービス業、あるいは製造業、医療業なども含めてというところですけれども、やはり令和５年度、令和６年度と通じて、商店街でのご利用、そういう店舗の運営をされている方が多かったと認識しております。","voiceIndex":43,"id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"意見","question":"どうもありがとうあります。それで、今回、周知方法の記載がないのですが、前回だとホームページとか広報しながわとか、あとメールマガジンとか、そういうので周知するというのが前回あったと思うのですけれども、それと同様に今回も周知をするという方向でいるのかどうかをお聞かせ願います。","respondent":"小林地域産業振興課長","answer":"今、委員ご指摘のとおり、周知方法については、ホームページですとか広報しながわですとか、あるいはＳＮＳを通じて周知してまいりますけれども、昨年度の実績、令和６年度に使われた方で、どういうところからこの補助金を知って活用されたかというのも聞いているのですけれども。","voiceIndex":45,"id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本当にこれは全業種対象なので、周知方法はしっかりとやっていただいて、取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで何点か確認をさせていただきたいのですが、まず、申請期間ですけれども、９月１日から１２月２６日まで、いわゆる年内３か月といった設定というのは、これまでも設定が３か月、４か月という設定だったので、今回もそういう設定なのか、いわゆるこの設定の根拠を教えていただきたいのが１点と、それから、この事業について、去年は３７０件程度の方にこれを使っていただいたということで、ここには。","respondent":"小林地域産業振興課長","answer":"今回、我々は補正予算としてやるということもあり、納品の期日とかも考えて、三、四か月を取ると、一通り事業者からの今年度のニーズというのは、対応できるのではないかというところで、今回こういった申請期間としています。","voiceIndex":49,"id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"ありがとうございました。一旦１２月２６日で終了しますけれども、その後、動向を見ながら、そういうこともしていくという考えを今の段階でお持ちなのかどうなのかというところを確認のためにお伺いしたいのと、それから、２回目も使えますよということで、前回も３割の方が２回目を使われていたということなので、大変にありがたいなと思いますので、その辺は理解をいたしました。","respondent":"小林地域産業振興課長","answer":"３点目が、それ以外も含めた景気動向といいますか、世の中の景気がどうかというところですけれども、令和５年、６年、７年も、やはり区内経済といいますか、国内の経済状況等もなかなか厳しいという中で。","voiceIndex":51,"id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。３点、考え方として、今後の見通し、当然ですが、今、この補正予算を組んでいただいて、さらに次のを聞くのも何だったのですが、でも、国の動向なりを見ながら、考え方としては持ってくださっているということですので、そういうことになった場合には、ぜひまたお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-015"},{"speaker":"こしば委員","kind":"質問","question":"私からは、目的と内容について教えてもらいたいのですが、目的が、今回の助成金を通じて、省エネ化や業務改善に資する設備への更新を促進し、事業継続の下支えおよび区内経済の活性化を図るということなのですが、そうすると、既存の設備を更新するということは、これまでの設備だと、例えば、今、電気代も上がってきておりますので。","respondent":"小林地域産業振興課長","answer":"ただいまのご質問ですが、今回の補助金も含めてですけれども、区の支援措置として、一般的なルールとして、区内に事業所を構えてから１年を経過した方というのを１つ条件にしております。","voiceIndex":55,"id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"それ以外に書類申請も可というと、窓口に直接来て、相談して申請をされる方もいれば、書類を送ってきて申請をされる方もいらっしゃると思うのですけれども、この窓口業務委託というのは、その申請、要は入り口の段階での委託が中心になるものなのか、また、さらにその中身のところまで踏み込んだ委託となるのかどうかも踏まえて、中身のことまで踏まえるとなると。","respondent":"小林地域産業振興課長","answer":"そういったところで、件数も最終的に４００件近くの件数になってくるというところで、なるべくスピーディーに審査を進めて、なるべく早くお金を振り込めるようにというところで、そういったところも含めて、従来の職員の体制。","voiceIndex":57,"id":"exchange-017"},{"speaker":"こしば委員","kind":"意見","question":"そこら辺がこの内訳だと少し分からなかったもので、安心しました。入り口、間口のところで委託をすることによって、交付決定までの時間を短縮といいますか、なるべく早めに見ることによって、事業者の方にいち早く支援が行くということで、かしこまりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"本事業、先ほどからの質疑、ご答弁を聞いていて、昨年もやって３７０件程度で、令和５年度もやられたということでしたけれども、こうした事業は今回で何度目になるのかを教えてください。そして、省エネルギー対策というところでは、省エネの効果だとか、想定されるＣＯ２の削減量だったり、そういったところの具体的な目標値があれば教えてください。","respondent":"小林地域産業振興課長","answer":"もう一つ、省エネ効果をどういうふうに設定しているかというところですけれども、我々としてはなるべく幅広く使っていただきたいので、省エネ効果がもちろん高いものというのですかね、より古い機種を交換すると、今。","voiceIndex":61,"id":"exchange-019"},{"speaker":"せらく委員","kind":"質問・要望","question":"先ほどのお話の中でも、今回で３度目ということで、２度目の利用者もいながら、新規でも使っていただいて、事業継続性を支えたいということがあったと思うのですけれども、新規の方に、こういった効果があるとか、好事例といいますか、そういったところの広報などはされていますでしょうか。","respondent":"小林地域産業振興課長","answer":"我々、電話での問合せというのを、まず最初にかなりの件数お受けしているのですけれども、そもそもこういう設備を入れようと思っているのだけど、まだ今回初めてなのだけどということでご質問をいただくのですが、そういう場合には、令和５年度、令和６年度で。","voiceIndex":63,"id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"ほかの委員から多く質問が出ましたので、私から最後に１点だけ、窓口業務委託の質問が出ていましたけれども、こちらの委託する先というのはどちらでしょうか。","respondent":"小林地域産業振興課長","answer":"これは入札で毎回決定するので、今回どこかというのはまだ正式に決定していないところですけれども、昨年度の例で申し上げますと、人材派遣会社を通じてスタッフの方に来ていただいて、一緒に事務作業をしていただいたところです。","voiceIndex":66,"id":"exchange-021"},{"speaker":"おぎの委員","kind":"質問・要望","question":"慣れた方がされたほうが早いのかなというところはあるのかなと思いますけれども、入札ですので、透明性を持って、いろいろな可能性でやっていただきたいとは思います。困っている事業者の方には、もう本当にスピーディーに、一刻でも早く支援が行き渡るように、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-022"}]},{"id":"topic-03","title":"令和７年陳情第２４号、シナモロール以外のキャラクターも品川区で採用する陳情","agenda":"令和７年陳情第２４号、シナモロール以外のキャラクターも品川区で採用する陳情","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それで、着ぐるみの回数、シナモロールの経費が高くなったということで、回数を減らしていく意向のようなお話だったのですけれども、具体的にどういうふうに回数、今まで５回出演していたのが何回になるのか、分かる範囲でいいのですが、教えていただきたいと思います。","respondent":"大森文化観光戦略課長","answer":"そういったところで、３０分で触れ合える人たちとかファンの方たちとか、そういったことを考えていくと、１人当たり幾らになっていくのだろうとかということを考えると、結構高い金額になってしまうなというところがございまして。","voiceIndex":85,"id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問","question":"今まで５回出演だったのが、減らすということでいいのですか。何回になりますよとか、ある程度、お分かりになる範囲で教えていただければと思います。","respondent":"大森文化観光戦略課長","answer":"具体的なものはついていないのですけれども、予算のときは令和６年度と同等で５回ということでやっています。","voiceIndex":87,"id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。もっと、何というのですかね、先ほど週１回でしたか。なので、これを含めてもっともっと、このハタチの龍馬の知名度の向上のためにやっていただきたいと思います。そういう小学校とかにも出前授業ではないけれども、もっとそういう部分を含めて、何か知名度向上のためにやっていただきたいと思っていますけれども、その辺について見解をお知らせいただきたいと思います。","respondent":"大森文化観光戦略課長","answer":"ハタチの龍馬の見習いが取れるか、取れないかというところですけれども、この陳情の中にあるように、やはり知名度的にはまだまだ低いなというところがあるので、しばらくはそのままというところと、シナモンとの差別化みたいなところもあるので。","voiceIndex":89,"id":"exchange-025"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"小学校、特に荏原地区というのは、まだ認知度がすごく低いのかなと思っているので、小学校だけではないですけれども、そういう教育を含めて、荏原地区にもっともっと、広めていただいているのは分かるのですけれども、今まで以上に認知度を広げるためにやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-026"},{"speaker":"おぎの委員","kind":"質問・要望","question":"８年前に、２０１７年２月１３日から就任したということなのですが、そもそもこの品川区の観光大使がシナモロールに至った経緯というのと、そのときにほかのキャラクターも同時に検討していたのか。ほかのキャラクターを検討していたのであれば、提示されている使用料みたいな資料等があれば、分かる範囲で教えていただきたいなと思います。","respondent":"大森文化観光戦略課長","answer":"品川区の観光大使についての経緯というものですけれども、一番最初は、平成１９年、２００７年に五反田にキャッツシアターがありまして、そちらのキャッツを観光大使に任命したというのが一番最初の起こりです。","voiceIndex":93,"id":"exchange-027"},{"speaker":"おぎの委員","kind":"提案","question":"そうしますと、サンリオから提案されたのでシナモロールということなのですね。非常に人気で、しながわと書いてある青いシャツを着ているときは、観光大使という認識でいいのかなということと、別件なのですけれども、今回、品川区のロゴが「わ！取りあえずその２つ。","respondent":"大森文化観光戦略課長","answer":"青いＴシャツにしながわと平仮名で書いてあるときが、シナモロールの観光大使のコスチュームという形になります。なので、例えば、公式のＳＮＳ、Ｘとか、そういったものがあるのですけれども、そちらで品川の観光をＰＲするというのができないという状況になっています。","voiceIndex":95,"id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問・要望","question":"関連なので、分かる範囲で教えていただきたいのですが、名前が挙がっていましたハタチの龍馬のほかに、品川区の各所管でいろいろキャラクターを今つくられていると思うのですけれども、くるみプランのくるみちゃんとか、パラリンピックのときのビーチュウとかやたたまとかでしたか、これと、あとほかに今、戸越とか品川区内の商店街で、戸越の銀次郎とか。","respondent":"大森文化観光戦略課長","answer":"申し訳ございません。","voiceIndex":97,"id":"exchange-029"},{"speaker":"こしば委員","kind":"意見","question":"結論を出すでお願いします。不採択。意見としましては、そもそもこれは大変、財源ありきの話です。当然、費用対効果を、ほかの事業もそうですけれど、常に考えた上で事業を実施されておりますので、こういったことはやはり精査をして進めていくべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"それで、今、質疑、また所管の課長からのご説明をお聞きして、これだけの予算と、特に着ぐるみについてはこれだけの費用が今後はかかっていくのだなといったところを見ると、一定程度シナモロールについては、今年２位だったとはいえ周知が図られてきているので、その分を、先ほどのご説明で行くと、ハタチの龍馬のほうに着ぐるみなども振り分けながらというところがあるのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-031"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。それに対して、シナモロールは品川区とフィットしていると感じておりますし、浸透してきているので、シナモンだと、広報の効果を戦略的にも出せるのではないかというところから、引き続き頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。ぜひ、こんの委員がおっしゃるとおりで、見習いから昇格していただきたいというのは、要望として挙げさせてもらいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-033"},{"speaker":"おぎの委員","kind":"意見","question":"本日決めるで、不採択で、費用面を考えても、今のところ新しくというよりは、ハタチの龍馬はじめ、現役のキャラクターの認知度を上げることに注力したほうがいいのかなというのと、それぞれの地域で思い入れのあるキャラクターがたくさん現役で今活躍していますので、そういったことで不採択ですが、今、森澤区長が掲げている「しあわせ多彩区」ということで、シナモロール一択だけでなく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7101#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23669,"voices":112}},{"id":"r07-20250630-7","meetingId":"r07-cm06","date":"2025年6月30日","dateIso":"2025-06-30","committee":"厚生委員会","time":"午前１０時００分～午後 ２時４９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８３号議案、品川区指定障害児通所支援の事業等の人員、設備および運営の基準等に関する条例の一部を改正する条例","agenda":"第８３号議案、品川区指定障害児通所支援の事業等の人員、設備および運営の基準等に関する条例の一部を改正する条例","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"ご説明ありがとうございました。内容は特に当然反対するものではなくて、粛々と進めるべきものと思っているのですが、２点だけ確認させてください。１点は、今回この対象となる施設が品川区には既にあるのか、存在しているのかどうかということと、あとは、これは認証保育所ということですけれども、認可保育所等ではこういう施設が品川区内には既にあるのかどうか、この２点だけ確認をさせてください。","respondent":"佐藤障害者施策推進課長","answer":"１点目、今回の改正の認証保育所と児童発達支援事業所の併設ですけれども、こちらについては、区内には現在、対象になっている事業所についてはございません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"差し支えなければ、認可保育所等はどちらの業者なのか、今回の対象ではないのですけれども教えていただければと思います。","respondent":"佐藤障害者施策推進課長","answer":"認可保育所等は、児童発達支援の事業所としましてはコペルプラス西五反田というところで、そちらの併設の保育園はウィズブック保育園西五反田と確認しています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"東京都が認証保育所だけにしたというのは何か理由があるのかを１点伺いたいのと、それから、この２つの施設が併設されることによって設備や人員の共用・兼務ができるというようなことなのですけれども、具体的にはどのように変わるのかというのがちょっとよく分からないので、例えば人数は少なくて済むということになるのか。","respondent":"佐藤障害者施策推進課長","answer":"順にお答えします。今回、認証保育所だけなのかというところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、認可保育園と指定児童発達支援事業所が１か所もう既に品川区で併設されているということなのですけれども、これはもう既にそういうような形で併設の緩和というのか、そこら辺のところがもう実施されている、それに加えて今回は認証保育園がプラスされるということで捉えていいのでしょうか。実際に認可保育園でなっているところが具体的にどうなっているのかということを教えてください。","respondent":"佐藤障害者施策推進課長","answer":"先ほどの説明で申し上げたとおり、国の制度改正は令和５年に行われておりますので、併設されている事業所におきましては区のほうの条例も横引きしておりますので、今回の内容につきましては既にできる状態にあったというようなところでご理解をいただければと思います。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"多分これはインクルーシブ保育を実施する場合の人の配置というのが共用・兼務することができるというようなことになると思うのですけれども、でもその人数に対しての配置基準というのはしっかりと守られるということで、それが少なくていいよということになるわけではないということで確認させていただきたいと思っているのですけれども、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"条例改正の内容のとおりですけれども、例としましては保育園の従業者が支援に支障がない場合に限って障害者の支援に直接従事するようなこともできるということになりますので、委員のご指摘のとおり。","voiceIndex":14,"id":"exchange-005"}]},{"id":"topic-02","title":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そのことに対しては、今回の引上げによってそれが解消されるという見通しがあるのか、３３人足りないというのはかなり大変な足りなさではないかなと思っているのですけれども、その点については区としてどう考えられているのか、特に大崎第一のところが３４人に対して２４人ということで極端に少ないなと思ったのですけれども、そこら辺のところは区としてどう考えているのかについて伺いたいと思います。","respondent":"東野福祉計画課長","answer":"不在地区に対してはできるだけ推薦いただけるように、今回の一斉改選の説明でも各町会のほうへ申入れをしています。","voiceIndex":32,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その上で若干伺いたいのですけれども、ここのところでサービスの縮小や事業の休廃止につながるおそれがありというようなことで書かれているのですけれども、第１回定例会の代表質問で、この５年間で休廃止となった訪問介護事業所は１２か所ということでの答弁だったのですけれども、その後、たしか令和６年度で２か所廃止になったという答弁もあったかと思うのですけれども。","respondent":"菅野高齢者福祉課長","answer":"３点質問いただきましたので、順番にお答えします。令和６年度以降、介護報酬が令和６年４月に改定されましたので、それ以降の廃止となった事業所については、区内では４か所あると捉えております。","voiceIndex":34,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今回の給付額というのは訪問介護の介護報酬を請求して、東京都国民健康保険団体連合会で確定したことに対しての一律に２.５％分を支援金ということで給付するということで考えていいわけですか、そのことも確認させてください。そうすると、区内の全事業所が対象になるというようなことで考えていいのかということも確認させていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"次回の介護報酬の改定までというところですけれども、次回、国がどういう形で介護報酬、訪問介護についてするのかというのは、まだ国のほうも今いろいろ調査をしながら。","voiceIndex":36,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのところで、あとこれは今後の検討をぜひしていただきたいなと思っているのが、事業所が他区にあるけれども、その支店というか分室みたいな形で品川区に事業所があって、その事業所が区内の高齢者の訪問介護を、かなりの人数を実際に受け持って品川区で事業所展開している、だけれども事業所の本部は他区にある、でも品川区の高齢者をたくさん受け持っているという。","respondent":"菅野高齢者福祉課長","answer":"申請の仕方については、毎月の東京都国民健康保険団体連合会から来た介護給付費を基に申請していただいてということにはなっておりますが、月ごとに申請していただくことも結構ですし、事業者によってはある程度まとめてという形でも、どちらでも受付は可能となっておりますので。","voiceIndex":38,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"意見","question":"次のもあるのですけれども、取りあえず一旦、皆さん、どうぞ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-010"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"そういうことがあっても、それでもやはり担い手というのが出てこないというところがあるので、これは予算のところなので要望にしますけれども、他の自治体でどういうような選出方法をされているのかとか、これから担い手不足の解消の取組について、区のほうで新しいお考えがあればぜひ進めていただきたいと、これは要望で終わりにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、質疑の中で大分理解できてきたのですけれども、このたびは訪問介護サービス事業者安定運営支援金ですので、あくまで事業所の運営の支援という理解でよろしいですかということと、前に区が実施した、それは賛成、本当にいい事業だったと思うのですけれども、働いている方たちのための居住支援という形で働いている方たちのための支援で。","respondent":"菅野高齢者福祉課長","answer":"手続につきましては、先ほどの鈴木委員の質問にもありましたけれども、できるだけスピーディーに支給ができるようにということで月ごとの給付に対してというような場合と。","voiceIndex":44,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。配慮されているということは理解いたしました。ただ、それがその事業所にとってどう感じるかというのはまた別のことなので、今後も働いている方たちと、それから事業所の運営の負担というのは常に考えながらいろいろな施策を打っていただければと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、もう一回、先ほどの鈴木委員の質疑の中で確認させていただきたいのですけれども、今回指定事業者数が５８事業所あって、区内にも同一建物減算を算定している場合は対象外となると、これが数施設あるというお話でしたが、今回のこの５８事業所の中に数施設あるという意味なのか、それともこの５８事業所はそれを除いた数と、まさに今回の対象となるということなのか、私は聞き取れなかったので。","respondent":"寺嶋福祉部長、菅野高齢者福祉課長","answer":"訪問介護事業所の利益率が上がったことについては、サービス付き高齢者住宅の併設が悪いのではなくて、併設している建物の人に全てをそこの併設事業者の訪問介護だけでケアプランを組んでいるということが問題であって。その辺りについては給付費等を確認しながら、また慎重に引き続き実施していきたいと考えています。","voiceIndex":48,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もちろん、介護事業所、訪問介護事業所の救済という言い方はちょっと上から目線なのかもしれませんけれども、そこはさっき部長からご答弁いただいたそこの実態と合ってないと、そのとおりだと思いますので、そこのところの今回の差を埋めるためのものだというのは理解できたのですけれども、では、何のためにそれをするのかという大本のところ、もう少し申し上げれば。","respondent":"寺嶋福祉部長","answer":"事業そのもの、究極的な給付のピンポイントの目的は、もちろん訪問介護事業所が利益率のために引き下げられて困っているというところがあるのですけれども、そこを支援する目的は何なのかというと。","voiceIndex":51,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"言わずもがなというところがあると思うのですけれども、そのとおりだと思いますし、先ほど申し上げた区長の記者会見の資料の中で、国が推進しているにもかかわらず基本報酬を減額改定したということに対して区として、やはりそれは何らかのことをしなければならない、それは品川区がこういったことをすることによってほかの自治体もこういったことに目を向けるようになると思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"提案","question":"そこでちょっと確認なのですけれども、次回の介護報酬の改定があるまでということで、先ほど鈴木委員ともやり取りがありましたけれども、基本的に考えれば２０２７年４月ということになりますが、もしかしたら今、全国的というか、こういった訪問介護事業所の切迫した声というのは高まっておりまして、期中改定が臨時的に。","respondent":"菅野高齢者福祉課長","answer":"そうなったときには、その改定がどのような形で訪問介護事業者の実態に沿っているのかというところをしっかり検証しながら、この支援金を続けるかどうかの判断はする予定となります。","voiceIndex":55,"id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、例えば期中改定が行われましたと、ただ今回は２.５％という支援金ですけれども、それが例えば期中改定が２％でしたと、０.５％下がると足りませんというときは、例えばその０.５％分に切り替えて支援金を出すということもあり得るという理解でよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"細かい部分については、そうなってみないと分からないというところもありますが、例えば、今委員おっしゃったような２％がどういう根拠で算出されたのかという部分も踏まえながら、区としてどういう対応をしていくかというのは考えていきたいと思います。","voiceIndex":57,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"今回の支援金によって１事業所で月に増え幅でいくと大体幾らぐらいから幾らぐらい、何万円から何十万円ぐらいの月の支援金になるかという事業所ごとの大体の目安みたいなものがもしありましたら教えていただきたいのですが。","respondent":"菅野高齢者福祉課長","answer":"給付に対して２.５％ということになりますので、おそらく１万円から２０万円くらいの振れ幅があるかと思います。","voiceIndex":59,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"月に１万円から２０万円ということは、年にすると１２万円から２４０万円分の支援金を出していただけるということで、非常にありがたく思っております。逆に言うと、今回の２０２４年の減収によって、年１２万円から２００万円以上、２４０万円ぐらい減収した事業所があったという事実でもあると思うのです。これは要望で、答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これはガソリン代が値上がりした分の支援金ということで出されているということでいいのか、この１,７００円の根拠について伺いたいと思います。それから、対象期間ですけれども、４月１日から９月３０日までの６か月間ということでここに書いてあるのですが、その後はどのようになるのかについても伺います。","respondent":"菅野高齢者福祉課長","answer":"１０月以降の予算計上については社会情勢を踏まえ、また都の動向を注視していきたいと考えております。","voiceIndex":63,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、ガソリン代がこのまま値上げがそのまま続くような状況であればこれも継続されるということで、値上げが続いている限りはぜひとも継続していただきたいと思うのですけれども、その点も改めて伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"繰り返しの答弁になりますが、１０月以降につきましては東京都の動向も踏まえながら、社会情勢を見て判断していきたいと考えています。","voiceIndex":65,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"提案","question":"１,７００円掛ける６か月分で１万２００円ぐらいの支援ということになるわけですけれども、今までゼロだったわけなので、これが出されるということは事業者としても助かりますということで感想も、「こういうようなことで提案されたのですよ」ということで言ったらそういうように喜ばれておりました。これは要望です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この燃料費高騰の支援金について、車１台当たり１,７００円ということで、各通所介護事業所の所有台数がどういうところで申請を受けるという形になるのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"地域密着型の定員等も踏まえて、２台から３台は各事業者がお持ちなのかなというところで見積りをしていますので、今後受付を開始して、そのような実態が見えてくるのかなと考えております。","voiceIndex":69,"id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"確認","question":"今の時点で正確に把握しているというよりも、大体これぐらいかなというところで見積もっているということでよろしいということで、確認でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"その辺のことで事業者からそういう実態を聞いて、ヒアリングして、何かの形で平均してこれぐらいだったら妥当だなという算出をされたのか、事業者の実態の調査とこの金額はどのように連動しているのか、教えていただけたらありがたいです。","respondent":"菅野高齢者福祉課長","answer":"今後、申請していく上で事業者とやり取りをしていく中で実態等も見えてくると思いますので、この部分につきましては、今後予算編成をしていく中で検討していく課題となっていくかなと捉えております。","voiceIndex":73,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ありがとうございました。いろいろ難しいのはもう重々承知なのですけれども、事業者としてどれぐらい本当に負担になっているかということは何かの形できちんと調査しながら今後の施策につなげていっていただけたらと思います。これは要望でとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-027"}]},{"id":"topic-03","title":"令和７年請願第８号、大井・西大井地区に地域包括支援センターの設置と特別養護老人ホームの増設を求める請願","agenda":"令和７年請願第８号、大井・西大井地区に地域包括支援センターの設置と特別養護老人ホームの増設を求める請願","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今の段階で、地域包括支援センターをつくるということでスケジュール的に、令和９年からはモデルで、第１０期に入るときにモデルで始めるというところなのでけれども、それまでの大まかなスケジュール、おおよそどれぐらいの地域にどれぐらいつくるというところがいつ頃どういう形で決まるのか、それから、運営協議会で検討していくということですけれども。","respondent":"菅野高齢者福祉課長","answer":"介護保険制度推進委員会と、こちらの地域包括支援センター運営協議会が兼ねているというような実態に今はなっておりますので、実態としましては、昨年度の３月に行われた介護保険制度推進委員会の中で、運営協議会を開催した際にはこういった在り方を検討するので。","voiceIndex":89,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は、これから地域包括支援センターが地域につくられるということは品川区にとってはすごく大きな転換になるわけですので、そういうところを厚生委員会の中でも、事業所を公募しているわけですから、そして予算も使っているわけですから、そういうところはぜひとも報告していただいて、区が課題の洗い出しもしているということであれば。","respondent":"田中委員長","answer":"委員会での報告に関しましては、今後委員長、副委員長と協議をし、理事者との調整をした上で、内容については決定して対応していきたいと思います。","voiceIndex":91,"id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"Ｂ判定の方も入れる、Ａで入らなくて辞退した人がいれば入れる可能性があるというようなことで、Ｃの方はほぼ入れないという状況になると思うのですけれども、Ｃ判定の方が何人いたのかということを教えていただきたいのと、あと、令和６年度の第１回の３９３人という方はもう既に、これは去年の８月末までに申請した人で９月に入所調整会議にかかった方で。","respondent":"菅野高齢者福祉課長","answer":"ただ、結果を通知するときに、今、特養ホームは３か所まで希望できるということになっていまして、入所希望者数の一覧というのもお伝えさせていただいていまして、傾向としてどういった場所を希望するかにもよって。","voiceIndex":95,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところでいえば、私は所要量を出す、必要な数を出して土地をどう確保していくかということで、ぜひそういう観点でやっていただきたいなと思うのですが、いかがでしょうかということと、もう一つ伺いたいのが、今回の請願というのは大井・西大井地域に特養ホームを造ってくださいということなのですけれども、品川区は。","respondent":"東野福祉計画課長","answer":"そういったものを全体的に考え合わせながら、建設につきましては今後も検討してまいります。","voiceIndex":97,"id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それに比べて、大井・西大井地域はロイヤルサニーの６０ベッド、１か所しかないということでは本当に地域のアンバランスがあって、住み慣れた地域でいつまでも暮らし続けたいというのが品川区の大きな方針になっていると思うのですけれども、それは在宅でということなのですが、在宅でもう限界といったときには特養ホームに入れるようにと。","respondent":"菅野高齢者福祉課長","answer":"特別養護老人ホームを住み慣れた地域にというようなお話でしたけれども、例えば高齢者福祉課のほうでは区内１２か所ある特別養護老人ホームを一手に区のほうで一括して申込みを受け付けて、入所調整をしていますが、ご希望の傾向を見しますと。","voiceIndex":99,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは、個々人の家族の経済的な状況だったりとか、家族関係の状況だったりとかに合わせて、もちろんそういう多床室でないと希望できないであったりとか、もう限界なのでとにかく早く入れてほしいということで三多摩のほうを希望するというようなことはあると思うのですが、でも多くの高齢者はやはり住み慣れた地域で最期まで暮らしたいというのが思いだと思いますので、そういうところからも。","respondent":"菅野高齢者福祉課長","answer":"そうすると、この間見た限りだと、例えば高い所は月額６５万円とか、そういうような傾向は出ております。そこに介護報酬の自己負担分も加わるのかなというところです。平均的には恐らく３５～３６万円前後ではないのかなと捉えております。","voiceIndex":101,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、ぜひそういう品川区の入所調整会議にかかる方が、要介護３以上しか申込みができないという状況になってもそういう状況がずっと続いているわけですから、ぜひとも特養ホームの増設に向けて、特にこの大井・西大井地域にはロイヤルサニー１か所しかないわけですから、そこにぜひとも造っていただきたいということで要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-034"},{"speaker":"えのした副委員長","kind":"意見","question":"本日結論を出すで、不採択です。理事者のご答弁でもございましたが、大井・西大井地区には在宅介護支援センターもありますし、こちらを増設３か所していくということで、特別養護老人ホームについては計画的に進めると。地域包括支援センターは令和９年４月、第１０期にモデル地区の実施ということで、地域はこれからということでしたが、なかなか地区の限定は今の段階では難しいと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-035"},{"speaker":"大倉委員","kind":"確認","question":"特別養護老人ホームについてもできる限り設置をしていき、今も３つ、お話の中であった小山台、八潮、東大井に設置していって、着実に今も増やし続けてきているというところで、人によっては各個々人の事情もあって、どういう所がいいかというのは人によるというところもお話がありましたけれども、整備についてはしっかり進めていっている状況だということを確認できましたので、この請願については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどからのご説明がありましたとおり、昨年の私どもの会派としてもこれは一般質問、求めていたところの地域包括支援センターの在り方と在宅介護支援センターとの役割分担についてということで、区長からも再検証する時期に来ているということで、地域包括ケアシステム全体の再構築を検討していくというご答弁からこうした動きになっていますので、この点については、今進行中ということになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。地域包括支援センターはこれから整備していく、令和９年度にモデル実施ということで本当に大転換で、そういうことは評価するところですけれども、大井・西大井地域というのは日常生活圏域の６つのうちの１つということになるわけですから、地域包括支援センターをつくるとなったらば、この地域にも当然つくられるということになるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-038"},{"speaker":"吉田委員","kind":"意見","question":"私からは本日結論を出すということで、採択でお願いいたします。理由といたしましては、最初の地域包括支援センターについては、生活者ネットワークは何年か前に品川区に調査をお願いしています。そのことからいっても、現場も地域包括支援センターとしてきちんと整備してほしいというお声と私どもは受け止めております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-039"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すということで、趣旨採択にしたいと思います。説明だけします。他方で、ただ５８５人の方の請願の署名もあったということなので、これは重く受け止めてほしいというところで趣旨採択にしたいのですが、恐らくこれは３つに割れてしまうということで問題が起きると思いますので、私は採択のほうに寄せします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-040"}]},{"id":"topic-04","title":"令和７年請願第１１号、国に対して、国が引き下げた訪問介護事業者への区の減収補填分を区に補填することと","agenda":"令和７年請願第１１号、国に対して、国が引き下げた訪問介護事業者への区の減収補填分を区に補填することと","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"訪問介護の報酬が引き下げられたということを引上げを求めるという請願はもう３回出されて、こういう審査が繰り返し行われているわけですけれども、前回の審査のときに、私は区としてもそういう現場の実態を把握していただきたいということで意見を言ったときに、区内には２０か所の在宅介護支援センターもあって、ケアマネジャーとかに実態を聞くほかに、在宅介護支援センターごとに地区ケア会議があって。","respondent":"菅野高齢者福祉課長","answer":"２３区から全国の市長会のほうに上がっていって、最終的に国に要望するというような段取りを取っていますので、今はその途中の過程なのかなというところで捉えております。","voiceIndex":119,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、これだけ品川区としても国が引き下げたためにその対応を取るということで３,９００万円からの予算を計上するということになりましたので、その対応というのは本当に評価するところなのですけれども、国がそういう対応を取らなければこういう支出はなくて済んだわけですから。","respondent":"菅野高齢者福祉課長","answer":"今ご指摘の調査というのは、令和７年度の介護事業経営概況調査の実施についてなのかなと捉えております。","voiceIndex":121,"id":"exchange-042"},{"speaker":"鈴木委員","kind":"意見","question":"訪問介護の場合は実際に介護のところしか報酬にならなくて、移動時間、移動しなければ介護ができないにもかかわらず移動が基本報酬の中に入ってないということが大きな問題で、特に山間地とか離島は特に大変だし、都市部でもそういう移動時間というのは大体１５分ぐらいはかかるということも聞いていますので、そこのところの実態が把握されて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"提案","question":"例えば前年度、自民党・無所属の会の厚生委員会の委員の方の請願・陳情に反対した理由としては、国が今動いているのだから待つべきだということを、去年の１０月の審査のときのも恐らくおっしゃっていたと。今回、今年の年明け２月になって初めて切り分けた調査をするよというのが提案されて、５月から実施されたということが先ほど鈴木委員への答弁の中にありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの審査のときも言いましたけれども、私たちも調査をしているのです。生活者ネットワークとしてもそれはいろいろな機関紙とかそういうもので公表しています。そういう国の方針を区が補填しているわけですから、それは品川区としては当然国に対して要求してもいいことなのではないかなと私も思うところです。手順を踏んで意見書の提出というのは行うべきなのではないかなと私も感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどからの委員のご意見を拝聴しているのですけれども、そうした場合、ここで請願の事項にあるような形で補填した自治体の財源負担を補填すること、基本報酬を全産業の平均引上げ率以上に引き上げること、この財源をどこに求めるのかというのは、私は逆にほかの委員に聞きたいのですけれども、これどのようにお考えになっているのですか。これはいわゆる介護保険料を上げるということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-046"},{"speaker":"鈴木委員","kind":"提案","question":"それなので、私たち共産党としては国の負担割合を２５％から３５％に１０％引き上げる、そうすることで介護報酬のことが直接介護保険の保険料の引上げにならなくて済む、だから国の負担を増やす、税金を投入するということをしない限りは介護保険の崩壊になるので、自民党や公明党が野党時代に提案していた１０％引き上げるというようなことを一緒にやりましょうよということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど私が申し上げたのは財源をどこに求めるかという話をしたので、それはどこの国家の予算から持ってくるおつもりなのか、それをはっきり教えてくださいと申し上げたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"提案","question":"国の財源をどうするかということですから、大企業の法人税は消費税が導入、増税されるたびに減税されて、今や中小企業の半分ぐらいしか大企業は払っていないというのが実態なのです。１０％ぐらいしか払っていないという実態ですから、そういう優遇税制を改めるということで社会保障の財源もつくることができるという提案です。それから、株でもうけた人の１億円の壁というのもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"意見","question":"すみません、ほかの委員のご意見はないのですが、一応共産党のお考えは拝聴いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"質問","question":"それがある上で、私の所属しているれいわ新選組の考え方としては、一部共産党とも重なるのですけれども国の負担割合を増やすとか、いわゆる法人税の累進制を含めて、本当にものすごいもうかっているところから税を取ると、あと所得税に関しても累進制を残して１億円の壁をなくしていくということもありますし、あと我々として独自で言っているのは国債をもっと積極的に発行して財政出動するということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの請願事項のところで、訪問介護の基本報酬を全産業平均の引上げ率以上に引き上げるよう求めることということも書かれているのですけれども、この全産業平均の引上げ率というのは、多分賃上げのことなのかなと思うのですけれども、この賃上げというのが２０２４年の春闘で平均で５.１％で、今年２０２５年度の平均賃上げ率が５.３２％になっているのです。","respondent":"菅野高齢者福祉課長","answer":"今のご質問についてのお答えですけれども、一つ一つの介護事業者の実態というか、その辺りのところまでは詳しくは確認が取れておりませんが、区としては、少しでもというところで介護事業者に向けては居住支援手当を支給させていただいてプラス１万円。","voiceIndex":137,"id":"exchange-052"},{"speaker":"鈴木委員","kind":"意見","question":"これだけ全産業が賃上げ５％されても実質賃金マイナスという状況の中で、改めて訪問介護の報酬が引き下げられたというのが二重に大変な事態をつくり出して、さらに全産業との格差を広げるということにつながっているというところが、今回国が行った基本介護報酬の引下げのマイナスというか、本当はしてはいけなかったことなので、本当にこれは早急に是正しなければならない問題ではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-053"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。先ほど理事者のご答弁からも、国はより詳細に実態を把握するとしておりますし、２３区の区長会、上部組織へこちらも要望しますし、国へも段取りをしているとありましたので不採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-054"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すというところと、不採択でお願いいたします。なので、国は国でしっかりまた考えていただきながら、今回調査を実施した中で、まだ足りないところあって設問が増えたとか、そういうところも国のほうは国のほうでしっかり考えていただいて実施していくというところで言うと、これを議会としての意見書として提出するところではないのかなと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただ、先ほど委員の中からあった補填を国に求める意見書を上げるというその根拠として国の負担割合を上げる、そして富裕層への課税強化、そして国債を発行するというようなお話もありましたけれども、残念ながらこれは今、国会ではそのような検討、国会ではそういうご意見が出ているのだと思うのですけれども、今そういった形にはなっていませんので、このままもし意見書を上げれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-056"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ深刻な状況を引き起して、訪問介護の事業所が倒産、廃止に追い込まれているわけですから、本来であれば期中の改定も求めるべきだと思います。ぜひとも自民党、公明党が野党時代に出していた１０％国の負担割合を増やす、こういう方向もぜひとも検討していただいてそういう方向を打ち出していただきたいということの要望もさせていただきながら意見、態度表明とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区はあくまで国がやるべきことを補填したということですから、それについて国に求めるのは当然だと思いますし、区民としては、本来品川区民のためのほかの事業に使われたかもしれない予算をここに充てたわけですから、その分の補填を求めるのは当然の思いだと思いますし、この請願審査というのは区民の思いをどう判断するかということだと思いますので、その点については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"意見","question":"先ほど財源というお話も出てきましたけれども、例えば防衛増税、軍事費を上げるというのは、特にどこで財源をつくりますという話は一切出ないまま、５年で４３兆円上積みということが話し合われて、そういうところからして、財源、財源と言うのは、必要なときには言うけれども、出したくないときは言わないというようなことが整理していると非常に見えるなと思っているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-059"}]},{"id":"topic-05","title":"１８歳の壁をなくすために心身障害者福祉会館等の施設整備を求める陳情","agenda":"１８歳の壁をなくすために心身障害者福祉会館等の施設整備を求める陳情","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"１８歳の壁となっていますけれども、特別支援学校とかそういうところを卒業される方が大体毎年十五、六人はいらっしゃると伺っているのですけれども、その辺の認識は間違いないでしょうかというのが１個と、そういう方たちが区内の施設に通所なりなんなりしていかなければいけないと思うのですけれども、その辺の受入れ状況というのはどのように計画されているのか。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"私からは、特別支援学校の卒業生ということで十数名の認識で間違いがないかということですけれども、卒業生については十数人いらっしゃいます。受入れ状況、施設整備につきましては、今申し上げた状況を踏まえて生活介護、その他などのサービスの状況を把握しているところでして、先ほど申し上げました生活介護につきましては、ピッコロの受入れ拡大や。","voiceIndex":154,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。もちろん卒業された方で確かに就労される方たちがいらっしゃるということは認識しているのですけれども、でも最低限、区でこれだけの受入れは予定しておく必要があるのではないかなと思うのです。だから、それがどこかに明記されているのであれば、それを教えていただきたい。そういうことがないのか、その辺についてもきちんと点検されながら事業が進められているのか伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"整備の計画の明示というところですけれども、所要量の把握につきましては、先ほど申し上げたようなところで障害者支援課とも情報共有しながら、卒業生、それから、その方がそれぞれどのようなサービスを希望されているかというようなところも含めて対応を検討する中で。","voiceIndex":157,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、高齢者施設の部分の説明会が開かれてから大分時間がたっているのですけれども、ごめんなさい、私が見落としていたとしたら申し訳ないのですが、説明会とか、そういう今現在どのように事業が進んでいるかについて、どこかで公表されているとしたら伺いたいのですが。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長","answer":"障害者施設についても、また説明などを行う機会を設けてまいりますので、その際には詳しくお伝えできるかと思います。現在予定している施設等の整備予定につきましては、障害福祉計画にページを設けて記載している内容で皆様にご覧いただけるような形で、大枠につきましては。小山台の特養施設につきましては、大きい施設ということもありまして東京都との補助金協議なども必要なので、先に事業者を決める手続なども踏まえまして。","voiceIndex":159,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"ということは、同じ所に建つ建物だけれども、障害者のことについてはまだ全然公表できるようなスケジュールもないということなのでしょうか。同じ場所の建物で、そんなにずれがあってうまく進むのかしらとかいうのも、素人考えですけれども思ってしまうのですが、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"委員のご質問ですけれども、先ほど福祉計画課長から答弁したとおり、事業者の選定等につきましては補助金等の関係から手続が進んでいるものがありますが、障害者施設の部分の内容につきましては。","voiceIndex":163,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"さっきピッコロのことについてもちょっとお答えいただいてしまったのでというか、どの程度の事業なのかとか、それから、どれくらいの施設なのか、私は視察に行ったことがあるのですけれども、あまり１人当たりのスペースが広いような状況ではなかったような気がしていて、スヌーズレンとかの部屋も別個にあったりしたのは確認したのですけれども、どれぐらいのスペースで、どれぐらいの受入れがあって。","respondent":"佐藤障害者施策推進課長","answer":"初めの施設の開設時期、それから事業開始の時期につきましては、今後施設の概要をご案内する際にそこを意識して、お伝えできるようなところにつきましては、今まで不足している部分があったとすれば対応できるように努めてまいりたいと思います。","voiceIndex":165,"id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、二重に聞いてしまうかもしれません。だからピッコロは事業者は同じ、継続で、定員とか事業の内容が増えるわけだから、それに対応するだけの契約金額の算定というのは改めて行われるのですかということも伺ったと思うのですけれども。","respondent":"佐藤障害者施策推進課長","answer":"運営事業者につきましては、移転先で同じ事業者で行うかどうかはまだ決定しておりませんので、そこについても相談、検討というような形です。ただ、受入れも含めて事業としては拡大というところになりますので、それなりの対応の予算をつけていくことになるかとは思います。","voiceIndex":167,"id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問","question":"それと、理由のところに令和７年度に心身障害者福祉会館のエレベーターの更新予定ということであるのですけれども、これはエレベーターの改修となると心身障害者福祉会館を一定休んでエレベーターを設置するということになるのでしょうか、そこら辺のところはどのように進められるのかも教えてください。","respondent":"松山障害者支援課長","answer":"無駄になるというご指摘ですが、施設整備課に確認しましたところ、今年度実施予定のエレベーター改修設計委託では、昨年度実施した耐火クロススクリーン設置工事を除き、既存不適格解消のための改修計画を検討いたしますので。","voiceIndex":170,"id":"exchange-066"},{"speaker":"鈴木委員","kind":"確認","question":"１８歳の壁というのは厚生委員会で議会報告会をやったときに発表されてみんなの認識になったわけですけれども、それに対して時間延長の補助金の制度がつくられて、一人一人の実情に合わせて全ての方が対応されているということが確認されて、よかったなと思っています。それから、あとは耐火クロススクリーンは無駄にならないということで確認させていただきました。","respondent":"佐藤障害者施策推進課長","answer":"こちらについては、就労継続支援Ｂ型とかそういった形ではなく、昨今、超短時間雇用とかそういった就労事業を進めるに当たって。","voiceIndex":172,"id":"exchange-067"},{"speaker":"吉田委員","kind":"確認","question":"今のリボン跡地の就労支援事業で、障害者総合支援法に基づく支援事業ではないということは、要するに就労継続支援Ａ型とかＢ型とかは、何という言い方が正しいのだろう、工賃と言うのでしょうか、国からお金が入ってくるわけです。それだとなかなか厳しいのではないかなと思うのです、働いている人にとっては。それがどうなのかなということを確認したいのです。","respondent":"佐藤障害者施策推進課長","answer":"そこに勤める障害のある方をサポートするスタッフ等については、当然区の事業ということですので、そちらの予算で対応するような形での事業の組立てということで予定しております。","voiceIndex":175,"id":"exchange-068"},{"speaker":"吉田委員","kind":"確認","question":"それで一番気になったのは、訓練とはいえそこで働くわけだから、一定こういうように頑張って働くと、少しでもそういう報酬が得られるのだよというのも一つの社会的な体験になるのではないかと思うのですけれども、あくまでこれは訓練だからと、次に行くための訓練だからということだけなのかなと、その辺をもう一度、ごめんなさい、確認させてください。","respondent":"佐藤障害者施策推進課長","answer":"本事業につきましては、訓練というよりは、就労につきまして、障害のある方が一般就労もしくは就労継続支援Ａ型・Ｂ型も含めまして就労に就いたときにうまくいかなかったりとか、こういったことがうまくできないとかそういったところが出てくることも踏まえまして。","voiceIndex":177,"id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどピッコロの増員、定員増のお話もあったと思うのですけれども、結構品川区の重度心身障害の日中支援というのは割とピッコロに集中しているのではないかなと思ったりもするのですけれども、その辺の受け止めはいかがですか。","respondent":"松山障害者支援課長","answer":"医療的ケアの方もいらっしゃいますけれども、割合としては、ピッコロは６人全員医療的ケアが必要な方ということになります。心身障害者福祉会館については、１日２名程度の医療的ケアが必要な方が通っている施設になります。","voiceIndex":180,"id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"確認","question":"現在ピッコロは６名ということで、増員は２０名でよろしいのでしょうか、確認で増員予定を。","respondent":"佐藤障害者施策推進課長","answer":"今のところ２０名ということで、区として整備を進めているところです。","voiceIndex":182,"id":"exchange-071"},{"speaker":"えのした副委員長","kind":"質問","question":"本日結論を出すで、不採択。理事者のご答弁のとおりでグループホームを２か所整備していますし、今のピッコロ、重症心身障害者通所事業所は小山台住宅跡地に拡充という、障害者福祉施設でしょうか、拡充するということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-072"},{"speaker":"大倉委員","kind":"意見","question":"理由としては、様々今も検討されていて、今までのお話の中でも様々バランスも考えながら、民間の活用などもいろいろと検討を重ねながら、最終的には改築も視野に入れているというところでありますので、１８歳の壁をなくすためというところで施設整備が直ちに解決につながるかどうかというところが、ご答弁でもありましたが全体的に改築を進めているというところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。先ほどのやり取りの中で確認をさせていただきましたが、障害者施設、通所施設も含めて、それから心身障害者福祉会館の設備の更新も含めて今計画にのっとって行っているということでしたので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"意見","question":"本日結論を出すということで、趣旨採択でお願いしたいと思います。障害者福祉については、この間、改善がされてきていると思っています。でも、まだまだ様々障害者施設の整備というのは進めることが必要だと思っていますので、趣旨採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"露骨には言われないのですけれども、私の場合は少しやんわりとした感じですが、「品川区は財政が豊かなのだから、自分の所で施設を造るべきなのではないのか」と、それは、これはほかのところの非難になってしまうかもしれないですけれども、障害者の方たちのお声が小さ過ぎるのではないか、もっと区にどんどん要望を出すべきなのではないかということも、私のところにはほかの区の方から声が届いています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"確認","question":"本日結論を出すで、趣旨採択でお願いいたします。区としても様々な取組をしていただいているというのは確認ができました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7099#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":62180,"voices":200}}]);
